    Text = "Mãi mãi theo đuổi lý tưởng, theo đuổi ánh sáng, theo đuổi hy vọng. \n Dù cái giá phải trả là hy sinh chính mình. \n Ôi Chúa, tôi chỉ hy vọng rằng con đường mà tôi đang kiên định bước tới, là con đường chính mà Ngài dẫn dắt."
  },
  Stage_122179_Name = {
    Text = "Lấy bản thân làm hiến tế"
  },
  Stage_122180_Desc = {
    Text = "Dùng tư duy để phân tích tư duy, vẫn sẽ bị tư duy chi phối. \n Hãy giao mọi thứ cho bản năng nào~"
  },
  Stage_122180_Name = {
    Text = "Suy nghĩ bản năng · thứ ba"
  },
  Stage_122181_Desc = {
    Text = "Dùng tư duy để phân tích tư duy, vẫn sẽ bị tư duy chi phối. \n Hãy giao mọi thứ cho bản năng nào~"
  },
  Stage_122181_Name = {
    Text = "Suy nghĩ bản năng·thứ tư"
  },
  Stage_122182_Desc = {
    Text = "Những điều mới mẻ thường đứng vững trên đống đổ nát của những điều cổ xưa. \n Vì vậy, hãy đập tan trái tim cổ hũ và tẻ nhạt đó đi!"
  },
  Stage_122182_Name = {
    Text = "Đập vỡ trái tim · điên cuồng"
  },
  Stage_122183_Desc = {
    Text = "Ngôn từ mang theo sức mạnh, nếu kiểm soát được ngôn từ, có phải là kiểm soát được sức mạnh không? \n Để tôi thử xem…… Ôi! Thật là hữu dụng!"
  },
  Stage_122183_Name = {
    Text = "Kiểm soát ngôn ngữ · điên cuồng"
  },
  Stage_122184_Desc = {
    Text = "Ngôn từ mang theo sức mạnh, nếu kiểm soát được ngôn từ, có phải là kiểm soát được sức mạnh không? \n Để tôi thử xem…… Ôi! Thật là hữu dụng!"
  },
  Stage_122184_Name = {
    Text = "Kiểm soát ngôn từ·số sáu"
  },
  Stage_122185_Desc = {
    Text = "Cuộc sống bình thường giống như cái ruột thừa vô dụng, đã đến lúc phải cắt bỏ rồi~"
  },
  Stage_122185_Name = {
    Text = "Cắt ruột thừa·phần sáu"
  },
  Stage_122186_Desc = {
    Text = "Cuộc sống bình thường giống như cái ruột thừa vô dụng, đã đến lúc phải cắt bỏ rồi~"
  },
  Stage_122186_Name = {
    Text = "Cắt ruột thừa·thứ nhất"
  },
  Stage_122601_Name = {
    Text = "Mộc Hạ màn chơi thử nghiệm"
  },
  Stage_123112_Desc = {
    Text = "Sương mù che khuất đôi mắt tôi, khiến tôi mất liên lạc với thế giới của chính mình, nhưng qua đôi mắt của bạn, tôi nhìn thấy những quá khứ không thể trở lại, những người không bao giờ có thể gặp lại. \nChúng ta thật giống nhau."
  },
  Stage_123112_Name = {
    Text = "Xuyên qua đôi mắt của bạn"
  },
  Stage_123113_Desc = {
    Text = "Sương mù che khuất đôi mắt tôi, khiến tôi mất liên lạc với thế giới của chính mình, nhưng qua đôi mắt của bạn, tôi nhìn thấy những quá khứ không thể trở lại, những người không bao giờ có thể gặp lại. \nChúng ta thật giống nhau."
  },
  Stage_123113_Name = {
    Text = "Xuyên qua đôi mắt của bạn"
  },
  Stage_125199_Desc = {
    Text = "Chỉ có những sinh vật đam mê tình yêu mới trở nên mong manh, kiên cường, buồn cười, nhưng cũng thật phi thường. \nÔi, hãy cùng ta đi xem những điều tuyệt vời hơn nhé, các ngươi sẽ hỗ trợ lẫn nhau, từ nay sẽ gắn bó chặt chẽ."
  },
  Stage_125199_Name = {
    Text = "Rối rắm·thứ ba"
  },
  Stage_125200_Desc = {
    Text = "Cảm xúc mãnh liệt cuối cùng cũng có nơi trở về, không phải lúc nào cũng là về bên nhau đến già, mà có lẽ nhiều hơn là về cái chết vô nghĩa. \n Đôi khi cái chết vô nghĩa là tình yêu, đôi khi cái chết vô nghĩa là bạn."
  },
  Stage_125200_Name = {
    Text = "Vong mạng·Điên rồ"
  },
  Stage_125201_Desc = {
    Text = "Tình cũ đã rời bỏ bạn, tại sao bây giờ bạn mới bắt đầu hối hận?\nHaha, không muộn, không vội, nhìn đi—— chàng ơi. Chỉ cần mặt trời lặn, mỗi ngọn đèn, mỗi cây nến đỏ, sẽ phản chiếu hình bóng của cô ấy ở sau cửa sổ."
  },
  Stage_125201_Name = {
    Text = "Phản ánh sau cửa sổ·thứ hai"
  },
  Stage_125202_Desc = {
    Text = "\"... Như ve sầu rụng vỏ đổi xương, gọi là thi giải mà thăng tiên...\"\nÔi, thực ra không phải, đó là một đoạn chuyện hoang đường, nhưng có sao đâu? Họ dùng máu và nước mắt ước nguyện, vì vậy cái đẹp đáng sợ và nỗi kinh hoàng từ đó tái sinh."
  },
  Stage_125202_Name = {
    Text = "Xác giải·sáu"
  },
  Stage_125203_Desc = {
    Text = "Tình cũ đã rời bỏ bạn, tại sao bây giờ bạn mới bắt đầu hối hận?\nHaha, không muộn, không vội, nhìn đi—— chàng ơi. Chỉ cần mặt trời lặn, mỗi ngọn đèn, mỗi cây nến đỏ, sẽ phản chiếu hình bóng của cô ấy ở sau cửa sổ."
  },
  Stage_125203_Name = {
    Text = "Phản ánh sau cửa sổ·một"
  },
  Stage_125204_Desc = {
    Text = "Họ cùng quỳ dưới bàn thờ, vị thần nữ vô hình không thể bị khám phá, không thể định nghĩa, không thể chống lại. \n Dâng hiến tất cả, tuân theo tất cả, đạt đến cảnh giới cực lạc duy nhất, hỗn loạn vĩnh cửu."
  },
  Stage_125204_Name = {
    Text = "Cực lạc · điên rồ"
  },
  Stage_125205_Desc = {
    Text = "Ta thích mùi hương của bạn, ta sẽ thay bạn nếm thử kẻ thù của bạn."
  },
  Stage_125205_Name = {
    Text = "Theo hương·thứ hai"
  },
  Stage_125206_Desc = {
    Text = "Hội bí ẩn đó lẩn khuất bên ngoài những cuốn sử của quốc gia cổ đại phương Đông, nó không thể bị khám phá, không thể bị định nghĩa, chỉ có rất ít cá thể đến nay vẫn chưa biến mất, vĩnh viễn cư trú trong vùng đất không có giấc mơ, từng biết đến danh tính của vị thần mà họ thờ phụng. \n Cô ấy được gọi là——\"@4\""
  },
  Stage_125206_Name = {
    Text = "Sự phì nhiêu·một trong"
  },
  Stage_125207_Desc = {
    Text = "Họ cùng quỳ dưới bàn thờ, vị thần nữ vô hình không thể bị khám phá, không thể định nghĩa, không thể chống lại. \n Dâng hiến tất cả, tuân theo tất cả, đạt đến cảnh giới cực lạc duy nhất, hỗn loạn vĩnh cửu."
  },
  Stage_125207_Name = {
    Text = "Cực lạc · sáu"
  },
  Stage_125208_Desc = {
    Text = "Khà la——xì lầu——gù jiū——hứ——\nChúng ta sẽ mãi mãi bên nhau, chúng ta sẽ mãi mãi bên nhau.\nChúng ta sẽ mãi mãi mãi mãi bên nhau bên nhau bên nhau bên nhau bên nhau bên nhau bên nhau bên nhau bên nhau@4"
