  },
  Stage_125656_Name = {
    Text = "Khán giả, diễn viên, tác giả"
  },
  Stage_125657_Desc = {
    Text = "Hình phạt khổ đau hơn cả gai nhọn và lửa thiêu."
  },
  Stage_125657_Name = {
    Text = "Xiềng xích dịu dàng"
  },
  Stage_125658_Desc = {
    Text = "Vũ điệu đẹp nhất, mãi mãi nở rộ giữa cái chết và sự tan vỡ."
  },
  Stage_125658_Name = {
    Text = "Thiên nga bay"
  },
  Stage_125659_Desc = {
    Text = "90 phút nửa đêm, 15 inch mặt nạ, 10 gallon mộng cảnh, 2 ounce rượu — công thức duy nhất của hạnh phúc."
  },
  Stage_125659_Name = {
    Text = "Bữa tiệc mặt nạ"
  },
  Stage_125660_Desc = {
    Text = "Trang viên Kadelin say mê chứng kiến những vở kịch huy hoàng và suy tàn. Chỉ những ai biết cách làm hài lòng trang viên mới nhận được thiệp mời."
  },
  Stage_125660_Name = {
    Text = "Lời mời đến biệt thự"
  },
  Stage_125661_Desc = {
    Text = "Diễn viên lên sân khấu, tác giả không rõ."
  },
  Stage_125661_Name = {
    Text = "Màn thứ hai"
  },
  Stage_125662_Desc = {
    Text = "Cơn bão bên kia đại dương, thực ra chưa bao giờ liên quan đến sự lựa chọn của con bướm."
  },
  Stage_125662_Name = {
    Text = "Súng đạn"
  },
  Stage_125663_Desc = {
    Text = "Lồng giam bất tử, do chính tù nhân tự tay dệt nên.\nHọ mãi mãi dệt. Họ chưa bao giờ thoát ra."
  },
  Stage_125663_Name = {Text = "Kén"},
  Stage_126202_Desc = {
    Text = "Hoa tươi, hoan hô, tiếng vỗ tay. Thế giới trở lại bên nó.\nNhà ảo thuật tự sự đã hoàn thành màn biểu diễn, ký ức của khán giả tan biến trong lễ chào kết thanh nhã.\nKhông bí mật nào có thể rời khỏi đống đổ nát của sân khấu."
  },
  Stage_126202_Name = {
    Text = "Xin đừng spoil·Phần bốn"
  },
  Stage_126203_Desc = {
    Text = "Hãy đón nhận, cao trào của câu chuyện! Mọi phục bút đều là nhiên liệu, mọi sự chuẩn bị, đều là để thắp sáng khoảnh khắc này của sân khấu."
  },
  Stage_126203_Name = {
    Text = "Bùng cháy·Phần bốn"
