  Stage_129163_Name = {
    Text = "Tàu hỏa hạnh phúc lao nhanh·Bình thường"
  },
  Stage_129164_Name = {
    Text = "Tàu hỏa hạnh phúc lao nhanh·khó khăn"
  },
  Stage_129165_Name = {
    Text = "Tàu hỏa hạnh phúc lao nhanh·Điên rồ"
  },
  Stage_129500_Desc = {
    Text = "Mỗi lễ cầu năm của Quốc gia Bàn Long, bất kể ở phương trời nào, nhà nhà đều phải đoàn viên. \n Họ lên chuyến tàu đến phương xa khi lễ cầu năm sắp đến, ôm ấp trái tim đầy mơ mộng chờ đợi khoảnh khắc tái ngộ sau thời gian dài xa cách."
  },
  Stage_129500_Name = {
    Text = "Tàu cầu năm"
  },
  Stage_129501_Desc = {
    Text = "Đừng sợ hãi, đây chỉ là một trò chơi. \n Một trò chơi tàn nhẫn và xấu xa."
  },
  Stage_129501_Name = {
    Text = "Trò chơi bắt đầu"
  },
  Stage_129502_Desc = {
    Text = "Đừng dừng lại, đừng lùi bước. \nNếu những người tốt bụng bỏ súng trong tay, thì cái ác sẽ tiếp tục truy đuổi."
  },
  Stage_129502_Name = {
    Text = "Người chết thứ hai"
  },
  Stage_129503_Desc = {
    Text = "Đây là phản công tuyệt địa thuộc về công lý…à?"
  },
  Stage_129503_Name = {
    Text = "Chiêu thức ẩn"
  },
  Stage_129504_Desc = {
    Text = "Cái cần kéo đó thường xuất hiện trong giấc mơ của bạn.\nĐẩy nó hay kéo xuống, đó là một câu hỏi."
  },
  Stage_129504_Name = {
    Text = "Phòng tối thường trực"
  },
  Stage_129505_Desc = {
    Text = "Lửa trại nối tiếp tiễn biệt năm cũ, những ngày xưa đã chìm vào tro tàn không thể tìm lại."
  },
  Stage_129505_Name = {
    Text = "Lửa trại của những ngày xưa"
  },
  Stage_130109_Desc = {
    Text = "Con người phải đi học, Thể Thức Tỉnh cũng phải đi học.\nBây giờ cô ấy là Thể Thức Tỉnh, tất nhiên cô ấy cũng phải đi học.\nXin hãy chú ý an toàn."
  },
  Stage_130109_Name = {
    Text = "Trường học·thứ hai"
  },
  Stage_130110_Desc = {
    Text = "Làm sao để trở thành điều tra viên huyền thoại? Trước hết, mỗi miệng giếng sâu đều ẩn giấu vô vàn bí mật.\nThứ hai, trước khi xông vào đáy giếng, hãy nhớ rằng súng săn không nhất thiết phải sở hữu hợp pháp."
  },
  Stage_130110_Name = {
    Text = "Giếng nước· sáu"
  },
  Stage_130111_Desc = {
    Text = "Làm sao để trở thành điều tra viên huyền thoại? Trước hết, mỗi miệng giếng sâu đều ẩn giấu vô vàn bí mật.\nThứ hai, trước khi xông vào đáy giếng, hãy nhớ rằng súng săn không nhất thiết phải sở hữu hợp pháp."
  },
  Stage_130111_Name = {
    Text = "Giếng nước·thứ hai"
  },
  Stage_130112_Desc = {
    Text = "Đúng vậy, dù là điều tra viên huyền thoại, cũng chưa chắc lần nào cũng giành được chiến thắng.\n……Nhưng không sao, vodka vẫn còn giọt cuối cùng."
  },
  Stage_130112_Name = {
    Text = "Chén rượu cuối cùng·bốn"
  },
  Stage_130113_Desc = {
    Text = "Những người yêu nhau cùng dùng bữa tối, thổ lộ tâm tư với nhau.\nThức ăn đã nghe được biết bao bí mật, nhưng dĩ nhiên, chúng chẳng bao giờ lên tiếng."
  },
  Stage_130113_Name = {
    Text = "Bàn ăn·bốn"
  },
  Stage_130114_Desc = {
    Text = "Con người phải đi học, Thể Thức Tỉnh cũng phải đi học.\nBây giờ cô ấy là Thể Thức Tỉnh, tất nhiên cô ấy cũng phải đi học.\nXin hãy chú ý an toàn."
