  },
  Stage_141235_Desc = {
    Text = "Bạn thích chơi trò chơi, Bạn xem mọi thứ như một trò hề. Vì vậy chúng ta sẽ cắt cổ những Tín đồ đó, nghiền nát xương sống của chúng, để chúng biết mình đang tin vào thứ rác rưởi ngu ngốc và lố bịch đến mức nào.\nCứ chạy trốn đi, nếu không, Bạn sẽ phát hiện ra rằng ngay cả Sự diệt vong Chỉ là ảo tưởng tuyệt vời mà thôi."
  },
  Stage_141235_Name = {
    Text = "Trò Chơi Đuổi Bắt· một trong"
  },
  Stage_141236_Desc = {
    Text = "Dễ lấy, ngon miệng, chắc chắn, chặt chẽ, ngạt thở.\nMong manh.\nNó tồn tại ngay tại đây."
  },
  Stage_141236_Name = {
    Text = "Sụn Sườn· sáu"
  },
  Stage_141237_Desc = {
    Text = "Đúng vậy, tất nhiên tôi biết.\nTừ đầu đến cuối, Chỉ có \"Tôi\", không có \"Chúng ta\"."
  },
  Stage_141237_Name = {
    Text = "Thú Nhận·Điên rồ"
  },
  Stage_141238_Desc = {
    Text = "Lập trường của thợ săn và con mồi thường xuyên hoán đổi trong chớp mắt, qua hàng nghìn năm, Vòng lặp đi lặp lại, cho đến khi một bên học được cách sử dụng công cụ, cho đến khi một bên nắm giữ được Sức mạnh thực sự."
  },
  Stage_141238_Name = {
    Text = "Luật Rừng· năm"
  },
  Stage_141239_Desc = {
    Text = "Anh ta được chọn bởi một sự tồn tại cổ xưa hơn cả biển, anh ta ở lại nơi mà anh ta không thể quay trở về."
  },
  Stage_141239_Name = {
    Text = "Tiếng Còi· sáu"
  },
  Stage_141240_Desc = {
    Text = "Món ăn náo nhiệt nhất, món ăn thích hợp nhất để ăn mừng, chúng ta nâng ly, chúng ta sum họp.\nKhông ai quan tâm liệu bên dưới những thân xác kia có phải là cùng một ý chí hay không, không ai quan tâm bên dưới những vỏ rỗng kia còn có linh hồn hay không."
  },
  Stage_141240_Name = {
    Text = "Bia Và Gia Vị·bốn"
  },
