  Stage_141287_Name = {
    Text = "Thú Nhận·bốn"
  },
  Stage_141288_Desc = {
    Text = "Anh ta được chọn bởi một sự tồn tại cổ xưa hơn cả biển, anh ta ở lại nơi mà anh ta không thể quay trở về."
  },
  Stage_141288_Name = {
    Text = "Tiếng Còi· thứ ba"
  },
  Stage_141289_Desc = {
    Text = "Ngài khó nhận ra, Ngài lặng lẽ không tiếng động, Ngài đến bất ngờ.\nMọi người trong những ngày tháng tươi đẹp vô tư nhắc đến tên Ngài, cho đến khi họ nhận ra, Ngài đã trở thành người bạn đồng hành như bóng với hình.\n"
  },
  Stage_141289_Name = {
    Text = "Nguyên Nhân"
  },
  Stage_141290_Desc = {
    Text = "Món ăn náo nhiệt nhất, món ăn thích hợp nhất để ăn mừng, chúng ta nâng ly, chúng ta sum họp.\nKhông ai quan tâm liệu bên dưới những thân xác kia có phải là cùng một ý chí hay không, không ai quan tâm bên dưới những vỏ rỗng kia còn có linh hồn hay không."
