  Stage_146229_Desc = {
    Text = "Người vào tiệc đã đủ mặt, Thần Minh đang ngủ say cuối cùng cũng cất tiếng cười.\nCác bạn chưa bao giờ là những vị khách đến dự tiệc."
  },
  Stage_146229_Name = {
    Text = "Người Trong Tiệc"
  },
  Stage_146230_Desc = {
    Text = "Núi tuyết Chỉ có một quy tắc: dù Bạn nghe thấy gì, Đừng Trả Lời."
  },
  Stage_146230_Name = {
    Text = "Đừng Trả Lời"
  },
  Stage_146231_Desc = {
    Text = "Bảy lễ vật, bảy bệ đỡ, một cánh cửa dẫn đến nguồn gốc của thế giới.\nƯớc nguyện chưa bao giờ là món quà miễn phí."
  },
  Stage_146231_Name = {
    Text = "Đỉnh Nhọn Vô Nguyện"
  },
  Stage_146232_Desc = {
    Text = "Con chim cuối cùng cũng tìm lại được con chim kia.\nHôm nay lên đường, không hỏi ngày về."
  },
  Stage_146232_Name = {
    Text = "Chim Bay Xa Hôm Nay"
  },
  Stage_146233_Desc = {
    Text = "Mặt hồ trong vắt phản chiếu bầu trời sao, cũng phản chiếu những khao khát không muốn được thừa nhận.\nLời nói dối bị ném vào lửa, thứ còn lại chưa chắc đã là Sự thật."
  },
  Stage_146233_Name = {
    Text = "Vầng Trăng Chưa Đóng Băng"
  },
  Stage_146234_Desc = {
    Text = "Theo truyền thuyết, Diêm Vương dặn dò Orpheus, tuyệt đối đừng quay đầu, quay đầu thì mất vợ mãi mãi.\nNhưng nếu anh ta nỡ lòng làm ngơ trước tiếng Gọi của người yêu, thì làm sao anh ta lại vì khổ công tìm kiếm nàng, ôm đàn vượt sông chết, băng qua thung lũng u tối, bước vào cõi âm tối tăm?"
  },
  Stage_146234_Name = {
    Text = "Ngược Chiều"
  },
  Stage_146235_Desc = {
    Text = "Tuyết gió bịt kín lối về, cũng mang đến Một vị lữ hành xa lạ.\nTrong sâu thẳm bóng tối có tiếng xào xạc, Dường như cả ngọn núi tuyết đang Nhìn lén những người lạc bước vào đó."
  },
  Stage_146235_Name = {
    Text = "Hành Khách Thứ Bảy"
  },
  Stage_146236_Desc = {
    Text = "Người đồng hành cũng là Người Tiên Phong, Cô ấy đến đường tuyết sơn trước Bạn.\nHãy đối mặt đi, từ Bắt đầu, đó đã là sự tồn tại không thể thoát khỏi."
  },
  Stage_146236_Name = {
    Text = "Người Tiên Phong"
  },
  Stage_146237_Desc = {
    Text = "Áo choàng bị gió tuyết tốc lên, bí mật ẩn giấu bấy lâu cuối cùng cũng Vỗ Cánh.\nCó những Cánh sinh ra vốn không phải để bay."
  },
  Stage_146237_Name = {
    Text = "Ngày Rời Tổ"
  },
  Stage_146238_Desc = {
    Text = "Tuyết gió bịt kín lối về, cũng mang đến Một vị lữ hành xa lạ.\nTrong sâu thẳm bóng tối có tiếng xào xạc, Dường như cả ngọn núi tuyết đang Nhìn lén những người lạc bước vào đó."
  },
  Stage_146238_Name = {
    Text = "Hành Khách Thứ Bảy"
  },
  Stage_146239_Desc = {
    Text = "Người ta kiểm đếm thức ăn, nhiên liệu, dây thừng và oxy, nhưng chẳng ai cân đo những ước nguyện giấu trong Hành Lý."
  },
  Stage_146239_Name = {Text = "Hành Lý"},
  Stage_146240_Desc = {
    Text = "Ánh lửa soi rõ khuôn mặt mọi người, cũng soi rõ những ước nguyện mà họ ôm ấp trong lòng.\nKhi đêm dài chưa tàn, hãy để chúng ta tận hưởng thêm một giấc ngủ yên."
  },
  Stage_146240_Name = {
    Text = "Chuyện Trò Bên Lò Sưởi"
  },
  Stage_146241_Desc = {
    Text = "Đừng bước vào Đêm Lành đó một cách nhẹ nhàng."
