  Stage_146928_Desc = {
    Text = "Công chúa lâm nạn được hiệp sĩ giải cứu, đây là câu chuyện truyền thống ai ai cũng biết."
  },
  Stage_146928_Name = {
    Text = "Công chúa"
  },
  Stage_146929_Desc = {
    Text = "Rồng thức giấc, hận thù một lần nữa trỗi dậy. Hơi thở của dã thú phun trào từ trong đá, nọc độc chiến tranh bùng cháy dữ dội, đến nay vẫn chưa tắt.\nMặt đất vang lên tiếng sấm rền."
  },
  Stage_146929_Name = {
    Text = "Hang Rồng"
  },
  Stage_146930_Desc = {
    Text = "Hiệp sĩ bước lên con đường xa lạ, đi qua những cánh đồng hoang vu và đồi núi, chỉ có bóng mình làm bạn đồng hành.\nCó lẽ chàng đã chết từ lâu, nhưng không ai làm chứng, nên cũng đành quên đi.\nThế giới im lặng đến vậy."
  },
  Stage_146930_Name = {
    Text = "Mộ Phần"
  },
  Stage_146931_Desc = {
    Text = "Mưa lớn đổ xuống mặt đất suốt bốn mươi ngày đêm, chúng ta không thể tiếp tục, nhưng chúng ta vẫn sẽ tiếp tục."
  },
  Stage_146931_Name = {
    Text = "Đảo Táo"
  },
  Stage_146932_Desc = {
    Text = "Rồng thức giấc, hận thù một lần nữa trỗi dậy. Hơi thở của dã thú phun trào từ trong đá, nọc độc chiến tranh bùng cháy dữ dội, đến nay vẫn chưa tắt.\nMặt đất vang lên tiếng sấm rền."
  },
  Stage_146932_Name = {
    Text = "Hang Rồng"
  },
  Stage_146933_Desc = {
    Text = "Đó là rễ và hoa của vườn thiên đường, là vương miện của mọi ước nguyện trần thế, sự sung túc không bao giờ cạn kiệt.\nHãy uống cạn chén rượu đi, ngươi sẽ thấy điều mình khao khát nhất."
  },
  Stage_146933_Name = {
    Text = "Chén Thánh"
  },
  Stage_146934_Desc = {
    Text = "Rồng thức giấc, hận thù một lần nữa trỗi dậy. Hơi thở của dã thú phun trào từ trong đá, nọc độc chiến tranh bùng cháy dữ dội, đến nay vẫn chưa tắt.\nMặt đất vang lên tiếng sấm rền."
  },
  Stage_146934_Name = {
    Text = "Hang Rồng"
  },
