  Stage_20089_Desc = {
    Text = "Cô ấy đã thực hiện lời hứa của mình, cuối cùng các bạn có thể về nhà cùng nhau rồi."
  },
  Stage_20089_Name = {
    Text = "Đầu Vàng"
  },
  Stage_20090_Desc = {
    Text = "Triển lãm salon là sự kiện nghệ thuật quan trọng nhất của Tây Đài. \nTại đây, những người vô danh khao khát thành công, những người đã thành danh khao khát bất diệt."
  },
  Stage_20090_Name = {
    Text = "Cái chết của thiếu nữ san hô"
  },
  Stage_20091_Desc = {
    Text = "Câu trả lời nằm giữa biển cả."
  },
  Stage_20091_Name = {
    Text = "Giữa lòng biển"
  },
  Stage_20092_Desc = {
    Text = "Ernst Claudel từng là chúa tể của Besançon. \nĐến ngày nay, gia đình này vẫn có tiếng tăm ở địa phương."
  },
  Stage_20092_Name = {
    Text = "Đọc thư như gặp người thân"
  },
  Stage_20426_Desc = {
    Text = "Kết cục cuối cùng đã được định sẵn, dù bạn hay cô ấy có cố gắng thế nào, quá khứ vẫn không thể thay đổi."
  },
  Stage_20426_Name = {
    Text = "Kết thúc rực rỡ"
  },
  Stage_20427_Desc = {
    Text = "Giấc mơ không bao giờ tuyệt vời mãi, cũng như những bài ca đẹp đẽ không bao giờ mãi vang lên."
  },
  Stage_20427_Name = {
    Text = "Khúc tàn người tản"
  },
  Stage_20428_Desc = {
    Text = "Vua bị giam cầm trong ngai vàng cao vời. \n Thế giới thay đổi, chỉ có nỗi buồn của ông luôn mãi như xưa."
  },
  Stage_20428_Name = {
    Text = "Vương quốc của cô ấy"
  },
  Stage_20429_Desc = {
    Text = "Cô ấy lang thang vô định trong những mảnh ký ức. \n Không biết gì, không cảm thấy gì, lặp đi lặp lại……"
  },
  Stage_20429_Name = {
    Text = "Rào cản ký ức"
  },
  Stage_20430_Desc = {
    Text = "Cuối mê cung là gì? Ban ngày, ban đêm, hay hư vô không biên giới? \nCô ấy cần tự tìm câu trả lời."
  },
  Stage_20430_Name = {
    Text = "Tận cùng mê cung"
  },
  Stage_20431_Desc = {
    Text = "Đứa con, nhiều đứa con hơn, dòng dõi không ngừng tiếp nối……\nChúng là người yêu duy nhất của cô ấy."
  },
  Stage_20431_Name = {
    Text = "Cụm ý thức"
  },
  Stage_20432_Desc = {
    Text = "Đừng bao giờ mở cánh cửa không thuộc về bạn, dù chỉ một lần……"
  },
  Stage_20432_Name = {Text = "cửa"},
  Stage_20433_Desc = {
    Text = "Giấc mơ không bao giờ tuyệt vời mãi, cũng như những bài ca đẹp đẽ không bao giờ mãi vang lên."
  },
  Stage_20433_Name = {
    Text = "Khúc tàn người tản"
  },
  Stage_20434_Desc = {
    Text = "Ernst Claudel từng là chúa tể của Besançon. \nĐến ngày nay, gia đình này vẫn có tiếng tăm ở địa phương."
  },
  Stage_20434_Name = {
    Text = "Đọc thư như gặp người thân"
  },
  Stage_20435_Desc = {
    Text = "Anh ấy đã làm tất cả những gì có thể, tiếp theo, hãy để thời gian viết nên những bài ca mới."
  },
  Stage_20435_Name = {
    Text = "Bài ca mới"
  },
  Stage_20436_Desc = {
    Text = "Một ký ức đáng nhớ, hay một giấc mơ không thể quên?"
  },
  Stage_20436_Name = {
    Text = "Sợi tơ quá khứ"
  },
  Stage_20437_Desc = {
    Text = "Đứa con, nhiều đứa con hơn, dòng dõi không ngừng tiếp nối……\nChúng là người yêu duy nhất của cô ấy."
  },
