  },
  Stage_20438_Name = {
    Text = "Khúc tàn người tản"
  },
  Stage_20439_Desc = {
    Text = "Đây là bí mật giữa các ngươi, nó sẽ in dấu trên linh hồn, đồng hành qua muôn đời."
  },
  Stage_20439_Name = {
    Text = "Giấc mơ, hay lý tưởng"
  },
  Stage_20440_Desc = {
    Text = "Thế giới sau vụ nổ chìm trong bóng tối, bạn lang thang trong thế giới tinh thần, không biết điều gì đang chờ đợi bạn và Erika."
  },
  Stage_20440_Name = {
    Text = "Giọng nói cất lên"
  },
  Stage_20441_Desc = {
    Text = "Lại một giấc mơ, lại một đoạn quá khứ —— lần này, bạn thấy Erika có thân hình bằng thịt máu."
  },
  Stage_20441_Name = {
    Text = "Khởi động kiểm tra"
  },
  Stage_20442_Desc = {
