  },
  Stage_20697_Desc = {
    Text = "Mỗi khoảnh khắc đều có một người chết đi, cũng như mỗi khoảnh khắc đều có một người sinh ra. \nChỉ có bóng là khác biệt. Nó bị thời gian tiêu thụ, bị mảnh đất khốn khổ này ràng buộc. \nSống đời đời kiếp kiếp, không chết, không sinh."
  },
  Stage_20697_Name = {
    Text = "Tụng Ca Bóng Tối"
  },
  Stage_20698_Desc = {
    Text = "Thần nói, họ sinh ra đã phải trải qua gian khổ, đổ hết máu. \n Giống như mặt trời vốn dĩ phải mọc, mưa vốn dĩ phải rơi. \n Mọi thứ đều là sự sắp xếp tốt nhất."
  },
  Stage_20698_Name = {
    Text = "Vùng Đất Mưa Sầu"
  },
  Stage_20699_Desc = {
    Text = "Chúng ta tiến lên, để chiến thắng quang vinh. \n Chúng ta sống, để ra đi một cách trọn vẹn."
  },
  Stage_20699_Name = {
    Text = "Đến từ phương xa"
  },
  Stage_20700_Desc = {
    Text = "Nó là sinh vật duy nhất ở đây, mọi thứ nó thấy đều do nó thống trị. \n——Nó là vị vua tối cao."
  },
  Stage_20700_Name = {
    Text = "Vương Quốc Dã Thú"
  },
  Stage_20701_Desc = {
    Text = "Họ vượt qua sinh tử, cách nhau bởi bia mộ mà tái ngộ. \n Mặt dính vào mặt, tay nắm lấy tay, hơi thở mang mùi thối rữa."
  },
  Stage_20701_Name = {
    Text = "Cuộc tái hợp cô đơn"
  },
  Stage_20702_Desc = {
    Text = "Chúng tôi là tập hợp của những sinh vật nhỏ bé, xương và nước mắt. \nĐêm nay chúng tôi tụ họp ở đây, chỉ để chiêm ngưỡng dòng sông rực rỡ với vô số cầu vồng."
  },
  Stage_20702_Name = {
    Text = "Hội Săn Đầu"
  },
  Stage_20703_Desc = {
    Text = "Khi bóng tối lẻn vào đêm tối, giọt nước hòa vào mưa. \nThời khắc săn giết sắp đến…"
  },
