  },
  Stage_22313_Desc = {
    Text = "Dòng nước chảy ngược, ký ức tràn về. \nTất cả mọi thứ trước khi mặt trăng tròn mọc đều mở mắt."
  },
  Stage_22313_Name = {
    Text = "Mở mắt ra"
  },
  Stage_23624_Desc = {
    Text = "Một số người sinh ra đã là đề tài phiêu lưu, một số người khác thì đóng gói bản thân thành một câu chuyện tình yêu đẹp đẽ. \nTuy nhiên, nói cho cùng, mỗi người đều là đạo diễn của chính mình."
  },
  Stage_23624_Name = {
    Text = "Sức mạnh của Andy·Johnson"
  },
  Stage_23625_Desc = {
    Text = "Mỗi người đều giấu một câu chuyện, nhưng không phải ai cũng có mong muốn kể về."
  },
  Stage_23625_Name = {
    Text = "Tìm kiếm câu chuyện"
  },
  Stage_23626_Desc = {
    Text = "Trao đổi vật phẩm, luật tự nhiên không thể chối bỏ."
  },
  Stage_23626_Name = {
    Text = "Sự hào phóng của thương nhân"
  },
  Stage_23627_Desc = {
    Text = "Người nhớ nhất, đã mang lại ước nguyện muốn nói ra nhất."
  },
  Stage_23627_Name = {
    Text = "Người nhớ nhung nhất"
  },
  Stage_23628_Desc = {
    Text = "Bông hoa tuyệt vời nhất, khai sinh ra bài thơ tuyệt đẹp và sâu sắc nhất."
  },
  Stage_23628_Name = {
    Text = "Bông hoa đẹp nhất"
  },
  Stage_23629_Desc = {
    Text = "Kết cục trọn vẹn nhất… có lẽ không phải hoàn hảo, nhưng ít nhất vào thời khắc này, không ai không vui vẻ vì kết cục."
  },
  Stage_23629_Name = {
    Text = "Cái kết viên mãn nhất"
  },
  Stage_23630_Desc = {
    Text = "Khung cảnh huyền ảo nhất, mang theo những ước mơ tốt đẹp nhất."
  },
  Stage_23630_Name = {
