  Stage_24183_Name = {
    Text = "Bà Hồng màn chơi thử nghiệm"
  },
  Stage_24184_Name = {
    Text = "Cánh hoa bùn màn chơi thử nghiệm"
  },
  Stage_24423_Desc = {
    Text = "Mỗi người Lentiennam đều không từ chối một cốc trà nóng vừa pha. \nDù đó là một cốc trà Ô Long lươn."
  },
  Stage_24423_Name = {
    Text = "Đặc chế Cá Mút Đá"
  },
  Stage_24424_Desc = {
    Text = "Mỗi người được số phận chọn đều nghĩ mình là trường hợp ngoại lệ. \nSố phận bỡn cợt xác suất."
  },
  Stage_24424_Name = {
    Text = "Tù nhân của số mệnh"
  },
  Stage_24425_Desc = {
    Text = "Rắc. \nCô thề sẽ cắt đứt hoàn toàn và dứt khoát với cuộc sống quá khứ. \nGiống như dùng kéo cắt một dải ruy băng thành hai đoạn."
  },
  Stage_24425_Name = {
    Text = "Dành tặng Soreil"
  },
  Stage_24426_Desc = {
    Text = "Một lần nữa, bạn trở thành tù nhân của sự đồng cảm, rơi sâu vào linh hồn của cô ấy."
  },
  Stage_24426_Name = {
    Text = "Phán Xét Sụp Đổ"
  },
  Stage_24427_Desc = {
    Text = "Vào đầu câu chuyện, bạn sẽ chứng kiến một cái chết hoành tráng. \nDù là điểm khởi đầu, nhưng nó vẫn chưa phải là kết thúc."
  },
  Stage_24427_Name = {
    Text = "Bài Ca Rượu"
  },
  Stage_24428_Desc = {
    Text = "Cô gái tên là Sorrel, là niềm tự hào của cả làng. \nCô ấy rất ngoan, sạch sẽ, toàn thân màu trắng tuyết, bước những bước nhỏ, giống như những quý cô thực thụ. \nCô gái khác với những quý cô đó —— cô ấy không bao giờ mơ."
  },
  Stage_24429_Desc = {
    Text = "Lôgic giống như rượu, uống quá nhiều sẽ mất đi lợi ích của nó."
  },
  Stage_24429_Name = {
    Text = "Mặt Nạ Hòa Thanh"
  },
  Stage_24430_Desc = {
    Text = "Dưới sự chăm sóc cẩn thận của Ngài, tế bào ung thư mang tên ham muốn quyền lực cuối cùng đã lan rộng như hoa hồng nở rộ."
  },
  Stage_24430_Name = {
    Text = "Lễ Hội Đỏ"
  },
  Stage_24431_Desc = {
    Text = "Xì lầu. xì lầu. \n Chúng ta bò trong bóng tối và thì thầm. \n Thân thể béo tròn để lại những vệt nước mắt cong cong dưới ánh trăng —— mặn mặn đó."
  },
  Stage_24431_Name = {Text = "Trứng"},
  Stage_24432_Desc = {
    Text = "Scone, macaron, và cacao bốc khói…\nƯớc nguyện của cô hầu gái đơn giản: ăn ngon hơn một chút, rồi lại ngon hơn một chút nữa."
  },
  Stage_24432_Name = {
    Text = "Tâm nguyện của thị nữ"
  },
  Stage_24433_Desc = {
    Text = "Cẩn thận, cẩn thận. \nNgười phụ nữ mà các người đang mê mẩn không phải là một quý bà thật sự. \nTuy nhiên, ai quan tâm chứ?"
  },
  Stage_24433_Name = {
    Text = "Cẩm Nang Quý Cô"
  },
  Stage_24434_Desc = {
    Text = "Hoa hồng cúi đầu mảnh mai trong tiếng chuông, kền kền lạc lối giữa những bông hoa tanh hôi. \n Không ai ca hát, không ai kể chuyện. Thế giới nhạt màu vì cái chết của cô ấy."
  },
  Stage_24434_Name = {
    Text = "Đám tang Tường Vi"
  },
  Stage_24435_Desc = {
    Text = "Cô ấy hút cạn suối nước, bóp nghẹt những chú chim ngây thơ. \nCô ấy mang đến làn gió vàng, chúng như những ngôi sao băng vụt qua cánh đồng. \nCô ấy đặt cả thế giới lên ngọn lửa dục vọng, rồi hóa nó thành tro bụi."
  },
  Stage_24435_Name = {
    Text = "Trà Hoa Nữ"
  },
  Stage_24439_Desc = {
    Text = "Cẩn thận, cẩn thận. \nNgười phụ nữ mà các người đang mê mẩn không phải là một quý bà thật sự. \nTuy nhiên, ai quan tâm chứ?"
  },
