  Stage_24444_Desc = {
    Text = "Xì lầu. xì lầu. \n Chúng ta bò trong bóng tối và thì thầm. \n Thân thể béo tròn để lại những vệt nước mắt cong cong dưới ánh trăng —— mặn mặn đó."
  },
  Stage_24444_Name = {Text = "Trứng"},
  Stage_24445_Desc = {
    Text = "Dưới sự chăm sóc cẩn thận của Ngài, tế bào ung thư mang tên ham muốn quyền lực cuối cùng đã lan rộng như hoa hồng nở rộ."
  },
  Stage_24445_Name = {
    Text = "Lễ Hội Đỏ"
  },
  Stage_24446_Desc = {
    Text = "Cô gái tên là Sorrel, là niềm tự hào của cả làng. \nCô ấy rất ngoan, sạch sẽ, toàn thân màu trắng tuyết, bước những bước nhỏ, giống như những quý cô thực thụ. \nCô gái khác với những quý cô đó —— cô ấy không bao giờ mơ."
  },
  Stage_24447_Desc = {
    Text = "Một lần nữa, bạn trở thành tù nhân của sự đồng cảm, rơi sâu vào linh hồn của cô ấy."
  },
  Stage_24447_Name = {
    Text = "Phán Xét Sụp Đổ"
  },
  Stage_24448_Desc = {
    Text = "Một lần nữa, bạn trở thành tù nhân của sự đồng cảm, rơi sâu vào linh hồn của cô ấy."
  },
  Stage_24448_Name = {
    Text = "Phán Xét Sụp Đổ"
  },
  Stage_24449_Desc = {
    Text = "Cô gái tên là Sorrel, là niềm tự hào của cả làng. \nCô ấy rất ngoan, sạch sẽ, toàn thân màu trắng tuyết, bước những bước nhỏ, giống như những quý cô thực thụ. \nCô gái khác với những quý cô đó —— cô ấy không bao giờ mơ."
  },
  Stage_24450_Desc = {
    Text = "Vào đầu câu chuyện, bạn sẽ chứng kiến một cái chết hoành tráng. \nDù là điểm khởi đầu, nhưng nó vẫn chưa phải là kết thúc."
  },
  Stage_24450_Name = {
    Text = "Bài Ca Rượu"
  },
  Stage_24451_Desc = {
    Text = "Scone, macaron, và cacao bốc khói…\nƯớc nguyện của cô hầu gái đơn giản: ăn ngon hơn một chút, rồi lại ngon hơn một chút nữa."
  },
  Stage_24451_Name = {
    Text = "Tâm nguyện của thị nữ"
  },
  Stage_24452_Desc = {
    Text = "Cẩn thận, cẩn thận. \nNgười phụ nữ mà các người đang mê mẩn không phải là một quý bà thật sự. \nTuy nhiên, ai quan tâm chứ?"
  },
  Stage_24452_Name = {
    Text = "Cẩm Nang Quý Cô"
  },
  Stage_24453_Desc = {
    Text = "Dưới sự chăm sóc cẩn thận của Ngài, tế bào ung thư mang tên ham muốn quyền lực cuối cùng đã lan rộng như hoa hồng nở rộ."
  },
  Stage_24453_Name = {
    Text = "Lễ Hội Đỏ"
  },
  Stage_24454_Desc = {
    Text = "Xì lầu. xì lầu. \n Chúng ta bò trong bóng tối và thì thầm. \n Thân thể béo tròn để lại những vệt nước mắt cong cong dưới ánh trăng —— mặn mặn đó."
  },
  Stage_24454_Name = {Text = "Trứng"},
  Stage_24455_Desc = {
    Text = "Mỗi người được số phận chọn đều nghĩ mình là trường hợp ngoại lệ. \nSố phận bỡn cợt xác suất."
  },
  Stage_24455_Name = {
    Text = "Tù nhân của số mệnh"
  },
  Stage_24456_Desc = {
    Text = "Lôgic giống như rượu, uống quá nhiều sẽ mất đi lợi ích của nó."
  },
  Stage_24456_Name = {
    Text = "Mặt Nạ Hòa Thanh"
  },
  Stage_24528_Desc = {
    Text = "Dù điều gì xảy ra hay có bao nhiêu thay đổi, lời kêu gọi của bạn sẽ luôn vang vọng."
  },
  Stage_24528_Name = {
    Text = "Đây không phải vĩnh biệt"
  },
  Stage_24529_Desc = {
    Text = "Một lần, hai lần, ba lần… Sisyphus đẩy tảng đá, leo một cách vô vọng lên ngọn núi không thể vượt qua."
  },
  Stage_24529_Name = {Text = "Sisyphus"},
  Stage_24530_Desc = {
    Text = "Cô gái quen thuộc đã trở nên xa lạ như thế này, người lạnh lùng này… có thật sự là Ramona mà bạn biết không?"
  },
  Stage_24530_Name = {
    Text = "Liều mình một phen"
  },
  Stage_24531_Desc = {
    Text = "Ngày thường, bắt đầu từ một giấc mơ khác thường."
  },
  Stage_24531_Name = {
    Text = "Nước mắt tựa mưa"
  },
  Stage_24532_Desc = {
    Text = "Cô gái quen thuộc đã trở nên xa lạ như thế này, người lạnh lùng này… có thật sự là Ramona mà bạn biết không?"
  },
  Stage_24532_Name = {
    Text = "Liều mình một phen"
  },
  Stage_24533_Desc = {
    Text = "Cô gái quen thuộc đã trở nên xa lạ như thế này, người lạnh lùng này… có thật sự là Ramona mà bạn biết không?"
  },
  Stage_24533_Name = {
    Text = "Liều mình một phen"
  },
  Stage_34716_Desc = {
    Text = "Câu chuyện chuyển biến đột ngột, tình tiết bất ngờ —— Người Giữ Gìn cảm thấy, điều này dường như đang mô tả chính mình đôi khi."
  },
  Stage_34716_Name = {
    Text = "III·Cốt truyện luân chuyển"
  },
  Stage_34717_Desc = {
    Text = "Đây là một từ mà ngay cả Ramona cũng chưa từng nghe qua. Nhờ sự giúp đỡ của một số thân thể được đánh thức lớn tuổi, mọi người cuối cùng mới hiểu được: đôi khi, khóc một trận chính là cách duy nhất để xử lý những cảm xúc tiêu cực."
  },
  Stage_34717_Name = {
    Text = "2·catharsis"
  },
  Stage_34718_Desc = {
    Text = "Sách lý thuyết mà Kassia tìm được viết như sau: Thời gian xảy ra câu chuyện không thể vượt quá một ngày, sân khấu cũng không thể vượt quá một nơi...\nNgười giữ bí mật nghe đến đây thì đã từ bỏ việc tiếp tục đọc. Dù sao, một ngày đôi khi còn không đủ để Người Giữ Gìn hoàn thành bài luận về \"Xử Lý Rỗng và Thảm Họa\" sau giờ học."
  },
  Stage_34718_Name = {
    Text = "I·Ba quy tắc thống nhất"
  },
  Stage_34719_Desc = {
    Text = "Trong cuốn sách lý thuyết mà Kassia tìm thấy có viết: Mô hình kim tự tháp thường tập trung vào việc giải quyết một cuộc khủng hoảng. \nNhưng rất tiếc, không phải mọi cuộc khủng hoảng đều có thể được giải quyết trong thực tế. Chúng bị che giấu dưới lớp bình yên giả tạo, âm thầm phát triển và cuối cùng bùng phát thành những \"kim tự tháp\" mới."
  },
  Stage_34719_Name = {
    Text = "VII·Kim tự tháp sáng tác"
  },
  Stage_34720_Desc = {
    Text = "Tại cuối câu chuyện, cần thể hiện sự phát triển hoặc thay đổi của nhân vật. Tuy nhiên, trong cuộc sống, vòng cung phát triển thường khép lại thành một vòng tròn hoàn chỉnh."
  },
  Stage_34720_Name = {
    Text = "VI·Lý thuyết Hồ Quang"
  },
  Stage_34721_Desc = {
    Text = "Một bối cảnh được sắp đặt trước, vài diễn viên quen thuộc. Còn lại, nhờ vào cảm hứng và sự tương tác."
  },
  Stage_34721_Name = {
    Text = "V·Hài kịch mặt nạ"
  },
  Stage_34722_Desc = {
    Text = "Đừng liên tục ném nội dung vào đầu khán giả, hãy để họ có không gian suy nghĩ, tốt nhất là hoàn toàn yên lặng——thật mong Đóa có thể thành thạo kỹ năng này khi đứng lớp, Người Giữ Gìn thì thầm, và nhận được sự đồng tình của tất cả mọi người."
  },
  Stage_34722_Name = {
    Text = "IV·Khoảnh khắc yên lặng"
  },
  Stage_34912_Desc = {
    Text = "Thiên tai cổ xưa nay đã thức tỉnh----vượt qua ranh giới để tiến vào thực tại, rực cháy giữa đại dương sa đọa mênh mông."
  },
  Stage_34912_Name = {
    Text = "Vùng Cấm - Thảm Họa Phân Giải: Đợt Đầu Tiên: Cảnh Báo Bậc 3"
  },
  Stage_34913_Desc = {
    Text = "Thiên tai cổ xưa nay đã thức tỉnh----vượt qua ranh giới để tiến vào thực tại, rực cháy giữa đại dương sa đọa mênh mông."
