  Stage_35099_Desc = {
    Text = "\"Suỵt... Bạn đoán xem, tôi nhìn thấy gì qua đôi mắt của bạn?\"\nSau khi Ô Ryta bị Người Giữ Gìn làm cho khóc, bức tường thứ tư trong phòng của Người Giữ Gìn suýt bị lơ-tan đẩy đổ. Vì Ô Ryta khóc quá mức, khiến người ta cảm thấy vô cùng hoảng loạn."
  },
  Stage_35099_Name = {
    Text = "IX·Bức tường thứ tư của kịch nghệ"
  },
  Stage_35100_Desc = {
    Text = "\"Đừng để khán giả chìm đắm hoàn toàn vào cốt truyện, hãy để họ phân tích, phê phán những gì đang xảy ra trên sân khấu.\"\nĐối với lý thuyết này, Ô Ryta đánh giá như sau: Ô Ryta không muốn bị ai trách móc! Ô Ryta chỉ muốn trở thành bạn tốt với tất cả mọi người!"
  },
  Stage_35100_Name = {
    Text = "VIII·Hiệu ứng lạ"
  },
  Stage_35129_Desc = {
    Text = "Cô ấy là ranh giới giữa giấc mơ và hiện thực, là phản ánh sâu thẳm trong tâm hồn mỗi linh hồn ngước nhìn bầu trời đêm."
  },
  Stage_35129_Name = {
    Text = "Ngôi sao xoắn"
  },
  Stage_35129_StageInitStateText = {
    Text = "Ác Mộng Biển Sâu"
  },
  Stage_35130_Desc = {
    Text = "Cô ấy đã sẵn sàng."
  },
  Stage_35130_Name = {
    Text = "Ngọn lửa nội hóa"
  },
  Stage_35571_Desc = {
    Text = "Vì bạn là bạn thân của Ô Ryta, nên cô ấy muốn giới thiệu bạn với tất cả bạn bè của mình."
  },
  Stage_35571_Name = {
    Text = "Bộ sưu tập bạn bè"
  },
  Stage_35572_Desc = {
    Text = "Vì bạn là bạn thân của Ô Ryta, nên cô ấy muốn giới thiệu bạn với tất cả bạn bè của mình."
  },
  Stage_35572_Name = {
    Text = "Bộ sưu tập bạn bè"
  },
  Stage_35573_Desc = {
    Text = "Vì bạn là bạn thân của Ô Ryta, nên cô ấy muốn giới thiệu bạn với tất cả bạn bè của mình."
  },
  Stage_35573_Name = {
    Text = "Bộ sưu tập bạn bè"
  },
  Stage_35574_Desc = {
    Text = "Ô Ryta thích bạn, nên muốn bạn trở thành người bạn đồng hành trong cuộc sống hàng ngày của cô ấy."
  },
  Stage_35574_Name = {
    Text = "Ngày tĩnh lặng"
  },
  Stage_35575_Desc = {
    Text = "Vì mọi người đều ở bên cạnh Ô Ryta, nên Ô Ryta hoàn toàn không sợ hãi khi ngủ."
  },
  Stage_35575_Name = {
    Text = "Cung điện dưới nước"
  },
  Stage_35843_Name = {
    Text = "Cô gái biển sâu màn chơi thử nghiệm"
  },
  Stage_35857_Desc = {
    Text = "Các ngôi sao đã đi đến nơi chúng nên đến, giao tiếp với nhau theo một cách vượt ngoài tầm hiểu biết của con người, dệt nên một tấm lưới vô hình, bắt lấy dòng chảy thời gian và năm ánh sáng đã mất."
  },
  Stage_35857_Name = {
    Text = "Vết sao bí ẩn"
  },
  Stage_36125_Desc = {
