  Stage_36614_Desc = {
    Text = "Một lòng phóng túng, buông thả theo dục vọng……\n—— rồi sao?\nsẽ phải chịu hình phạt lửa vĩnh viễn, như một lời cảnh báo.\n—— à."
  },
  Stage_36614_Name = {
    Text = "Đêm của Tử Thần, Rượu Mật và Khúc Ca"
  },
  Stage_36615_Desc = {
    Text = "Bốn cuộc hôn nhân và bốn đám tang——chúng trở thành toàn bộ chú thích cho \"cuộc sống tình cảm\" của Vanda trên thế gian."
  },
  Stage_36615_Name = {
    Text = "Bốn đám cưới"
  },
