  },
  Stage_38793_Desc = {
    Text = "Nữ hoàng và thành phố bất tử của bà —— Isarau. \n Hỡi những đứa con song sinh được vũ trụ sủng ái, các ngươi bị dây rốn của định mệnh nhẹ nhàng cuốn vào. \n Có người nói rằng, nữ hoàng trí tuệ dẫn dắt dân chúng đến Isarau, giống như được mô tả trong \"Sách Khải Huyền\". \n Cũng có người nói rằng, lòng sông Isarau luôn cuồn cuộn chảy, cho đến khi sinh ra nữ hoàng từ đó."
  },
  Stage_38793_Name = {
    Text = "Khải Huyền·Truy Nhớ Chi Nhất"
  },
  Stage_38794_Desc = {
    Text = "Nữ hoàng và thành phố bất tử của bà —— Isarau. \n Hỡi những đứa con song sinh được vũ trụ sủng ái, các ngươi bị dây rốn của định mệnh nhẹ nhàng cuốn vào. \n Có người nói rằng, nữ hoàng trí tuệ dẫn dắt dân chúng đến Isarau, giống như được mô tả trong \"Sách Khải Huyền\". \n Cũng có người nói rằng, lòng sông Isarau luôn cuồn cuộn chảy, cho đến khi sinh ra nữ hoàng từ đó."
  },
