  Stage_38804_Name = {
    Text = "Giếng·Ký Ức Thứ Ba"
  },
  Stage_43506_Desc = {
    Text = "Tạm biệt. Người khổng lồ nói. \n Tôi sẽ trở lại lịch sử, ở đó tôi bất khả chiến bại, vô địch. \n Tôi là vĩnh cửu."
  },
  Stage_43506_Name = {Text = "Kèn chìm"},
  Stage_43508_Desc = {
    Text = "Người bị thời gian quên lãng, bạn muốn hướng về đâu? \n—— Đi đến nơi xa xôi không có gì nương tựa. Nơi đó, sao trăng yên lặng và đại dương im lìm. \nThế giới chỉ còn lại bạn và ta."
  },
  Stage_43508_Name = {
    Text = "Biển Cô Độc"
  },
  Stage_43509_Desc = {
    Text = "Tạm biệt. Người khổng lồ nói. \n Tôi sẽ trở lại lịch sử, ở đó tôi bất khả chiến bại, vô địch. \n Tôi là vĩnh cửu."
  },
  Stage_43509_Name = {Text = "Kèn chìm"},
  Stage_43510_Desc = {
    Text = "Anh hùng và tùy tùng của ông ấy đang điều khiển con tàu trên biển vàng. \nHọ mang những vết sẹo giống nhau, hát cùng một giai điệu, cùng nhau đón chào cái chết và sự tái sinh."
  },
  Stage_43510_Name = {
    Text = "Giai điệu vàng óng"
  },
  Stage_43512_Desc = {
    Text = "Tạm biệt. Người khổng lồ nói. \n Tôi sẽ trở lại lịch sử, ở đó tôi bất khả chiến bại, vô địch. \n Tôi là vĩnh cửu."
  },
  Stage_43512_Name = {Text = "Kèn chìm"},
  Stage_44196_Desc = {
    Text = "Hỡi những kẻ ngu muội, các ngươi đã châm ngòi cho ngọn lửa, thiêu rụi hy vọng và cứu rỗi. \nKhi các ngươi vật lộn trong cái chết tối tăm, cái gọi là công lý ấy có vị ra sao?"
  },
