  Stage_44551_Desc = {
    Text = "Thần Cha nhân từ, xin hãy tha thứ cho con, để con có thể sửa sai, để con có thể bù đắp lỗi lầm của mình."
  },
  Stage_44551_Name = {
    Text = "Sai lầm của chúng tôi"
  },
  Stage_44552_Desc = {
    Text = "Bụi đất đã lắng xuống, những kẻ có tội sẽ bị kết án, những người tiếp tục đi sẽ vẫn tiến lên. \nNgày mai sẽ là một khởi đầu mới."
  },
  Stage_44552_Name = {
    Text = "Thắp lên hy vọng màu trắng"
  },
  Stage_44553_Desc = {
    Text = "Đây vốn là một buổi chiều bình thường, nhưng đối với Người Giữ Gìn của Misaque, cuộc sống thường nhật rõ ràng là một niềm mơ ước xa xỉ."
  },
  Stage_44553_Name = {
    Text = "Hối cải"
  },
  Stage_44554_Desc = {
    Text = "Sạch sẽ, sạch sẽ… Điều này liệu có phải là lời lảm nhảm của một kẻ điên, hay là một niềm tin sai lạc?"
  },
  Stage_44554_Name = {
    Text = "Biểu tượng đẫm máu"
  },
  Stage_44555_Desc = {
    Text = "Họ đã bị ngọn lửa nuốt chửng, hoàn toàn mất lý trí."
  },
  Stage_44555_Name = {
    Text = "Do cơn thịnh nộ điên cuồng"
  },
  Stage_44556_Desc = {
    Text = "Người khác có thì họ cũng phải có, người khác không có thì họ càng phải có —— dù vô nghĩa đến đâu, dù điên rồ đến đâu."
  },
  Stage_44556_Name = {
    Text = "Vì cơn ghen tuông mà giết người"
  },
  Stage_44557_Desc = {
    Text = "Dừng lại đi, thư giãn đi, bạn đã làm việc đủ nhiều rồi; nằm xuống đi, ngủ ngon đi, không ai nỡ trách bạn."
  },
  Stage_44557_Name = {
    Text = "Nhượng bộ sự kiệt quệ"
  },
  Stage_44558_Desc = {
    Text = "Bạn bước đi trong sự kiệt sức, nhưng va phải nanh vuốt đói khát."
  },
  Stage_44558_Name = {
    Text = "Làm đầy bụng đói"
  },
  Stage_44559_Desc = {
    Text = "Trong gương nhìn bạn, liệu đó là một bóng hình ảo hay là dục vọng thực sự?"
  },
  Stage_44559_Name = {
    Text = "Thanhh tẩy tội lỗi"
  },
  Stage_44560_Desc = {
    Text = "Thần Cha nhân từ, xin hãy tha thứ cho con, để con có thể sửa sai, để con có thể bù đắp lỗi lầm của mình."
