  Stage_44715_Name = {
    Text = "Thử cấp độ của Thượng tế Nhân Ái"
  },
  Stage_45411_Desc = {
    Text = "Hôn tôi nhé, tạm biệt."
  },
  Stage_45411_Name = {
    Text = "Nụ hôn tạm biệt"
  },
  Stage_46169_Desc = {
    Text = "Cô ghi nhớ tất cả các xác suất trong tâm trí, nhưng lại bối rối như một sinh viên thần học tại trường kinh viện. \nBởi vì điên rồ không thể dự đoán được, và thật đáng buồn, đó mới chính là trạng thái bình thường của thế giới."
  },
  Stage_46169_Name = {
    Text = "Mãn Quán Định Ước"
  },
  Stage_46170_Desc = {
    Text = "Cô ghi nhớ tất cả các xác suất trong tâm trí, nhưng lại bối rối như một sinh viên thần học tại trường kinh viện. \nBởi vì điên rồ không thể dự đoán được, và thật đáng buồn, đó mới chính là trạng thái bình thường của thế giới."
