  },
  Stage_46171_Name = {
    Text = "Sợi dây nguyền rủa đắng cay"
  },
  Stage_46172_Desc = {
    Text = "Cô gái từng là Mason. \n Không lâu sau, cô sẽ giống như Ulysses, không là ai cả. \n Không lâu sau, cô sẽ là chúng sinh."
  },
  Stage_46172_Name = {Text = "\"nguồn\""},
  Stage_46173_Desc = {
    Text = "Lời nguyền biến bạn thành một con rắn bị giam cầm trong giấc ngủ đông miên vĩnh cửu. \nNó cổ xưa như dây rốn của bạn."
