  },
  Stage_46176_Name = {
    Text = "Sợi dây nguyền rủa đắng cay"
  },
  Stage_46177_Desc = {
    Text = "Cô ghi nhớ tất cả các xác suất trong lòng, nhưng lại bối rối như một sinh viên thần học tại trường kinh viện. \nVì sự điên rồ là điều không thể đoán trước. Thật không may, đó mới là trạng thái bình thường của thế giới."
  },
  Stage_46177_Name = {
    Text = "Mãn Quán Định Ước"
  },
  Stage_46178_Desc = {
    Text = "Cô ấy chứng kiến bản thân sắp chiếm lĩnh thế giới. \n Cô ấy nhìn vào bóng tối dài và hẹp đó, không nói một lời."
  },
  Stage_46178_Name = {
    Text = "Truyện Cổ Tích Bóng Tối"
  },
  Stage_46179_Desc = {
    Text = "Truyện hài của cô ấy là độc nhất vô nhị. Chúng được tạo nên từ bầu trời đêm tĩnh lặng, mặt trăng và những giọt nước mắt."
  },
  Stage_46179_Name = {
    Text = "Chờ đợi hài kịch"
  },
  Stage_46180_Desc = {
    Text = "Khi vạn vật chìm vào giấc ngủ, con rắn sẽ thức dậy. \nKhi mọi thứ sụp đổ, con rắn sẽ trở lại như ban đầu."
  },
  Stage_46180_Name = {
    Text = "Rắn Mất Ngủ"
  },
  Stage_46181_Desc = {
    Text = "Mèo chia cảm xúc của mình thành mười tám phần và phát minh ra các âm điệu khác nhau cho tiếng \"meo meo\"để thể hiện chúng. \nNhư vậy, nó có thể nói \"tôi đói rồi\", \"hãy chơi với tôi đi\", \"đừng làm phiền tôi\". \nNó cũng có thể bày tỏ \"tôi nhớ bạn rồi\"."
  },
  Stage_46181_Name = {
    Text = "Mèo biết mọi thứ"
  },
  Stage_46182_Desc = {
    Text = "Kè theo tiếng chuông cũ kĩ vang lên là hơi thở yếu ớt, không ngừng tan biến của những lời chúc phúc. \nChúc bạn một mùa lễ vui vẻ và hạnh phúc. Chúc bạn một mùa lễ vui vẻ và hạnh phúc. Chúc bạn một mùa lễ vui vẻ và hạnh phúc."
  },
  Stage_46182_Name = {
    Text = "Khúc Fugue Vàng Kim"
  },
