  },
  Stage_51761_Desc = {
    Text = "Lần cuối cùng, cô ngắm nhìn nơi mà tượng của vua từng đứng. \n Nơi đó không có tượng, cũng không có vua."
  },
  Stage_51761_Name = {
    Text = "Mơ về Lemuria"
  },
  Stage_51762_Desc = {
    Text = "Tượng nhìn xa xăm về phía cô. Giữa họ là quãng thời gian dài đằng đẵng và giấc mơ chưa từng tỉnh lại."
  },
  Stage_51762_Name = {
    Text = "Tượng tối"
  },
  Stage_51763_Desc = {
    Text = "Hy vọng, là thứ độc dược quý giá nhất của Lemuria. \nHọ ca hát điên cuồng, coi đó như niềm vui tột độ."
  },
  Stage_51763_Name = {
    Text = "Lễ nghi của linh mục"
  },
  Stage_51764_Desc = {
    Text = "Các ngôi sao, số phận, thần minh… Trước mặt Họ, sự công bằng không đáng một đồng."
  },
  Stage_51764_Name = {
    Text = "Ưu điểm của lời nói dối"
  },
  Stage_51765_Desc = {
    Text = "Đấu tranh trong mưa. chia tay trong mưa."
  },
  Stage_51765_Name = {Text = "Trong mưa"},
  Stage_51766_Desc = {
    Text = "Đáp lại tôi đi, ngài. Tôi sẽ dâng lên ngài món quà quý giá nhất."
  },
  Stage_51766_Name = {
    Text = "Lễ vật của vua"
  },
  Stage_51767_Desc = {
    Text = "Hãy thưởng thức, Người nói. Hãy thưởng thức những tình cảm thấp hèn, hãy thưởng thức số phận đã được chế biến sẵn."
  },
  Stage_51767_Name = {Text = "Thịt cá"},
  Stage_51768_Desc = {
    Text = "Ý chí của Đấng như mạng lưới các vì sao đan xen, Ngài đợi ngươi bước vào cõi mộng giữa hư vô vĩnh hằng."
  },
  Stage_51768_Name = {
    Text = "Cầu nguyện giữa biển sâu"
  },
  Stage_51769_Desc = {
    Text = "Cầu nguyện, điều đầu tiên mà người Lemuria học được chính là."
  },
  Stage_51769_Name = {Text = "Dự ngôn"},
  Stage_51770_Desc = {
    Text = "Trong vùng đất thanh bình và hạnh phúc kia, những người bạn cũ ngày xưa nhìn vào mắt nhau. \nHọ sẽ nắm tay nhau, cùng bước lên bậc thang dẫn lên thiên đường."
  },
  Stage_51770_Name = {
    Text = "Bạn thân"
  },
  Stage_51771_Desc = {
    Text = "Máu. nước mắt. tế lễ. cuồng hoan. giết chóc. \nMột câu chuyện khác về các vì sao lại bắt đầu, nhưng các vì sao không quan tâm. \nChúng tỏa sáng, từ cổ chí kim."
  },
  Stage_51771_Name = {
    Text = "Lắng nghe nào, những ngôi sao trên bầu trời"
  },
  Stage_51772_Desc = {
    Text = "Cô ấy là người bạn tốt nhất của cô ấy. Luôn luôn như vậy."
  },
  Stage_51772_Name = {
    Text = "Người xưa"
  },
  Stage_51773_Desc = {
    Text = "Uống đi, rượu ngon này. Nhảy đi, vũ điệu sôi động này. \n Chủ tế cố quốc bước vào điện, chào đón tín đồ mới của mình."
  },
  Stage_51773_Name = {
    Text = "Yến tiệc máu"
  },
  Stage_51774_Desc = {
    Text = "Sương mù che khuất khuôn mặt của người cầu đạo. Sương mù che khuất trái tim của đấng bá chủ."
  },
  Stage_51774_Name = {
    Text = "Người trong sương"
  },
  Stage_51775_Desc = {
    Text = "Cung điện xưa nay đã trở thành ảo ảnh, giấc mơ cũ chỉ còn lại âm vang mỏng manh. Trên ngai vàng héo úa, chỉ còn xác của vị vua. Vị vua ấy vẫn kể về những ngụ ngôn cổ xưa."
  },
  Stage_51775_Name = {
    Text = "Ảo ảnh ngày xưa"
  },
  Stage_51785_Desc = {
    Text = "Vào thời khắc thảm họa vô hình sống lại, lịch sử và hiện tại của thế giới vật chất dần chìm vào tận cùng vực sâu."
  },
  Stage_51785_Name = {
    Text = "Vùng Cấm - Thảm Họa Phân Giải: Đợt Đầu Tiên: Cảnh Báo Bậc 4"
  },
  Stage_51786_Desc = {
    Text = "Vào thời khắc thảm họa vô hình sống lại, lịch sử và hiện tại của thế giới vật chất dần chìm vào tận cùng vực sâu."
  },
  Stage_51786_Name = {
    Text = "Vùng Cấm - Thảm Họa Phân Giải: Đợt Thứ Ba: Cảnh Báo Bậc 4"
  },
