  Stage_53376_Name = {
    Text = "Vùng Cấm - Thảm Họa Phân Giải: Đợt Thứ Năm: Cảnh Báo Bậc 4"
  },
  Stage_53775_Desc = {
    Text = "Trước khi khởi hành, nhà văn viết tiểu sử quay đầu nhìn lại ngôi biệt thự xinh đẹp với hoa hồng nở rộ, nó không thể sánh bằng một phần vạn của vẻ rực rỡ chủ nhân. \nChuyện về bà Sorrel vẫn tiếp tục và đang xảy ra ngay lúc này. Chúng ta đều sẽ trở thành những người chứng kiến."
  },
  Stage_53775_Name = {
    Text = "Cuối cùng·Phần hai"
  },
  Stage_53776_Desc = {
    Text = "Cô ấy có nhiều thân phận: quý cô, thương nhân, trung gian, nhà sưu tập… \nDuy nhất không có chính bản thân mình —— rất đáng tiếc, Bà Hồng Hoa chưa bao giờ cảm thấy mất mát vì điều đó. \nĐối với cô, những thứ nguyên thủy, chưa được mài dũa không đáng kể, phức tạp và rối rắm mới là thẩm mỹ cao nhất."
  },
