  Stage_53788_Name = {
    Text = "Hoa hồng góc · thứ sáu"
  },
  Stage_53789_Desc = {
    Text = "Sắc đẹp là sợi dây vô hình, dễ dàng trói buộc trái tim con người. Cô ấy khéo léo điều khiển những sợi chỉ, như một thiên tài thờ ơ. \nChẳng bao lâu, cô cảm thấy nhàm chán với trò chơi này, vì qua những khuôn mặt xấu xí của họ, cô nhìn thấy chính mình."
  },
