  Stage_55395_Name = {
    Text = "Tượng tu từ học"
  },
  Stage_55396_Desc = {
    Text = "Các cô gái nhìn nhau qua khu vườn. \nTrong vườn có vô số con đường riêng của họ, mỗi con đường đều đi ngược chiều nhau."
