  Stage_55400_Name = {Text = "Nhà"},
  Stage_55401_Desc = {
    Text = "\"Hãy để tôi dùng bông hồng đầu tiên, đổi lấy bài thơ đầu tiên của bạn.\""
  },
  Stage_55401_Name = {
    Text = "Thi thiên 1843"
  },
  Stage_55551_Desc = {
    Text = "Ngọn tuyết sơn này có sức sống, trong khe núi vang vọng tiếng gào thét, đó là nó đang gọi con gái của mình. \nNhanh lên nào, nhanh lên nào. \nLà con gái đi về phía mẹ, hay là mẹ đi về phía con gái? \nTại đỉnh tuyết sơn, hai chiếc dạ dày trống rỗng cuối cùng đã gặp nhau."
  },
