  Stage_55585_Name = {
    Text = "Phá đất · Số 4"
  },
  Stage_56404_Desc = {
    Text = "Muphí nghe nói rằng mình không phải là Thánh nữ đầu tiên, trong suốt hàng nghìn năm dài đằng đẵng, đã có vô số thiếu nữ mang trong mình nhịp đập tim xao động. \nTrong hàng ngàn không gian thời gian, vô số trái tim đập đồng điệu."
  },
  Stage_56404_Name = {
    Text = "Hố sâu thời không·điên cuồng"
  },
  Stage_56404_StageInitStateText = {
    Text = "Ác Mộng Biển Sâu"
  },
  Stage_56405_Desc = {
    Text = "Đây là nơi quy tú cuối cùng đầy uy nghiêm của mọi sức sống.\nVới biển sâu làm quan tài, trời đất làm giường ngủ, vị thần minh vĩ đại đã yên nghỉ trong dòng hải lưu."
  },
  Stage_56405_Name = {
    Text = "Vải liệm·điên cuồng"
  },
  Stage_56405_StageInitStateText = {
    Text = "Ác Mộng Biển Sâu"
  },
  Stage_56407_Desc = {
    Text = "Ngài đến trong im lặng và vô tâm. \nTrái tim của Ngài nằm trong dòng máu của cô, đập liên tục một cách không mong muốn."
  },
  Stage_56407_Name = {
    Text = "Sự đến của Ngài · điên cuồng"
  },
  Stage_56407_StageInitStateText = {
    Text = "Ác Mộng Biển Sâu"
  },
  Stage_56408_Desc = {
    Text = "Cô đếm những ngôi sao trên cao, chờ đợi khoảnh khắc mà cô không hề mong đợi. \n \"Thời khắc của ngôi sao chính vị\", khi các ngôi sao mọc lên trên mặt biển, cô sẽ trở thành một trong số chúng."
  },
  Stage_56408_Name = {
    Text = "Sao vàng · điên cuồng"
  },
  Stage_56408_StageInitStateText = {
    Text = "Ác Mộng Biển Sâu"
  },
  Stage_56409_Desc = {
    Text = "Cô không có quyền quyết định về sự thuộc sở hữu của phôi thai được cấy ghép trong lồng ngực mình. \n Cô không có quyền quyết định chạy trốn đi đâu, không có quyền quyết định nắm tay ai, không có quyền quyết định cùng ai lang thang lênh đênh. \n Trong số phận sóng gió của ảo cảnh trên biển, ai cũng chỉ là con cừu chờ bị thịt."
  },
  Stage_56409_Name = {
    Text = "Tàn sát con chiên · điên cuồng"
  },
  Stage_56409_StageInitStateText = {
    Text = "Ác Mộng Biển Sâu"
  },
  Stage_56410_Desc = {
    Text = "Không cần thiết phải dùng đến máy chém để xử tử cô ta. \n Người mẹ đã tự tay kết liễu cô."
  },
  Stage_56410_Name = {
    Text = "Hành hình giả·điên cuồng"
