  Stage_56894_Desc = {
    Text = "Trên thế gian này vốn không có cửa. \n Khi có nhiều người khao khát cánh cửa, thế gian mới có đủ loại cửa. \n Ai nấy đều nói rằng đằng sau cửa của mình mới là thiên đường. \n Tuy nhiên, lời tiên tri cổ xưa đã nói rõ, trên thế gian này từ xưa đến nay chưa bao giờ có cửa. \n Những ai muốn xây dựng thiên đường ở trần gian, cuối cùng sẽ mở ra cánh cửa địa ngục."
  },
  Stage_56894_Name = {
    Text = "Dự ngôn hỗn loạn · Thứ sáu"
  },
  Stage_56895_Desc = {
    Text = "Dây sợi buông xuống từ tay con rối, nối liền các bộ phận của thế giới. \nTạch tạch, xẹt xẹt, khẽ động ngón tay, thế giới sụp đổ. \nLại có thứ gì đó treo trên đầu con rối, khiến nó không ngừng dâng hiến vũ điệu cho hư vô."
  },
