  Stage_56901_Name = {
    Text = "Dự ngôn hỗn loạn · thứ nhất"
  },
  Stage_56902_Desc = {
    Text = "Nhảy đi, nhảy đi, đừng dừng bước của bạn. \nNâng váy lên, quay vòng tròn, vì thế giới này đang không ngừng xoay trong cơn lốc. \nQuên đi mọi lo lắng, hòa vào bữa tiệc cuối cùng. \nChỉ cần nhảy múa hết mình, bạn sẽ thấy hoàng hôn bất tận."
  },
  Stage_56902_Name = {
    Text = "Đám tiệc nhảy múa · Phần một"
