  Stage_57684_Name = {
    Text = "Lời từ biệt cuối cùng"
  },
  Stage_57685_Desc = {
    Text = "Chúc may mắn luôn bên cạnh anh, thưa ngài thám tử. \nHẹn gặp lại."
  },
  Stage_57685_Name = {
    Text = "Chúc bạn may mắn!"
  },
  Stage_57686_Desc = {
    Text = "Mỗi khi kỳ thi đến, tôi lại mong có một điều gì đó xảy ra. \n Lũ lụt, bão táp, va chạm của tiểu hành tinh… bất cứ thứ gì cũng được, miễn là có thể tạm thời đẩy lùi thực tại trong chốc lát. \n Chỉ một lúc ngắn thôi."
  },
  Stage_57686_Name = {
    Text = "Khách không mời mà đến"
  },
  Stage_57687_Desc = {
    Text = "Họ đều đang ở trong tình thế nguy cấp, lại cùng nhau khát vọng sống."
