  Stage_58443_Name = {
    Text = "Bộ não bò sát·điên cuồng"
  },
  Stage_58443_StageInitStateText = {
    Text = "Nguyên thủy"
  },
  Stage_58444_Desc = {
    Text = "Nó đã trở thành biểu tượng của khu vực đáng ghét trong linh hồn của cô ấy. \nCô ấy cùng nó chịu đựng, cùng nó chết đi, và theo một nghĩa nào đó, cùng nó biến mất. \nVì vậy, trái tim cô ấy lạnh lùng và không chút cảm thương."
  },
  Stage_58444_Name = {
    Text = "Páo chóng não · sáu"
  },
  Stage_58445_Desc = {
    Text = "Nó đã trở thành biểu tượng của khu vực đáng ghét trong linh hồn của cô ấy. \nCô ấy cùng nó chịu đựng, cùng nó chết đi, và theo một nghĩa nào đó, cùng nó biến mất. \nVì vậy, trái tim cô ấy lạnh lùng và không chút cảm thương."
  },
  Stage_58445_Name = {
    Text = "Bò cạp · Năm"
  },
  Stage_58446_Desc = {
    Text = "Nó đã trở thành biểu tượng của khu vực đáng ghét trong linh hồn của cô ấy. \nCô ấy cùng nó chịu đựng, cùng nó chết đi, và theo một nghĩa nào đó, cùng nó biến mất. \nVì vậy, trái tim cô ấy lạnh lùng và không chút cảm thương."
  },
  Stage_58446_Name = {
    Text = "Não bọ·thứ tư"
  },
  Stage_58449_Desc = {
    Text = "Dư âm vang vọng. \n Đổi lấy sức sống, bản nhạc của người vang vọng mãi trong đền thờ của Người."
  },
  Stage_58449_Name = {
    Text = "Âm vang còn lại · điên cuồng"
  },
  Stage_58449_StageInitStateText = {
    Text = "Nguyên thủy"
  },
  Stage_58450_Desc = {
    Text = "Màn lớn buông xuống. \nAnh ta với dáng vẻ kiêu hãnh dần biến mất sau bức màn nhung đỏ đang từ từ hạ xuống."
  },
  Stage_58450_Name = {
    Text = "Màn hạ · điên cuồng"
  },
  Stage_58450_StageInitStateText = {
    Text = "Nguyên thủy"
  },
  Stage_58451_Desc = {
    Text = "Đây là \"Cửa thứ tư\". \nNgười bước vào cửa thứ tư sẽ được thấy chân dung của \"Ngài\". \nKhi đã nhìn thấy sự bao la của vũ trụ, thì sẽ hiểu được sự nhỏ bé của bản thân. Đừng cố gắng lay chuyển những điều quá sức mình."
  },
  Stage_58451_Name = {
    Text = "Cổng Tri và Hành · Điên Cuồng"
  },
  Stage_58451_StageInitStateText = {
    Text = "Nguyên thủy"
  },
  Stage_58452_Desc = {
    Text = "Chào mừng đến với Nhà búp bê, nơi có một nghìn nụ cười giống hệt nhau. \nHihi, cái nào là người bạn cũ của bạn?"
  },
  Stage_58452_Name = {
    Text = "Nhà Búp Bê · Điên Cuồng"
  },
  Stage_58453_Desc = {
    Text = "Trên thế gian này vốn không có cửa. \n Khi có nhiều người khao khát cánh cửa, thế gian mới có đủ loại cửa. \n Ai nấy đều nói rằng đằng sau cửa của mình mới là thiên đường. \n Tuy nhiên, lời tiên tri cổ xưa đã nói rõ, trên thế gian này từ xưa đến nay chưa bao giờ có cửa. \n Những ai muốn xây dựng thiên đường ở trần gian, cuối cùng sẽ mở ra cánh cửa địa ngục."
  },
  Stage_58453_Name = {
    Text = "Dự ngôn hỗn loạn · Điên cuồng"
  },
  Stage_58454_Desc = {
    Text = "Dây sợi buông xuống từ tay con rối, nối liền các bộ phận của thế giới. \nTạch tạch, xẹt xẹt, khẽ động ngón tay, thế giới sụp đổ. \nLại có thứ gì đó treo trên đầu con rối, khiến nó không ngừng dâng hiến vũ điệu cho hư vô."
  },
  Stage_58454_Name = {
    Text = "Dây rối·điên cuồng"
  },
  Stage_58455_Desc = {
    Text = "Nhạc chương vui vẻ. \n Họ hoạt động khắp nơi trên đất này, hình ảnh họ đấu tranh thật rực rỡ và đầy cảm hứng."
  },
  Stage_58455_Name = {
    Text = "Minuet Nhỏ · điên cuồng"
  },
  Stage_58455_StageInitStateText = {
    Text = "Nguyên thủy"
  },
  Stage_58456_Desc = {
    Text = "Đây là \"Cửa thứ ba\". \nNgười bước vào cửa thứ ba, không bị ràng buộc bởi lý trí nông cạn, có thể hiểu được kiến thức bên ngoài giới hạn."
  },
  Stage_58456_Name = {
    Text = "Cánh cửa Lý trí · điên cuồng"
  },
  Stage_58456_StageInitStateText = {
    Text = "Nguyên thủy"
  },
  Stage_58457_Desc = {
    Text = "Nhảy đi, nhảy đi, đừng dừng bước của bạn. \nNâng váy lên, quay vòng tròn, vì thế giới này đang không ngừng xoay trong cơn lốc. \nQuên đi mọi lo lắng, hòa vào bữa tiệc cuối cùng. \nChỉ cần nhảy múa hết mình, bạn sẽ thấy hoàng hôn bất tận."
  },
  Stage_58457_Name = {
    Text = "Vũ hội điên cuồng·điên cuồng"
  },
  Stage_58458_Desc = {
    Text = "Sơ đồ sonata. \n Từ một chia thành ba, trong tam giác, con mắt mở to nhìn xuống mặt đất."
  },
  Stage_58458_Name = {
    Text = "Tiết tấu nhanh · điên cuồng"
  },
  Stage_58458_StageInitStateText = {
    Text = "Nguyên thủy"
  },
  Stage_58459_Desc = {
    Text = "Cô ấy đã có được tất cả những gì vua đã tiên đoán —— lực lượng mạnh mẽ, niềm tin kiên định. Cô ấy gánh chịu tội lỗi của việc từng nghi ngờ vua, và bước lên con đường đón chào thần quốc."
  },
  Stage_58459_Name = {
    Text = "Sự tin tưởng sâu sắc · điên cuồng"
  },
  Stage_58459_StageInitStateText = {
    Text = "Ác Mộng Biển Sâu"
  },
  Stage_58460_Desc = {
    Text = "Đây là \"Cửa thứ năm\". \nNgười vào Cửa thứ năm sẽ cùng Vũ trụ chia sẻ bí mật tối cao. \nMuôn vật đều do \"Ngài\" hít thở mà sinh ra, và cũng sẽ bị xóa sổ bởi hơi thở của \"Ngài\"."
  },
  Stage_58460_Name = {
    Text = "Cánh cửa thống nhất · điên cuồng"
  },
  Stage_58460_StageInitStateText = {
    Text = "Nguyên thủy"
  },
  Stage_58461_Desc = {
    Text = "Cô ấy đưa tay ra, mời bạn làm bạn nhảy của cô ấy. \n Tiến lên, lùi lại, sự ăn ý này chỉ có giữa hai người. \n Nhẹ nhàng nắm lấy bàn tay cô ấy, theo bước chân của cô ấy, hãy giữ đầu ngẩng cao như một quý ông. \n Dù dưới chân đã là mép vực sâu."
  },
  Stage_58461_Name = {
    Text = "Mời·điên cuồng"
  },
  Stage_58462_Desc = {
    Text = "Đây là \"Cửa thứ sáu\". \nAi bước vào cửa thứ sáu sẽ liên kết mọi thế giới, đạt được sự tồn tại vĩnh cửu trong vô số chiều không gian."
  },
  Stage_58462_Name = {
    Text = "Cổng Thiên Địa · điên cuồng"
  },
  Stage_58462_StageInitStateText = {
    Text = "Nguyên thủy"
  },
  Stage_58463_Desc = {
    Text = "Bản nhạc trữ tình. \n nuôi dưỡng, sinh sôi, liên tục phát triển."
  },
  Stage_58463_Name = {
    Text = "Chậm rãi · điên cuồng"
  },
  Stage_58463_StageInitStateText = {
    Text = "Nguyên thủy"
  },
  Stage_58464_Desc = {
    Text = "Hãy khởi hành. \nChuyến đi này dẫn đến \"Trí tuệ\" hay \"Ngu dốt\", chỉ có thể biết khi bước lên hành trình."
  },
  Stage_58464_Name = {
    Text = "Khởi hành điên cuồng"
  },
  Stage_58464_StageInitStateText = {
    Text = "Nguyên thủy"
  },
  Stage_58465_Desc = {
    Text = "Giao hưởng không phải là trò chơi của một người. \n Dây, gỗ, đồng và bộ gõ. \n Các nhóm nhạc cụ được sắp xếp gọn gàng cúi đầu chờ anh ấy chỉ đạo."
  },
  Stage_58465_Name = {
    Text = "Dàn nhạc · điên cuồng"
  },
  Stage_58465_StageInitStateText = {
    Text = "Nguyên thủy"
  },
  Stage_58466_Desc = {
    Text = "Anh ta theo tiếng động mà đến, đặt chân lên bục chỉ huy. \nBước chân của anh ta vững chắc, đầy tự tin. \nKhông ai biết anh ta đến vì một giấc mơ, và chủ nhân của giấc mơ đã sớm lạc lối."
  },
  Stage_58466_Name = {
    Text = "Mộng Dẫn Mê Lộ · điên cuồng"
  },
  Stage_58466_StageInitStateText = {
    Text = "Nguyên thủy"
  },
  Stage_58467_Desc = {
    Text = "Đây là\"Cửa Đầu Tiên\".\nNgười bước vào Cửa Đầu Tiên phải phá vỡ xiềng xích, buông bỏ bản ngã và lãng quên chính mình.\nGiới hạn trong tầm nhìn cá nhân không thể nắm bắt được sự thật kỳ quặc."
  },
  Stage_58467_Name = {
    Text = "Cánh cửa bản chất · điên cuồng"
  },
  Stage_58467_StageInitStateText = {
    Text = "Nguyên thủy"
  },
  Stage_58468_Desc = {
    Text = "Đây là \"Cửa thứ hai\". \nAi bước vào cửa thứ hai, chớ vội phán đoán đúng sai. \nĐúng sai chỉ là sự chủ quan của người đặt ra quy tắc, còn chân lý nằm ngoài mọi kiến thức."
  },
  Stage_58468_Name = {
    Text = "Cánh cửa thiện ác · điên cuồng"
  },
  Stage_58468_StageInitStateText = {
    Text = "Nguyên thủy"
  },
  Stage_58469_Desc = {
    Text = "Sơ đồ xoắn ốc.\nÔng sẽ chỉ dẫn hướng đi cuối cùng, đối mặt với sự hủy diệt."
  },
  Stage_58469_Name = {
    Text = "Khúc cuối · điên cuồng"
  },
  Stage_58469_StageInitStateText = {
    Text = "Nguyên thủy"
  },
  Stage_58470_Desc = {
    Text = "Dáng dấp của thần quốc hiện ra trước mắt cô. Tiếng chuông thần quốc vang lên trong tai cô. Cô sẽ thực hiện lời tiên tri của nhà vua, không bao giờ ngừng lại. \nCô dùng những lời này để vượt qua bóng tối vô tận của kiếp nhân sinh."
  },
  Stage_58470_Name = {
    Text = "Đến điên cuồng"
  },
  Stage_58470_StageInitStateText = {
    Text = "Ác Mộng Biển Sâu"
  },
  Stage_58471_Desc = {
    Text = "Họa tận thế đến, thế giới đầy vết loét, xoáy ốc suy tàn sẽ cuốn trôi mọi sinh linh. \nCầu nguyện đi, tìm kiếm đi, cánh cửa sinh tồn không bao giờ tồn tại."
  },
  Stage_58471_Name = {
    Text = "Cuồng Tai · Điên cuồng"
  },
  Stage_58472_Desc = {
    Text = "Mất mọi thứ, cô ấy cuối cùng đã hiểu rằng, chỉ có vua mới có thể cứu dân tộc Lemuria. \nCô ấy chờ đợi, trong thần quốc xa xôi kia, để gặp lại mọi thứ mình đã mất."
  },
  Stage_58472_Name = {
    Text = "Chứng kiến, điên cuồng"
  },
  Stage_58472_StageInitStateText = {
    Text = "Ác Mộng Biển Sâu"
  },
  Stage_58473_Desc = {
    Text = "Lemuria đã biến mất. Thần minh chưa bao giờ quan tâm đến mảnh đất này. \nThần quốc, chưa bao giờ tồn tại."
  },
  Stage_58473_Name = {
    Text = "Động lắc · điên cuồng"
  },
  Stage_58473_StageInitStateText = {
    Text = "Ác Mộng Biển Sâu"
  },
  Stage_58474_Desc = {
    Text = "Tại sao bạn vẫn không chịu từ bỏ? Tại sao bạn vẫn ngu muội như xưa? \n… Bảo vệ họ sao. \nNếu đó là câu trả lời của bạn, bạn sẽ phải dâng hiến xương, máu, linh tri thức, và tất cả mọi thứ."
  },
  Stage_58474_Name = {
    Text = "Cánh cửa điên cuồng"
  },
  Stage_58474_StageInitStateText = {
    Text = "Nguyên thủy"
  },
  Stage_58475_Desc = {
    Text = "Có một ngôi sao treo trong màn đêm đặc quánh. \n Ngôi sao đó phình to, phát sáng, biến thành một quả bông gòn vô tận. \n Đó là niềm yêu thương và nỗi hận thù sâu sắc mà ai đó đã tích tụ suốt đời, thử nếm xem, nó có vị gì?"
  },
  Stage_58475_Name = {
    Text = "Sao điên cuồng"
  },
  Stage_58476_Desc = {
    Text = "Cầu nguyện là điều đầu tiên người Lemuria học được, nhưng người xuất hiện trước mặt để bảo vệ cô ấy chưa bao giờ là hoàng đế của cô ấy."
  },
  Stage_58476_Name = {
    Text = "Thắc mắc·điên cuồng"
  },
  Stage_58476_StageInitStateText = {
    Text = "Ác Mộng Biển Sâu"
  },
  Stage_58477_Desc = {
    Text = "Vô số người khao khát sự thật, liên tiếp đổ xô tới.\nVô số người cầm những phân mảnh của sự thật, tưởng rằng đôi mắt mù đã được sáng tỏ, bắt đầu ca ngợi vẻ đẹp của thiên đường.\nChỉ có cô ấy tìm thấy rượu sự thật, uống cạn chén ngọc quý.\nGudong.\nCô ấy say khướt và nhiễm độc sâu.\nQuả nhiên, vô số kẻ ngốc đã chứng minh, sự thật chỉ là một ly thuốc độc.\nUống ít thì trúng độc, uống nhiều thì mất mạng.\nBây giờ cô ấy thời gian không còn nhiều, chỉ muốn cùng bạn thưởng thức."
  },
  Stage_58477_Name = {
    Text = "Thuốc độc thật sự điên cuồng"
  },
  Stage_58478_Desc = {
    Text = "Hãy bừng sáng như pháo hoa, dù nhiên liệu là chính sự sống. \nVì điểm kết cục tương đồng, sao không bỏ qua chuỗi ngày đau thương để đổi lấy ánh sáng chói lòa?"
  },
  Stage_58478_Name = {
    Text = "Sự tàn lụi rực rỡ·điên cuồng"
  },
  Stage_58479_Desc = {
    Text = "Đây là \"Cửa thứ Bảy\". \nDòng chảy của thời gian dừng lại ở đây, trí tuệ vĩnh cửu sẽ dẫn dắt những kẻ tìm kiếm đang bối rối thoát khỏi sự mê muội sâu thẳm."
  },
  Stage_58479_Name = {
    Text = "Cánh cửa tận cùng · điên cuồng"
  },
  Stage_58479_StageInitStateText = {
    Text = "Nguyên thủy"
  },
  Stage_58480_Desc = {
    Text = "Khởi đầu, phân biệt chủ đề. \nNgười đó sẽ kể về sự khởi đầu và kết thúc, về việc hít vào và thở ra."
  },
  Stage_58480_Name = {
    Text = "Dạo đầu · điên cuồng"
  },
  Stage_58480_StageInitStateText = {
    Text = "Nguyên thủy"
  },
  Stage_58691_Desc = {
    Text = "Gió thổi tuyết tan, vạn vật sinh sôi."
  },
  Stage_58691_Name = {
    Text = "Một mùa xuân"
  },
  Stage_58692_Desc = {
    Text = "Đau thương, hoặc kinh ngạc. Đây là một chiến binh, gửi lời thách đấu tới dãy núi."
  },
  Stage_58692_Name = {Text = "Đồi gai"},
  Stage_58693_Desc = {
    Text = "Quần áo của cô ấy bay theo gió, sự mơ hồ của cô ấy vang lên nhẹ nhàng. Cô ấy đứng trước mặt bạn."
  },
  Stage_58693_Name = {Text = "Tái ngộ"},
  Stage_58694_Desc = {
    Text = "Các bạn không tìm thấy kẻ địch, nhưng kẻ địch đã tìm thấy các bạn."
  },
  Stage_58694_Name = {Text = "Bóng đen"},
  Stage_58695_Desc = {
    Text = "Quay lại đi, con. Núi gọi. \nĐáp lại lời gọi thân thương của mẹ, trở về vòng tay bình yên của định mệnh."
  },
  Stage_58695_Name = {
    Text = "Tiếng gọi của núi rừng"
  },
  Stage_58696_Desc = {
    Text = "Câu chuyện của họ không ai biết. Tên của họ không ai tưởng niệm."
  },
  Stage_58696_Name = {Text = "Lễ vật"},
  Stage_58697_Desc = {
    Text = "Đối với sự thăm viếng lịch sự của các bạn, Elworth dường như không quá hoan nghênh."
  },
  Stage_58697_Name = {
    Text = "Khách từ cao nguyên tuyết"
  },
  Stage_58698_Desc = {
    Text = "Trong ánh trăng và tuyết, máu là sắc màu thứ ba."
  },
  Stage_58698_Name = {
    Text = "Đêm đông lạnh giá kéo dài"
  },
  Stage_58699_Desc = {
    Text = "Rất khó để phán đoán, thực sự cái nào nguy hiểm hơn."
  },
  Stage_58699_Name = {
    Text = "Đồng đội hay kẻ địch"
  },
  Stage_58700_Desc = {
    Text = "Đau thương, hoặc kinh ngạc. Đây là một chiến binh, gửi lời thách đấu tới dãy núi."
  },
  Stage_58700_Name = {Text = "Đồi gai"},
  Stage_58701_Desc = {
    Text = "Đau thương, hoặc kinh ngạc. Đây là một chiến binh, gửi lời thách đấu tới dãy núi."
  },
  Stage_58701_Name = {Text = "Đồi gai"},
  Stage_58976_Desc = {
    Text = "\"Tôi sẽ nhìn bạn, kiên định đi trên con đường tuyệt vọng này... Tôi sẽ tham dự tang lễ của bạn, để thương tiếc bạn.\""
  },
  Stage_58976_Name = {
    Text = "Con đường tồn vong"
  },
  Stage_58977_Desc = {
    Text = "\"Tôi thích nhiều cảnh trong nhà hát. Nhưng cảnh tôi thích nhất là khi họ ném những bộ đồ sứ đẹp nhất từ gác xép xuống.\""
  },
  Stage_58977_Name = {
    Text = "Người cha và cô con gái"
  },
  Stage_58978_Desc = {
    Text = "Gập ghềnh, dài đằng đẵng, hư vô. Mỗi người đều có con đường riêng mình phải đối mặt. \nKhi bạn cuối cùng đứng ở điểm khởi đầu, bạn có đủ can đảm để ngắm nhìn về phía xa xăm của mình không?"
  },
  Stage_58978_Name = {Text = "Đường"},
  Stage_58979_Desc = {
    Text = "Nhịp điệu. Giai điệu. Hòa âm nhẹ nhàng của dây đàn tràn ngập tâm trí các bạn. \nTrong sự chú ý im lặng của khán giả, người chỉ huy bước lên sân khấu của mình."
  },
  Stage_58979_Name = {
    Text = "Nhạc trưởng"
  },
  Stage_58980_Desc = {
    Text = "Thân thể yếu đuối của anh bị nhấn chìm trong lòng đất sôi sục. \nTrong chiều ảo, anh đơn độc đối đầu với hồ đen."
  },
  Stage_58980_Name = {Text = "Thân tàn"},
  Stage_58981_Desc = {
    Text = "Đi sai âm, thiếu vị trí…… bất kỳ một lỗi nào cũng sẽ khiến một buổi biểu diễn không thể cứu vãn. \n luyện tập. Qua vô số lần luyện tập, hãy kiên nhẫn chờ đợi những tràng pháo tay dành riêng cho bạn."
  },
  Stage_58981_Name = {
    Text = "Luyện tập"
  },
  Stage_58982_Desc = {
    Text = "Quên lãng, là sự thanh lọc cuối cùng của thế giới này? Misaque từ chối đồng ý. \nNhững người trong khuôn viên trường này sẽ chiến đấu vì sự ghi nhớ."
  },
  Stage_58982_Name = {
    Text = "Chân Lý Quên Lãng"
  },
  Stage_58982_StageInitStateText = {
    Text = "Tận cùng"
  },
  Stage_58983_Desc = {
    Text = "Nhạc điệu nhẹ nhàng, vui tươi, tác phẩm đơn điệu thiếu sự sáng tạo. \n Đúng vậy, hãy nghỉ ngơi ở chương ba. Nơi này an toàn, bình yên và không có gì bất ngờ."
  },
  Stage_58983_Name = {
    Text = "Chương ba (Phần nhạc thứ ba)"
  },
  Stage_58984_Desc = {
    Text = "Không có cách nào cầu xin. Không có cách nào trốn tránh. Đó là số phận của thế giới này. \n Chiến thắng chúng. Giết chết chúng. Sau đó, cứu rỗi chúng."
  },
  Stage_58984_Name = {
    Text = "Định mệnh"
  },
  Stage_58985_Desc = {
    Text = "Sự bất ngờ bị tiết lộ trước sẽ mất đi sức mạnh, nhưng anh ta không bao giờ quan tâm. \nNiềm vui mà anh ta mong đợi, không nằm ở đây."
  },
  Stage_58985_Name = {
    Text = "Phong cách chuyển biến kiểu Dexter"
  },
  Stage_58986_Desc = {
    Text = "Suỵt. \nKhán giả cuối cùng đã ngồi xuống, màn trình diễn thực sự sắp bắt đầu."
  },
  Stage_58986_Name = {Text = "Vào sân"},
  Stage_58987_Desc = {
    Text = "Khi thông tin không đối xứng, càng hoàn hảo, càng sai lầm."
  },
  Stage_58987_Name = {
    Text = "Học sinh tốt, học sinh xấu"
  },
  Stage_58988_Desc = {
    Text = "\"Misaque độc lập khỏi quyền quản lý của chính phủ Vương quốc Leo và hội nghị thẩm tra Hiệp định Misidia. Bất cứ ai xâm nhập trái phép đều sẽ bị coi là xâm nhập bất hợp pháp, và Misaque có quyền thực hiện đầy đủ quyền tự vệ.\""
  },
  Stage_58988_Name = {
    Text = "Nội quy trường"
  },
