  },
  Stage_59077_Name = {
    Text = "Khe Nứt Nguyên Thủy II"
  },
  Stage_59502_Desc = {
    Text = "Đối mặt với tuyệt vọng nguyên thủy nhất của các ngươi. Đối mặt với nỗi sợ hãi nguyên thủy nhất của các ngươi. \nĐứng cạnh nhau, dù không nhìn thấy, và chiến thắng vị Thần đó."
  },
  Stage_59502_Name = {
    Text = "Quyết định: Bóng tối nguyên thủy"
  },
  Stage_59503_Desc = {
    Text = "Ghi nhớ là lời thề của bạn, quên lãng là lễ dâng của bạn."
  },
