  Stage_62348_Desc = {
    Text = "Đây là cao trào của các ngôi sao. Đây là kết thúc của vũ trụ. \n Trong sự yên lặng này, lắng nghe kỹ — \n Những âm thanh đích thực, bạn có nghe thấy không?"
  },
  Stage_62348_Name = {
    Text = "Bản kết"
  },
  Stage_66016_Desc = {
    Text = "Ngài là ý chí tối thượng, Đấng sáng tạo vũ trụ, người kết thúc vạn vật. \n Hãy khóc lóc trước mặt Ngài. Vì sự can đảm yếu ớt của các ngươi, vì quyền năng vô tận của Ngài."
  },
  Stage_66016_Name = {
    Text = "Nhà nuôi người nghèo·Đôi mắt đẫm lệ"
  },
  Stage_66016_StageInitStateText = {
    Text = "Nguyên thủy"
  },
  Stage_66017_Desc = {
    Text = "Ngài là ý chí tối thượng, Đấng sáng tạo vũ trụ, người kết thúc vạn vật. \n Hãy khóc lóc trước mặt Ngài. Vì sự can đảm yếu ớt của các ngươi, vì quyền năng vô tận của Ngài."
  },
