  Stage_70415_Desc = {
    Text = "Con mèo đen quen thuộc rõ ràng cũng có ký ức về bạn, nó tháo mũ chào bạn. \nMột đôi găng tay trắng chẳng biết từ đâu xuất hiện được ném trước mặt bạn, đây không phải là lời chào, mà là một lời thách đấu đầy phong cách quý ông."
  },
  Stage_70415_Name = {
    Text = "Lời chào của mèo·số hai"
  },
  Stage_70416_Desc = {
    Text = "Đêm nay thật vui vẻ, mọi thứ khiến mèo lưu luyến không quên! \n Hãy để ánh trăng trong sáng xuyên qua cửa sổ hoa, chiếu xuống bữa tiệc cuồng hoan! \n Ôi, ca ngợi những chú mèo!"
  },
  Stage_70416_Name = {
    Text = "Lễ hội của mèo · Phần hai"
  },
  Stage_70417_Desc = {
    Text = "Mèo tai quay tròn, móng vuốt xòe ra như hoa nở, đuôi dựng đứng. \nTrong điệu nhảy vui vẻ cùng bạn, niềm vui của mèo tràn đầy."
  },
  Stage_70417_Name = {
    Text = "Sự vui sướng của mèo·thứ hai"
  },
  Stage_70418_Desc = {
    Text = "Chân mèo không ngừng thăm dò trước mặt bạn, duỗi ra và co lại liên tục. \n Dấu chân đen nhánh in lên đôi giày da đồng phục của bạn. \n Bạn không thể kiềm chế được và nhấc nắm đấm khổng lồ lên."
  },
  Stage_70418_Name = {
    Text = "Dấu vuốt mèo·thứ ba"
  },
  Stage_70419_Desc = {
    Text = "Chân mèo không ngừng thăm dò trước mặt bạn, duỗi ra và co lại liên tục. \n Dấu chân đen nhánh in lên đôi giày da đồng phục của bạn. \n Bạn không thể kiềm chế được và nhấc nắm đấm khổng lồ lên."
  },
  Stage_70419_Name = {
    Text = "Dấu vuốt mèo·thứ hai"
  },
  Stage_70420_Desc = {
    Text = "Hãy hát hết mình tại bữa tiệc của mèo, hãy nâng cao ly rượu vui vẻ, để mèo đen rót đầy rượu ngon cho bạn… Chuyện gì thế? Sao trong bình rượu lại là canh cá?"
  },
  Stage_70420_Name = {
    Text = "Đám tiệc của mèo·một"
  },
  Stage_70421_Desc = {
    Text = "Mèo đen cong lưng lên, bắt đầu di chuyển bốn chân của mình. \nDường như con mèo đen vừa thuần phục thân thể. \nCon mèo đen có hình dáng kỳ lạ đưa tay ra, mời bạn tham gia cùng nhảy múa."
  },
