  },
  Stage_71932_Name = {
    Text = "Vùng Cấm - Thảm Họa Phân Giải: Đợt Thứ Hai: Cảnh Báo Bậc 5"
  },
  Stage_72063_Desc = {
    Text = "Đôi mắt, tôi chẳng dám đối mặt trong giấc mơ\ntrên miền đất mơ màng của cái chết"
  },
  Stage_72063_Name = {
    Text = "Người rỗng"
  },
  Stage_72064_Desc = {
    Text = "Con người định nghĩa duy nhất là sự thật. \nNhững gì bạn thấy chính là bản chất của thế giới."
  },
  Stage_72064_Name = {
    Text = "Sự thật"
  },
  Stage_72065_Desc = {
    Text = "Bạn xem này, quả táo với vẻ ngoài tròn mượt mà và dưỡng sáng thật hấp dẫn. \nHãy cắn nhẹ một miếng, để xua tan mọi lo âu."
  },
  Stage_72065_Name = {
    Text = "Quả táo có độc"
  },
  Stage_72066_Desc = {
    Text = "Tất cả đều giống như trong ký ức."
  },
  Stage_72066_Name = {
    Text = "Người thân thiện và dũng cảm"
  },
  Stage_72067_Desc = {
    Text = "Điều đã mất sẽ không bao giờ trở lại. \nChỉ khi, đó là ở một thế giới khác."
  },
  Stage_72067_Name = {
    Text = "Chúng ta đã đánh mất"
  },
  Stage_72068_Desc = {
    Text = "Phách ngược, phách ngược, các nốt nhạc di chuyển ngoài nhịp điệu dự kiến."
  },
  Stage_72068_Name = {
    Text = "Những nốt nhạc của Mizou"
  },
  Stage_72069_Desc = {
    Text = "Trốn khỏi một bẫy, để rồi rơi vào một chiếc lồng giam lớn hơn."
  },
  Stage_72069_Name = {Text = "Thoát"},
  Stage_72070_Desc = {
    Text = "Người yêu, hãy cùng nhau đi xem ngày tận thế. \n Thay vì dần suy tàn trong tuyệt vọng, không bằng hãy tự tay xây dựng sự vĩ đại trước khi số phận đến."
  },
  Stage_72070_Name = {
    Text = "Con đường chưa đi"
  },
  Stage_72071_Desc = {
    Text = "Số từ trước đến nay không phải là tên, chỉ là ký hiệu. \nSinh mệnh tầm thường không muốn từ bỏ sự độc đáo hư cấu của bản thân, do đó chống lại việc dùng số để thay thế tên gọi của mình. \nCô ấy chẳng mảy may bận tâm."
  },
  Stage_72072_Desc = {
    Text = "Gừ... gừ... gừ. Cơ quan phát ra tiếng kêu đau đớn, khẩn thiết. \n Không phải tiếng bụng đói, sự trống rỗng này khởi nguồn từ não bộ."
  },
  Stage_72072_Name = {
    Text = "Lương thực của con người"
  },
  Stage_74229_Desc = {
    Text = "Bạn tình cờ gặp một chiếc váy bay phấp phới, chiếc váy xoay tròn giống như cánh thiên nga bay lượn, và cũng giống như một ngọn lửa bùng cháy."
  },
  Stage_74229_Name = {
    Text = "Lửa bất ngờ"
  },
  Stage_74230_Desc = {
    Text = "Đây không nên là đền thờ của nghệ thuật sao? Nếu không thì sao lại có nhiều điệu múa thanh lịch đến vậy.\nNhưng nơi này có thực sự là đền thờ nghệ thuật không? Nếu không thì tại sao lại đầy những ánh mắt lạnh lẽo và béo ngậy như vậy?"
  },
  Stage_74230_Name = {
    Text = "Băng cứng cháy"
  },
  Stage_74231_Desc = {
    Text = "Thiên nga trong giấc mơ bay lên cao, lại rơi xuống thất bại trong lưới của thợ săn."
  },
  Stage_74231_Name = {
    Text = "Giấc mơ đêm hè (A Midsummer Night's Dream)"
  },
  Stage_74232_Desc = {
    Text = "Những vũ công màu xanh đang nhảy múa trên sân khấu.\nNgọn lửa màu xanh đang bùng cháy trong những ngọn lửa.\nDành tặng bài hát tiễn biệt cuối cùng cho con thiên nga dũng cảm ra đi."
  },
  Stage_74232_Name = {
    Text = "Bài ca thiên nga"
  },
  Stage_74242_Desc = {
    Text = "Những vũ công màu xanh đang nhảy múa trên sân khấu.\nNgọn lửa màu xanh đang bùng cháy trong những ngọn lửa.\nDành tặng bài hát tiễn biệt cuối cùng cho con thiên nga dũng cảm ra đi."
  },
  Stage_74242_Name = {
    Text = "Bài ca thiên nga"
  },
  Stage_74243_Desc = {
    Text = "Những vũ công màu xanh đang nhảy múa trên sân khấu.\nNgọn lửa màu xanh đang bùng cháy trong những ngọn lửa.\nDành tặng bài hát tiễn biệt cuối cùng cho con thiên nga dũng cảm ra đi."
  },
  Stage_74243_Name = {
    Text = "Bài ca thiên nga"
  },
  Stage_74328_Desc = {
    Text = "Điều kiện đã sẵn sàng, máu đang sục sôi, bây giờ, cuộc đấu bắt đầu."
  },
  Stage_74328_Name = {
    Text = "Cuộc đấu ý chí kiên định"
  },
  Stage_74329_Desc = {
    Text = "Dù trong tình cảnh tuyệt vọng, cũng đừng từ bỏ hy vọng. Vì từng giây phút đều có thể trở thành khởi đầu để xoay chuyển tình thế."
  },
  Stage_74329_Name = {
    Text = "Khoảnh khắc đảo ngược muôn hình muôn vẻ"
  },
  Stage_74330_Desc = {
    Text = "Một tai nạn bất ngờ đã đưa một vị khách đặc biệt đến không gian đối đầu pha. Để giành lại không gian này, bạn bắt đầu hành trình trở thành đại sư thẻ bài mạnh nhất."
  },
  Stage_74330_Name = {
    Text = "Khách từ thế giới khác"
  },
  Stage_74975_Desc = {
    Text = "\"Nó là duy nhất. Nó là tất cả. Nó là hi vọng để mở ra cánh cổng Chân Lý.\"\nVô số chìa khóa tụ thành một vòng tròn. Chúng từ bầu trời rơi xuống, đem đến hi vọng nặng trĩu cho nhân loại.\nCũng như, những nấm mồ nặng tựa Thái Sơn."
  },
  Stage_74975_Name = {
    Text = "Thâm Nhập Mộng Ảo VI"
  },
  Stage_74976_Desc = {
    Text = "\"Nó là duy nhất. Nó là tất cả. Nó là hi vọng để mở ra cánh cổng Chân Lý.\"\nVô số chìa khóa tụ thành một vòng tròn. Chúng từ bầu trời rơi xuống, đem đến hi vọng nặng trĩu cho nhân loại.\nCũng như, những nấm mồ nặng tựa Thái Sơn."
  },
  Stage_74976_Name = {
    Text = "Thâm Nhập Mộng Ảo: Điên Cuồng"
  },
  Stage_74977_Desc = {
    Text = "\"Nó là duy nhất. Nó là tất cả. Nó là hi vọng để mở ra cánh cổng Chân Lý.\"\nVô số chìa khóa tụ thành một vòng tròn. Chúng từ bầu trời rơi xuống, đem đến hi vọng nặng trĩu cho nhân loại.\nCũng như, những nấm mồ nặng tựa Thái Sơn."
