  },
  Stage_7636_Desc = {
    Text = "Cô ấy dùng thân mình để chứa đựng thánh cốt, dùng giáo lý để hướng dẫn chúng tín, dùng răng độc để truyền bá tín ngưỡng."
  },
  Stage_7636_Name = {
    Text = "Bàn tay sùng kính III"
  },
  Stage_7637_Desc = {
    Text = "Trước khi các ngôi sao được sinh ra, chúng đã tồn tại ở đây. \nChúng vừa là hư vô, vừa là tất cả."
  },
  Stage_7637_Name = {
    Text = "Hỗn trộn tàn ảnh V"
  },
  Stage_7638_Desc = {
    Text = "Chúng âm thầm bảo vệ bí mật của đại dương, linh hồn sâu lắng như vũ trụ."
  },
  Stage_7638_Name = {
    Text = "Hải Uyên Tàn Tượng V(5)"
  },
  Stage_76399_Desc = {
    Text = "Khi bóng đêm của vực sâu tràn ra; tất cả kẻ xâm nhập đều quằn quại trong nỗi kinh hoàng tột độ trước khi bị nó nuốt chửng."
  },
  Stage_76399_Name = {
    Text = "Vùng Cấm - Thảm Họa Phân Giải: Đợt Thứ Tư: Cảnh Báo Bậc 5"
  },
  Stage_7639_Desc = {
    Text = "Chúng vặn vẹo, hòa quyện trong bóng tối, rồi được cẩn thận bảo quản trong tượng. \nĐây là một cuộc hội ngộ đã được dự mưu từ lâu."
  },
  Stage_7639_Name = {
    Text = "Chuyến đi siêu việt·「Khe hở」I"
  },
  Stage_76400_Desc = {
    Text = "Khi bóng đêm của vực sâu tràn ra; tất cả kẻ xâm nhập đều quằn quại trong nỗi kinh hoàng tột độ trước khi bị nó nuốt chửng."
  },
