  },
  Stage_7674_Desc = {
    Text = "Tượng thần sụp đổ quan sát con dân của nó; \nchứng kiến bọn họ sinh tồn, sinh sản, chiến đấu cùng nhau-- và cuối cùng, đánh mất chính mình trong quên lãng. \nTượng thần sụp đổ hoài niệm con dân của nó..."
  },
  Stage_7674_Name = {
    Text = "Thâm Nhập Mộng Ảo III"
  },
  Stage_7675_Desc = {
    Text = "Thị trấn ven biển —— Scarborough nằm ở North Yorkshire. Nơi đây có những vách đá cao chót vót và vịnh vàng, là một điểm nghỉ mát thanh lịch và quyến rũ."
  },
  Stage_7675_Name = {
    Text = "Mùa hè Scarborough"
  },
  Stage_7676_Desc = {
    Text = "Tượng thần sụp đổ quan sát con dân của nó; \nchứng kiến bọn họ sinh tồn, sinh sản, chiến đấu cùng nhau-- và cuối cùng, đánh mất chính mình trong quên lãng. \nTượng thần sụp đổ hoài niệm con dân của nó..."
  },
  Stage_7676_Name = {
    Text = "Thâm Nhập Mộng Ảo I"
  },
  Stage_7677_Desc = {
    Text = "Một con chuột nhỏ, một con chuột nhỏ. \n chạy đi, chạy đi, cô ấy dùng dao cắt thịt để cắt đứt đuôi của nó."
  },
  Stage_7677_Name = {
    Text = "Brun tấn công"
  },
  Stage_7678_Desc = {
    Text = "Tượng thần sụp đổ quan sát con dân của nó; \nchứng kiến bọn họ sinh tồn, sinh sản, chiến đấu cùng nhau-- và cuối cùng, đánh mất chính mình trong quên lãng. \nTượng thần sụp đổ hoài niệm con dân của nó..."
