  Stage_7679_Name = {
    Text = "Thâm Nhập Mộng Ảo VI"
  },
  Stage_7680_Desc = {
    Text = "Ô, cánh tay, những cánh tay phiền toái! Chúng luôn kéo tóc tôi không buông."
  },
  Stage_7680_Name = {
    Text = "Hai mươi tư"
  },
  Stage_7681_Desc = {
    Text = "Bộp bộp, nứt ra rồi. \nbộp bộp, gãy rồi."
  },
  Stage_7681_Name = {
    Text = "Bảo tàng Búp bê"
  },
  Stage_7682_Desc = {
    Text = "Đúng rồi, em yêu. Hãy khóc đi, hãy biến nỗi đau của bạn thành một kiệt tác để trân trọng."
  },
  Stage_7682_Name = {
    Text = "Cô gái và nước mắt"
  },
  Stage_7683_Desc = {
    Text = "Đúng, đúng. Mắt là chuồng giam của tâm hồn, linh hồn là xiềng xích giam giữ thân xác."
  },
  Stage_7683_Name = {
    Text = "Nỗi buồn của giải phẫu"
  },
  Stage_7684_Desc = {
    Text = "Ngọt ngào, thơm ngon, niềm yêu thích của trẻ em. \n tao nhã, khát vọng, ước mơ của người lớn."
  },
  Stage_7684_Name = {
    Text = "Nghệ thuật ngọt ngào"
  },
  Stage_76854_Desc = {
