  Stage_77103_Name = {
    Text = "Vùng Cấm - Thảm Họa Phân Giải: Đợt Thứ Năm: Cảnh Báo Bậc 3"
  },
  Stage_7710_Desc = {
    Text = "Nhật ký là những phân mảnh của ký ức. \nTrong quá trình điều tra, luôn tìm thấy nhật ký."
  },
  Stage_7710_Name = {
    Text = "Phân mảnh ký ức"
  },
  Stage_7711_Desc = {
    Text = "Đây là một thế giới được tạo riêng cho cô ấy, là tình yêu vĩ đại nhưng cũng là một nhà tù đáng sợ."
  },
  Stage_7711_Name = {
    Text = "Bệnh viện tinh thần"
  },
  Stage_7712_Desc = {
    Text = "Khi các quý tộc mất quyền lực, khi những người giàu có bị phá sản, họ không thể tiến thêm một bước nào, giống như chính bạn hiện tại."
  },
  Stage_7712_Name = {
    Text = "Vượt qua bức tường điên loạn"
  },
  Stage_7713_Desc = {
    Text = "Cuộc giao tranh trên thế gian không chỉ diễn ra trên chiến trường nơi lưỡi kiếm va chạm, mà đôi khi còn tồn tại trong miệng của những kẻ điên rồ."
  },
  Stage_7713_Name = {
    Text = "Miệng kẻ điên"
  },
  Stage_7714_Desc = {
    Text = "Dấu vết bị cuốn vào sương mù, vô số bước chân lang thang trên đó, mỗi điểm đặt chân đều là sự chất vấn đối với số phận."
  },
  Stage_7714_Name = {
    Text = "Lối đi mù mịt"
  },
  Stage_7715_Desc = {
    Text = "Ngọn lửa cháy trong im lặng, hứa với người lữ khách những lời hứa giả dối."
  },
  Stage_7715_Name = {
    Text = "lửa dụ dỗ"
  },
  Stage_7716_Desc = {
    Text = "Dâng lên thực tại tạo nên từ thịt và máu, chúng là hố sâu không bao giờ no đủ."
  },
  Stage_7716_Name = {
    Text = "Hình ảnh cơ chất V"
  },
  Stage_7717_Desc = {
    Text = "Giông bão vẫn đang tích tụ, tất cả vẫn chưa đi đến hồi kết."
  },
  Stage_7717_Name = {
    Text = "Khởi động lại thực tế"
  },
  Stage_7718_Desc = {
    Text = "Đi về đất liền, đi về tia sáng cuối đường hầm."
  },
  Stage_7718_Name = {
    Text = "Khởi đầu bi thảm"
  },
  Stage_7719_Desc = {
    Text = "Đó tuyệt đối không phải là sức sống được mong đợi, chỉ là con ký sinh trùng ô uế mà thôi."
  },
  Stage_7719_Name = {
    Text = "Ký sinh trùng"
  },
  Stage_7720_Desc = {
    Text = "Trong bóng tối vô tận của màn đêm, đuổi theo ánh sáng mê hoặc, giống như một con thiêu thân lao vào ánh lửa, bất chấp tất cả để bay về phía ánh hào quang số phận."
  },
  Stage_7720_Name = {
    Text = "Bướm đuổi lửa"
  },
  Stage_7721_Desc = {
    Text = "Đêm tối bị dòng chảy đen tối xâm chiếm, tinh tú im bặt. Tháng nguy hiểm ẩn chứa sự thay đổi và giông tố, lặng lẽ soi rọi tương lai vô định."
  },
  Stage_7721_Name = {
    Text = "Mặt Trăng Nguy Hiểm"
  },
  Stage_7722_Desc = {
    Text = "R run rúng trong cơn gió số phận, đấu tranh, nhưng nó sẽ không thực sự tan biến."
  },
  Stage_7722_Name = {
    Text = "Sắp đổ"
  },
  Stage_7723_Desc = {
    Text = "Tình bạn chập chờn trong những năm tháng đã qua, nay đơm hoa kết trái thành hy vọng mới."
  },
  Stage_7723_Name = {
    Text = "Bạn cũ bạn mới"
  },
  Stage_7724_Desc = {
    Text = "Quốc độ của Ngài là xác thân của vũ trụ, ham muốn của Ngài không giới hạn."
  },
  Stage_7724_Name = {
    Text = "Khu III của giun"
  },
  Stage_7725_Desc = {
    Text = "Dâng lên thực tại tạo nên từ thịt và máu, chúng là hố sâu không bao giờ no đủ."
  },
  Stage_7725_Name = {
    Text = "Dư ảnh vật chất II"
  },
  Stage_7726_Desc = {
    Text = "Chúng vốn là tập hợp vô thức của nỗi buồn, sự méo mó và bối rối, \n nhưng lại được ngụy trang thành những đứa trẻ, người lớn và thú cưng hạnh phúc. \n Vì chưa bao giờ biết đến hạnh phúc, chúng trở thành những diễn viên tồi tệ nhất."
  },
  Stage_7726_Name = {
    Text = "Bí mật bình tượng nến I"
  },
  Stage_7727_Desc = {
    Text = "Nó dựa vào mép giường với dáng vẻ ngoan ngoãn, đôi mắt nút mờ nhạt nhìn vào hư không. \nThân thể nhỏ bé gánh vác tất cả những giọt nước mắt của chủ nhân, nhưng không thể lên tiếng an ủi."
  },
  Stage_7727_Name = {
    Text = "Nước mắt búp bê I"
  },
  Stage_7728_Desc = {
    Text = "\"Nó là duy nhất. Nó là tất cả. Nó là hi vọng để mở ra cánh cổng Chân Lý.\"\nVô số chìa khóa tụ thành một vòng tròn. Chúng từ bầu trời rơi xuống, đem đến hi vọng nặng trĩu cho nhân loại.\nCũng như, những nấm mồ nặng tựa Thái Sơn."
  },
  Stage_7728_Name = {
    Text = "Thâm Nhập Mộng Ảo I"
  },
