  },
  Stage_7805_Name = {
    Text = "Di sản biển sâu · Khe hở luân chuyển III"
  },
  Stage_7806_Desc = {
    Text = "Thị trấn Rai nằm ở phía đông bắc của Lentiennam, ẩn sâu trong dãy núi liên tục. \n Người dân im lặng, ánh mắt theo dõi khắp nơi… Hãy cẩn thận, mọi thứ ở đây đều không bình thường."
  },
  Stage_7806_Name = {
    Text = "Thị trấn hỗn loạn III"
  },
  Stage_7807_Desc = {
    Text = "\"Nó là duy nhất. Nó là tất cả. Nó là hi vọng để mở ra cánh cổng Chân Lý.\"\nVô số chìa khóa tụ thành một vòng tròn. Chúng từ bầu trời rơi xuống, đem đến hi vọng nặng trĩu cho nhân loại.\nCũng như, những nấm mồ nặng tựa Thái Sơn."
  },
  Stage_7807_Name = {
    Text = "Thâm Nhập Mộng Ảo I"
  },
  Stage_7808_Desc = {
    Text = "\"Nó là duy nhất. Nó là tất cả. Nó là hi vọng để mở ra cánh cổng Chân Lý.\"\nVô số chìa khóa tụ thành một vòng tròn. Chúng từ bầu trời rơi xuống, đem đến hi vọng nặng trĩu cho nhân loại.\nCũng như, những nấm mồ nặng tựa Thái Sơn."
  },
