  Stage_7813_Name = {
    Text = "Thâm Nhập Mộng Ảo VI"
  },
  Stage_7814_Desc = {
    Text = "Đó là thanh kiếm khổng lồ của người muốn xé toạc đại dương, là khát vọng chế ngự mọi biển cả."
  },
  Stage_7814_Name = {
    Text = "Kẻ cuồng nộ và đại kiếm"
  },
  Stage_7815_Desc = {
    Text = "Hiện thực đã gieo rắc mầm họa, nhưng số phận lại dẫn lối cho cuộc gặp gỡ."
  },
  Stage_7815_Name = {
    Text = "Hạt giống định mệnh"
  },
  Stage_7816_Desc = {
    Text = "Sứ đồ vượt qua muôn biển."
  },
  Stage_7816_Name = {Text = "Sứ đồ"},
  Stage_7817_Desc = {
    Text = "Trên một con tàu, ngoài thuyền trưởng, thì ai còn đáng tin cậy?"
  },
  Stage_7817_Name = {
    Text = "Thủy thủ"
  },
  Stage_7818_Desc = {
    Text = "Khi không còn đường lui, người bạn được đào tạo bài bản thường là chìa khóa để phá vỡ thế bế tắc — Ramona đã dạy bạn điều này một lần nữa."
  },
  Stage_7818_Name = {
    Text = "Không lối thoát"
  },
  Stage_7819_Desc = {
    Text = "Đạp vỡ muôn biển mà qua, ngoài kẻ thù, có lẽ còn có ánh sáng hy vọng."
  },
  Stage_7819_Name = {
    Text = "Kẻ sa đà"
  },
  Stage_7820_Desc = {
    Text = "Cảng biển về đêm, người dân chân chất, sự đón tiếp nồng hậu."
  },
  Stage_7820_Name = {
    Text = "Vây hãm tứ phía"
  },
  Stage_7821_Desc = {
    Text = "\"Cửa\" sắp mở ra, bạn nhìn thấy một phần sự thật. \nKhông phải màu đen, cũng không phải màu trắng — sự thật là đa sắc màu, cũng như mờ đục."
  },
  Stage_7821_Name = {
    Text = "Di sản Biển Sâu · Khe Hở Xoay Chuyển II"
  },
  Stage_7822_Desc = {
    Text = "\"Cửa\" sắp mở ra, bạn nhìn thấy một phần sự thật. \nKhông phải màu đen, cũng không phải màu trắng — sự thật là đa sắc màu, cũng như mờ đục."
  },
  Stage_7822_Name = {
    Text = "Di sản Biển Sâu · Khe Hở Xoay Chuyển II"
  },
  Stage_7823_Desc = {
    Text = "\"Cửa\" sắp mở ra, bạn nhìn thấy một phần sự thật. \nKhông phải màu đen, cũng không phải màu trắng — sự thật là đa sắc màu, cũng như mờ đục."
  },
  Stage_7823_Name = {
    Text = "Di sản Biển Sâu · Khe Hở Xoay Chuyển II"
  },
  Stage_7824_Desc = {
    Text = "Trái tim thứ hai trong cơ thể Muphí đang đập, ngăn chặn \"Nghi lễ Giáng Sinh\"đang trở nên cấp bách."
  },
  Stage_7824_Name = {
    Text = "Một kỳ tích khác"
  },
  Stage_7825_Desc = {
    Text = "Vượt qua vòng vây chưa bao giờ là dễ dàng, nhưng may mắn thay, lần này Người Giữ Gìn đã tìm thấy ngôi sao sáng nhất."
  },
  Stage_7825_Name = {
    Text = "Đuổi theo những vì sao"
  },
  Stage_7826_Desc = {
    Text = "Bảo tàng sáp Rogers nằm ở cuối đường Southwark, gần nhánh sông Thames. \nNó không hề nổi bật, nhưng thu hút nhiều người đam mê nghệ thuật đương đại đến tham quan."
  },
  Stage_7826_Name = {
    Text = "Phòng trưng bày nến cuồng nộ I"
  },
  Stage_7827_Desc = {
    Text = "Ông ấy không phải là Ngài, Ngài không thể là ông ấy. \nĐúng vậy… Đúng vậy, chỉ có thần minh của tôi mới là đấng chân chính."
  },
  Stage_7827_Name = {
    Text = "Ánh sáng thất lạc"
  },
  Stage_7830_Desc = {
    Text = "\nĐã từng có một trường đại học tồn tại, nỗ lực đem đến tia hi vọng mong manh cùng dũng khí cho loài người \nVề phần kết cục của nó, hiện tại chúng ta đang được chứng kiến - bị chôn vùi trong vụn vỡ và hoang tàn."
  },
  Stage_7830_Name = {
    Text = "Thâm Nhập Mộng Ảo V"
  },
  Stage_7831_Desc = {
    Text = "\nĐã từng có một trường đại học tồn tại, nỗ lực đem đến tia hi vọng mong manh cùng dũng khí cho loài người \nVề phần kết cục của nó, hiện tại chúng ta đang được chứng kiến - bị chôn vùi trong vụn vỡ và hoang tàn."
  },
  Stage_7831_Name = {
    Text = "Thâm Nhập Mộng Ảo II"
  },
  Stage_7832_Desc = {
    Text = "\nĐã từng có một trường đại học tồn tại, nỗ lực đem đến tia hi vọng mong manh cùng dũng khí cho loài người \nVề phần kết cục của nó, hiện tại chúng ta đang được chứng kiến - bị chôn vùi trong vụn vỡ và hoang tàn."
  },
  Stage_7832_Name = {
    Text = "Thâm Nhập Mộng Ảo III"
  },
  Stage_7833_Desc = {
    Text = "\nĐã từng có một trường đại học tồn tại, nỗ lực đem đến tia hi vọng mong manh cùng dũng khí cho loài người \nVề phần kết cục của nó, hiện tại chúng ta đang được chứng kiến - bị chôn vùi trong vụn vỡ và hoang tàn."
  },
  Stage_7833_Name = {
    Text = "Thâm Nhập Mộng Ảo I"
  },
  Stage_7834_Desc = {
    Text = "Điều hoành hành ở đây không phải là một căn bệnh thông thường."
  },
  Stage_7834_Name = {Text = "Bệnh"},
  Stage_7835_Desc = {
    Text = "Trong làn sương mù dày đặc bao phủ nhà tế bần, chạm vào sự cắt đứt, sự biến mất và cái chết."
  },
  Stage_7835_Name = {
    Text = "Ai đã giết chim sâu"
  },
  Stage_7836_Desc = {
    Text = "Quốc độ của Ngài là xác thân của vũ trụ, ham muốn của Ngài không giới hạn."
  },
  Stage_7836_Name = {
    Text = "Sở của sâu bọ V"
  },
  Stage_7837_Desc = {
    Text = "Bạn và Ramona đến Bệnh viện Từ thiện Lily ở phía đông Lentiennam, để bắt đầu cuộc điều tra đầu tiên của bạn với tư cách là một Người Giữ Gìn mới. \nMọi thứ sẽ suôn sẻ, phải không?"
  },
  Stage_7837_Name = {
    Text = "Đừng trông mặt mà bắt hình dong"
  },
  Stage_7838_Desc = {
    Text = "Ngọt ngào, thơm ngon, niềm yêu thích của trẻ em. \n tao nhã, khát vọng, ước mơ của người lớn."
  },
  Stage_7838_Name = {
    Text = "Nghệ thuật ngọt ngào"
  },
  Stage_7839_Desc = {
    Text = "Gánh nặng của lương tâm tương đương với lời thề."
  },
  Stage_7839_Name = {
    Text = "Gánh nặng của lương tâm"
  },
  Stage_7840_Desc = {
    Text = "Nguy hiểm đến từ bên trong."
  },
  Stage_7840_Name = {
    Text = "Mối nguy hiểm tiềm ẩn"
  },
  Stage_7841_Desc = {
    Text = "Tôi rất muốn mãi không lớn lên, mỗi ngày đều cùng bạn ngắm sao. \nTôi rất muốn mau mau lớn lên, để có thể bảo vệ tất cả mọi người thân yêu."
  },
  Stage_7841_Name = {
    Text = "Bí mật của chúng ta"
  },
  Stage_7842_Desc = {
    Text = "Cắt đứt những sợi dây mỏng trên thân con rối, cô ấy sẽ không bao giờ nhảy múa nữa."
  },
  Stage_7842_Name = {
    Text = "Đêm vắng bóng chim"
  },
  Stage_7843_Desc = {
    Text = "Điều bạn muốn biết, đều ở ngay trước mắt bạn, nhưng bạn chưa bao giờ phát hiện ra."
  },
  Stage_7843_Name = {
    Text = "Ẩn dưới vành mũ"
  },
  Stage_7844_Desc = {
    Text = "Ramona đã trở lại đội. Misaque tiếp tục cuộc hành trình."
  },
  Stage_7844_Name = {
    Text = "Hôm qua trở lại"
  },
  Stage_7845_Desc = {
    Text = "Chân người không thể sánh bằng sự nhanh nhẹn của động vật hoang dã bốn chân, nhưng trí óc có thể. Chỉ là, sau khi bắt được \"chó địa ngục\", điều gì đang chờ đợi các ngươi?"
  },
  Stage_7845_Name = {
    Text = "Lá bài bí mật"
  },
  Stage_7846_Desc = {
    Text = "Chúc bạn có chuyến đi vui vẻ."
  },
  Stage_7846_Name = {
    Text = "Chúc bạn một chuyến đi vui vẻ"
  },
  Stage_7847_Desc = {
    Text = "Trong tàu điện ngầm, các bạn đã bị một sát thủ bí ẩn tấn công……"
  },
  Stage_7847_Name = {
    Text = "Cuộc đời không có bạn bè"
  },
  Stage_7848_Desc = {
    Text = "Sự giao dịch với Bà Daphne luôn được cấu thành từ các thỏa thuận. Bà Daphne xuất hiện và đề xuất một thỏa thuận với các bạn. Liệu kẻ tấn công bí ẩn có chấp nhận thỏa thuận này không?"
  },
  Stage_7848_Name = {
    Text = "Giao dịch công bằng"
  },
  Stage_7849_Desc = {
    Text = "Truy tìm những lời đồn đại về chó địa ngục \"Cerberus\", các điều tra viên của Misaque đã đến thị trấn Rai ở vùng ngoại ô Lentiennam, khám phá bí ẩn đằng sau các vụ mất tích…"
  },
  Stage_7849_Name = {
    Text = "Cân nhắc kỹ lưỡng trước khi hành động"
  },
  Stage_7850_Desc = {
    Text = "Một tin tốt, một tin xấu. Dấu vết đã mất sẽ không xuất hiện lại, nhưng một vụ án mới đang dần hình thành trong bóng tối. Hãy tin tưởng, điều tra viên sẽ không ra về tay trắng."
  },
  Stage_7850_Name = {
    Text = "Tin tốt, tin xấu"
  },
  Stage_7851_Desc = {
    Text = "Giọng điệu điên cuồng, mùi tanh nồng đậm, đây chính là nghi thức chào đón từ Lai."
  },
  Stage_7851_Name = {
    Text = "Chào mừng bạn đến với Lai"
  },
  Stage_7852_Desc = {
    Text = "Nó dựa vào mép giường với dáng vẻ ngoan ngoãn, đôi mắt nút mờ nhạt nhìn vào hư không. \nThân thể nhỏ bé gánh vác tất cả những giọt nước mắt của chủ nhân, nhưng không thể lên tiếng an ủi."
  },
  Stage_7852_Name = {
    Text = "Nước mắt búp bê III"
  },
  Stage_7855_Desc = {
    Text = "Ông ấy không phải là Ngài, Ngài không thể là ông ấy. \nĐúng vậy… Đúng vậy, chỉ có thần minh của tôi mới là đấng chân chính."
  },
  Stage_7855_Name = {
    Text = "Ánh sáng thất lạc"
  },
  Stage_7856_Desc = {
    Text = "Trước khi các ngôi sao được sinh ra, chúng đã tồn tại ở đây. \nChúng vừa là hư vô, vừa là tất cả."
  },
  Stage_7856_Name = {
    Text = "Hình ảnh mờ ảo IV"
  },
  Stage_7857_Desc = {
    Text = "Chúng âm thầm bảo vệ bí mật của đại dương, linh hồn sâu lắng như vũ trụ."
  },
  Stage_7857_Name = {
    Text = "Hải Uyên Tàn Tượng II"
  },
  Stage_7858_Desc = {
    Text = "Làm thế nào có hoàng hôn vĩnh viễn không lặn?"
  },
  Stage_7858_Name = {
    Text = "Hoàng hôn"
  },
  Stage_7859_Desc = {
    Text = "Khi màn mưa rơi xuống, máu tươi trào ra, chúng ta chào đón khoảnh khắc tái ngộ. \nĐã lâu không gặp, Người Giữ Gìn."
  },
  Stage_7859_Name = {
    Text = "Cuộc gặp bất ngờ"
  },
  Stage_7860_Desc = {
    Text = "Chúng giống như những phù thủy khó đoán, lang thang giữa các kẽ hở thời gian và không gian. \n Không có thù hận, không có sợ hãi, cũng không có lòng thương xót."
  },
  Stage_7860_Name = {
    Text = "Ảnh chiều không gian I"
  },
  Stage_7861_Desc = {
    Text = "Nó không ngừng truy đuổi những kẻ vi phạm quy tắc. \nVề việc gì là \"quy tắc\", gì là \"vi phạm\"? \nChó săn không bao giờ suy nghĩ — điều đó chỉ cản trở tốc độ tấn công của nó."
  },
  Stage_7861_Name = {
    Text = "Bóng Ma Ngoài Giới IV"
  },
  Stage_7862_Desc = {
    Text = "Chúng âm thầm bảo vệ bí mật của đại dương, linh hồn sâu lắng như vũ trụ."
  },
  Stage_7862_Name = {
    Text = "Hải Uyên Dư Ảnh III"
  },
  Stage_7863_Desc = {
    Text = "Chúng âm thầm bảo vệ bí mật của đại dương, linh hồn sâu lắng như vũ trụ."
  },
  Stage_7863_Name = {
    Text = "Hải Uyên Ảnh Tàn I"
  },
  Stage_7864_Desc = {
    Text = "Lentiennam nổi tiếng với nền văn minh công nghiệp rực rỡ và lớp sương mù màu chì xám bao phủ thành phố. \nSương mù hiện diện khắp nơi, đối với người đi đường, nó giống như một sự bất tiện ngẫu nhiên và không đáng kể."
  },
  Stage_7864_Name = {
    Text = "Thành phố Sương Quái I"
  },
  Stage_7865_Desc = {
    Text = "Là điều gì đã che mờ đôi mắt của cô ấy? \n Là tình yêu, lòng thương xót, công lý và sự biết ơn quá mức sao?"
  },
  Stage_7865_Name = {
    Text = "Vượt thoát"
  },
  Stage_7866_Desc = {
    Text = "Trẻ em đưa đôi tay về phía mẹ, cầu xin một cái ôm đầy đau đớn. \nDù kim tiêm đâm thủng làn da mỏng manh, dao phẫu thuật rạch qua làn da trắng trẻo, dây ràng buộc siết chặt các khớp mềm yếu. \nNỗi đau lan tỏa không ngừng vẫn không thể ngăn cản họ ôm nhau. \nBởi vì, đây là cái ôm ấm áp nhất. Từ khi phôi thai rời khỏi cơ thể mẹ, sinh ra khoảng cách, mài giũa thành sắc bén, gây thương tổn lẫn nhau, cuối cùng trở lại gần gũi, hòa làm một."
  },
  Stage_7866_Name = {Text = "Cô ấy"},
  Stage_7867_Desc = {
    Text = "Bạn chìm vào sự yên tĩnh của đêm, \n không còn bất kỳ nghi ngờ hay tranh cãi nào, \n như được ôm trọn trong vòng tay vĩnh cửu, \n chúng ta nằm trong sự bình yên, an lành."
  },
  Stage_7867_Name = {Text = "Phòng"},
  Stage_7868_Desc = {
    Text = "Cánh đồng tuyết trắng xóa, bách hợp nở rộ."
  },
  Stage_7868_Name = {
    Text = "Sông bí ẩn"
  },
  Stage_7869_Desc = {
    Text = "Bình minh luôn đến, mặt trời vẫn mọc như mọi khi."
  },
  Stage_7869_Name = {
    Text = "Phần kết"
  },
  Stage_7870_Desc = {
    Text = "Cô ấy dùng thân mình để chứa đựng thánh cốt, dùng giáo lý để hướng dẫn chúng tín, dùng răng độc để truyền bá tín ngưỡng."
  },
  Stage_7870_Name = {
    Text = "Bàn tay sùng kính II"
  },
  Stage_7871_Desc = {
    Text = "Đầu nhọn sắc bén phá vỡ đường tròn tuyệt đối, không phải vật của \"Cerberus\" sinh ra từ khe nứt."
  },
  Stage_7871_Name = {
    Text = "Vết nứt trên vỏ"
  },
  Stage_7872_Desc = {
    Text = "Hiện thực đã gieo rắc mầm họa, nhưng số phận lại dẫn lối cho cuộc gặp gỡ."
  },
  Stage_7872_Name = {
    Text = "Hạt giống định mệnh"
  },
  Stage_78738_Name = {
    Text = "Chủ nhân nguồn gốc đang ngủ say - Màn chơi thử"
  },
  Stage_7873_Desc = {
    Text = "Chúng vặn vẹo, hòa quyện trong bóng tối, rồi được cẩn thận bảo quản trong tượng. \nĐây là một cuộc hội ngộ đã được dự mưu từ lâu."
  },
  Stage_7873_Name = {
    Text = "Di sản Biển Sâu · Khe hở V"
  },
  Stage_7874_Desc = {
    Text = "Trên một con tàu, ngoài thuyền trưởng, thì ai còn đáng tin cậy?"
  },
  Stage_7874_Name = {
    Text = "Thủy thủ"
  },
  Stage_7875_Desc = {
    Text = "Sứ đồ vượt qua muôn biển."
  },
  Stage_7875_Name = {Text = "Sứ đồ"},
  Stage_7876_Desc = {
    Text = "Đạp vỡ muôn biển mà qua, ngoài kẻ thù, có lẽ còn có ánh sáng hy vọng."
  },
  Stage_7876_Name = {
    Text = "Kẻ sa đà"
  },
  Stage_78773_Name = {
    Text = "Nguồn gốc Quý cô biển sâu: thử thách"
  },
  Stage_7877_Desc = {
    Text = "Chúng vốn là tập hợp vô thức của nỗi buồn, sự méo mó và bối rối, \n nhưng lại được ngụy trang thành những đứa trẻ, người lớn và thú cưng hạnh phúc. \n Vì chưa bao giờ biết đến hạnh phúc, chúng trở thành những diễn viên tồi tệ nhất."
  },
  Stage_7877_Name = {
    Text = "Bí ẩn tượng sáp II"
  },
  Stage_7878_Desc = {
    Text = "Cảng biển về đêm, người dân chân chất, sự đón tiếp nồng hậu."
  },
  Stage_7878_Name = {
    Text = "Vây hãm tứ phía"
  },
  Stage_7879_Desc = {
    Text = "Những pho tượng có nguồn gốc không rõ ràng lang thang, run rẩy trong bóng tối. \nChúng bước theo nhịp điệu cổ xưa, nhảy múa theo tiếng sáo từ xa vọng lại."
  },
  Stage_7879_Name = {
    Text = "Bãi lầy của thịt và máu · khe hở VIII"
  },
  Stage_7880_Desc = {
    Text = "Vượt qua vòng vây chưa bao giờ là dễ dàng, nhưng may mắn thay, lần này Người Giữ Gìn đã tìm thấy ngôi sao sáng nhất."
  },
  Stage_7880_Name = {
    Text = "Đuổi theo những vì sao"
  },
  Stage_7881_Desc = {
    Text = "Trái tim thứ hai trong cơ thể Muphí đang đập, ngăn chặn \"Nghi lễ Giáng Sinh\"đang trở nên cấp bách."
  },
  Stage_7881_Name = {
    Text = "Một kỳ tích khác"
  },
  Stage_7882_Desc = {
    Text = "Những pho tượng có nguồn gốc không rõ ràng lang thang, run rẩy trong bóng tối. \nChúng bước theo nhịp điệu cổ xưa, nhảy múa theo tiếng sáo từ xa vọng lại."
  },
  Stage_7882_Name = {
    Text = "Vùng Hỗn Loạn - Khe Hở VII"
  },
  Stage_7883_Desc = {
    Text = "Thật, sự thật tàn nhẫn này."
  },
  Stage_7883_Name = {
    Text = "Dưới tấm màn che"
  },
  Stage_7884_Desc = {
    Text = "Ngọn lửa cháy trong im lặng, hứa với người lữ khách những lời hứa giả dối."
  },
  Stage_7884_Name = {
    Text = "lửa dụ dỗ"
  },
  Stage_7885_Desc = {
    Text = "R run rúng trong cơn gió số phận, đấu tranh, nhưng nó sẽ không thực sự tan biến."
  },
  Stage_7885_Name = {
    Text = "Sắp đổ"
  },
  Stage_7886_Desc = {
    Text = "Dấu vết bị cuốn vào sương mù, vô số bước chân lang thang trên đó, mỗi điểm đặt chân đều là sự chất vấn đối với số phận."
  },
  Stage_7886_Name = {
    Text = "Lối đi mù mịt"
  },
  Stage_7887_Desc = {
    Text = "Tượng thần sụp đổ quan sát con dân của nó; \nchứng kiến bọn họ sinh tồn, sinh sản, chiến đấu cùng nhau-- và cuối cùng, đánh mất chính mình trong quên lãng. \nTượng thần sụp đổ hoài niệm con dân của nó..."
  },
  Stage_7887_Name = {
    Text = "Thâm Nhập Mộng Ảo IV"
  },
  Stage_7888_Desc = {
    Text = "Một đống chất thô lỗ, chưa được tiêu hóa. Người ta gọi nó là chất thải, hay là hỗn loạn. \nThế giới được sinh ra từ chất thải."
  },
  Stage_7888_Name = {
    Text = "Hỗn loạn cụm I"
  },
  Stage_7889_Desc = {
    Text = "Khi những người ra đi bị quên lãng, mọi thứ sẽ trở lại bình thường. \nNhưng những ký ức đã tan biến, sẽ luôn có người ghi nhớ."
  },
  Stage_7889_Name = {
    Text = "Mọi thứ vẫn bình thường"
  },
  Stage_7890_Desc = {
    Text = "\"Nó là duy nhất. Nó là tất cả. Nó là hi vọng để mở ra cánh cổng Chân Lý.\"\nVô số chìa khóa tụ thành một vòng tròn. Chúng từ bầu trời rơi xuống, đem đến hi vọng nặng trĩu cho nhân loại.\nCũng như, những nấm mồ nặng tựa Thái Sơn."
  },
  Stage_7890_Name = {
    Text = "Thâm Nhập Mộng Ảo V"
  },
  Stage_7891_Desc = {
    Text = "Tượng thần sụp đổ quan sát con dân của nó; \nchứng kiến bọn họ sinh tồn, sinh sản, chiến đấu cùng nhau-- và cuối cùng, đánh mất chính mình trong quên lãng. \nTượng thần sụp đổ hoài niệm con dân của nó..."
  },
  Stage_7891_Name = {
    Text = "Thâm Nhập Mộng Ảo I"
  },
  Stage_7892_Desc = {
    Text = "Tượng thần sụp đổ quan sát con dân của nó; \nchứng kiến bọn họ sinh tồn, sinh sản, chiến đấu cùng nhau-- và cuối cùng, đánh mất chính mình trong quên lãng. \nTượng thần sụp đổ hoài niệm con dân của nó..."
  },
  Stage_7892_Name = {
    Text = "Thâm Nhập Mộng Ảo II"
  },
  Stage_7893_Desc = {
    Text = "Tượng thần sụp đổ quan sát con dân của nó; \nchứng kiến bọn họ sinh tồn, sinh sản, chiến đấu cùng nhau-- và cuối cùng, đánh mất chính mình trong quên lãng. \nTượng thần sụp đổ hoài niệm con dân của nó..."
  },
  Stage_7893_Name = {
    Text = "Thâm Nhập Mộng Ảo III"
  },
  Stage_7894_Desc = {
    Text = "Tượng thần sụp đổ quan sát con dân của nó; \nchứng kiến bọn họ sinh tồn, sinh sản, chiến đấu cùng nhau-- và cuối cùng, đánh mất chính mình trong quên lãng. \nTượng thần sụp đổ hoài niệm con dân của nó..."
  },
  Stage_7894_Name = {
    Text = "Thâm Nhập Mộng Ảo IV"
  },
  Stage_7895_Desc = {
    Text = "Tượng thần sụp đổ quan sát con dân của nó; \nchứng kiến bọn họ sinh tồn, sinh sản, chiến đấu cùng nhau-- và cuối cùng, đánh mất chính mình trong quên lãng. \nTượng thần sụp đổ hoài niệm con dân của nó..."
  },
  Stage_7895_Name = {
    Text = "Thâm Nhập Mộng Ảo V"
  },
  Stage_7896_Desc = {
    Text = "Tượng thần sụp đổ quan sát con dân của nó; \nchứng kiến bọn họ sinh tồn, sinh sản, chiến đấu cùng nhau-- và cuối cùng, đánh mất chính mình trong quên lãng. \nTượng thần sụp đổ hoài niệm con dân của nó..."
  },
  Stage_7896_Name = {
    Text = "Thâm Nhập Mộng Ảo VI"
  },
  Stage_7897_Desc = {
    Text = "Tượng thần sụp đổ quan sát con dân của nó; \nchứng kiến bọn họ sinh tồn, sinh sản, chiến đấu cùng nhau-- và cuối cùng, đánh mất chính mình trong quên lãng. \nTượng thần sụp đổ hoài niệm con dân của nó..."
  },
  Stage_7897_Name = {
    Text = "Thâm Nhập Mộng Ảo VII"
  },
  Stage_7898_Desc = {
    Text = "Trong làn sương mù dày đặc bao phủ nhà tế bần, chạm vào sự cắt đứt, sự biến mất và cái chết."
  },
  Stage_7898_Name = {
    Text = "Ai đã giết chim sâu"
  },
  Stage_7899_Desc = {
    Text = "Điều hoành hành ở đây không phải là một căn bệnh thông thường."
  },
  Stage_7899_Name = {Text = "Bệnh"},
  Stage_7900_Desc = {
    Text = "Bạn và Ramona đến Bệnh viện Từ thiện Lily ở phía đông Lentiennam, để bắt đầu cuộc điều tra đầu tiên của bạn với tư cách là một Người Giữ Gìn mới. \nMọi thứ sẽ suôn sẻ, phải không?"
  },
  Stage_7900_Name = {
    Text = "Đừng trông mặt mà bắt hình dong"
  },
  Stage_7901_Desc = {
    Text = "Gánh nặng của lương tâm tương đương với lời thề."
  },
  Stage_7901_Name = {
    Text = "Gánh nặng của lương tâm"
  },
  Stage_7902_Desc = {
    Text = "Ngọt ngào, thơm ngon, niềm yêu thích của trẻ em. \n tao nhã, khát vọng, ước mơ của người lớn."
  },
  Stage_7902_Name = {
    Text = "Nghệ thuật ngọt ngào"
  },
  Stage_7903_Desc = {
    Text = "Tôi rất muốn mãi không lớn lên, mỗi ngày đều cùng bạn ngắm sao. \nTôi rất muốn mau mau lớn lên, để có thể bảo vệ tất cả mọi người thân yêu."
  },
  Stage_7903_Name = {
    Text = "Bí mật của chúng ta"
  },
  Stage_7904_Desc = {
    Text = "Nguy hiểm đến từ bên trong."
  },
  Stage_7904_Name = {
    Text = "Mối nguy hiểm tiềm ẩn"
  },
  Stage_7905_Desc = {
    Text = "\"cửa\"đã được mở, ảo mộng sắp tỉnh giấc. \n Suỵt... đừng nhìn, đừng nghe."
  },
  Stage_7905_Name = {
    Text = "Thịt máu chiểu · khe hở luân chuyển IV"
  },
  Stage_7906_Desc = {
    Text = "\"cửa\"đã được mở, ảo mộng sắp tỉnh giấc. \n Suỵt... đừng nhìn, đừng nghe."
  },
  Stage_7906_Name = {
    Text = "Thịt máu chiểu · khe hở luân chuyển IV"
  },
  Stage_7907_Desc = {
    Text = "\"cửa\"đã được mở, ảo mộng sắp tỉnh giấc. \n Suỵt... đừng nhìn, đừng nghe."
  },
  Stage_7907_Name = {
    Text = "Thịt máu chiểu · khe hở luân chuyển IV"
  },
  Stage_7908_Desc = {
    Text = "Cắt đứt những sợi dây mỏng trên thân con rối, cô ấy sẽ không bao giờ nhảy múa nữa."
  },
  Stage_7908_Name = {
    Text = "Đêm vắng bóng chim"
  },
  Stage_7909_Desc = {
    Text = "Ramona đã trở lại đội. Misaque tiếp tục cuộc hành trình."
  },
  Stage_7909_Name = {
    Text = "Hôm qua trở lại"
  },
  Stage_7910_Desc = {
    Text = "Điều bạn muốn biết, đều ở ngay trước mắt bạn, nhưng bạn chưa bao giờ phát hiện ra."
  },
  Stage_7910_Name = {
    Text = "Ẩn dưới vành mũ"
  },
  Stage_7911_Desc = {
    Text = "Chúc bạn có chuyến đi vui vẻ."
  },
  Stage_7911_Name = {
    Text = "Chúc bạn một chuyến đi vui vẻ"
  },
  Stage_7912_Desc = {
    Text = "Chân người không thể sánh bằng sự nhanh nhẹn của động vật hoang dã bốn chân, nhưng trí óc có thể. Chỉ là, sau khi bắt được \"chó địa ngục\", điều gì đang chờ đợi các ngươi?"
  },
  Stage_7912_Name = {
    Text = "Lá bài bí mật"
  },
  Stage_7913_Desc = {
    Text = "Sự giao dịch với Bà Daphne luôn được cấu thành từ các thỏa thuận. Bà Daphne xuất hiện và đề xuất một thỏa thuận với các bạn. Liệu kẻ tấn công bí ẩn có chấp nhận thỏa thuận này không?"
  },
  Stage_7913_Name = {
    Text = "Giao dịch công bằng"
  },
  Stage_7914_Desc = {
    Text = "Trong tàu điện ngầm, các bạn đã bị một sát thủ bí ẩn tấn công……"
  },
  Stage_7914_Name = {
    Text = "Cuộc đời không có bạn bè"
  },
  Stage_7915_Desc = {
    Text = "Truy tìm những lời đồn đại về chó địa ngục \"Cerberus\", các điều tra viên của Misaque đã đến thị trấn Rai ở vùng ngoại ô Lentiennam, khám phá bí ẩn đằng sau các vụ mất tích…"
  },
  Stage_7915_Name = {
    Text = "Cân nhắc kỹ lưỡng trước khi hành động"
  },
  Stage_7916_Desc = {
    Text = "Giọng điệu điên cuồng, mùi tanh nồng đậm, đây chính là nghi thức chào đón từ Lai."
  },
  Stage_7916_Name = {
    Text = "Chào mừng bạn đến với Lai"
  },
  Stage_7917_Desc = {
    Text = "Một tin tốt, một tin xấu. Dấu vết đã mất sẽ không xuất hiện lại, nhưng một vụ án mới đang dần hình thành trong bóng tối. Hãy tin tưởng, điều tra viên sẽ không ra về tay trắng."
  },
  Stage_7917_Name = {
    Text = "Tin tốt, tin xấu"
  },
  Stage_7918_Desc = {
    Text = "Đây là nơi ngủ say của một thành phố cổ xưa. \nNó thích ngủ như chủ nhân của nó."
  },
  Stage_7918_Name = {Text = "Bonape IV"},
  Stage_7919_Desc = {
    Text = "Elworth nằm ở cực điểm của cà đa sác, quanh năm bị phủ bởi tuyết băng không tan, \ndưới lớp băng dày và cứng cáp, ẩn chứa những nhịp đập của sức sống."
  },
  Stage_7919_Name = {
    Text = "Dãy núi Rối loạn III"
  },
  Stage_7920_Desc = {
    Text = "\nĐã từng có một trường đại học tồn tại, nỗ lực đem đến tia hi vọng mong manh cùng dũng khí cho loài người \nVề phần kết cục của nó, hiện tại chúng ta đang được chứng kiến - bị chôn vùi trong vụn vỡ và hoang tàn."
  },
  Stage_7920_Name = {
    Text = "Thâm Nhập Mộng Ảo VII"
  },
  Stage_7921_Desc = {
    Text = "Chúng vặn vẹo, hòa quyện trong bóng tối, rồi được cẩn thận bảo quản trong tượng. \nĐây là một cuộc hội ngộ đã được dự mưu từ lâu."
  },
  Stage_7921_Name = {
    Text = "Thịt máu chiểu·khe hởI"
  },
  Stage_7922_Desc = {
    Text = "Dâng lên thực tại tạo nên từ thịt và máu, chúng là hố sâu không bao giờ no đủ."
  },
  Stage_7922_Name = {
    Text = "Chất cơ bản tàn ảnh IV"
  },
  Stage_7923_Desc = {
    Text = "Bảo tàng sáp Rogers nằm ở cuối đường Southwark, gần nhánh sông Thames. \nNó không hề nổi bật, nhưng thu hút nhiều người đam mê nghệ thuật đương đại đến tham quan."
  },
  Stage_7923_Name = {
    Text = "Phòng trưng bày nến cuồng nộ IV"
  },
  Stage_7924_Desc = {
    Text = "\"Nó là duy nhất. Nó là tất cả. Nó là hi vọng để mở ra cánh cổng Chân Lý.\"\nVô số chìa khóa tụ thành một vòng tròn. Chúng từ bầu trời rơi xuống, đem đến hi vọng nặng trĩu cho nhân loại.\nCũng như, những nấm mồ nặng tựa Thái Sơn."
  },
  Stage_7924_Name = {
    Text = "Thâm Nhập Mộng Ảo II"
  },
  Stage_7925_Desc = {
    Text = "\"Nó là duy nhất. Nó là tất cả. Nó là hi vọng để mở ra cánh cổng Chân Lý.\"\nVô số chìa khóa tụ thành một vòng tròn. Chúng từ bầu trời rơi xuống, đem đến hi vọng nặng trĩu cho nhân loại.\nCũng như, những nấm mồ nặng tựa Thái Sơn."
  },
  Stage_7925_Name = {
    Text = "Thâm Nhập Mộng Ảo III"
  },
  Stage_7926_Desc = {
    Text = "\"Nó là duy nhất. Nó là tất cả. Nó là hi vọng để mở ra cánh cổng Chân Lý.\"\nVô số chìa khóa tụ thành một vòng tròn. Chúng từ bầu trời rơi xuống, đem đến hi vọng nặng trĩu cho nhân loại.\nCũng như, những nấm mồ nặng tựa Thái Sơn."
  },
