  Stage_7930_Name = {
    Text = "Thâm Nhập Mộng Ảo V"
  },
  Stage_7931_Desc = {
    Text = "Quốc độ của Ngài là xác thân của vũ trụ, ham muốn của Ngài không giới hạn."
  },
  Stage_7931_Name = {
    Text = "Nơi của Giun II"
  },
  Stage_7932_Desc = {
    Text = "Đây là nơi ngủ say của một thành phố cổ xưa. \nNó thích ngủ như chủ nhân của nó."
  },
  Stage_7932_Name = {
    Text = "Phế tích Ponape II"
  },
  Stage_7933_Desc = {
    Text = "Thật, sự thật tàn nhẫn này."
  },
  Stage_7933_Name = {
    Text = "Dưới tấm màn che"
  },
  Stage_7934_Desc = {
    Text = "Hư vô là cội nguồn của chúng ta, cũng là chốn quay về của chúng ta."
  },
  Stage_7934_Name = {
    Text = "Lời thì thầm bất diệt"
  },
  Stage_7935_Desc = {
    Text = "Những pho tượng có nguồn gốc không rõ ràng lang thang, run rẩy trong bóng tối. \nChúng bước theo nhịp điệu cổ xưa, nhảy múa theo tiếng sáo từ xa vọng lại."
  },
  Stage_7935_Name = {
    Text = "Di sản biển sâu · Khe hở VIII"
  },
  Stage_7936_Desc = {
    Text = "Thị trấn Rai nằm ở phía đông bắc của Lentiennam, ẩn sâu trong dãy núi liên tục. \n Người dân im lặng, ánh mắt theo dõi khắp nơi… Hãy cẩn thận, mọi thứ ở đây đều không bình thường."
  },
  Stage_7936_Name = {
    Text = "Thị Trấn Hỗn Loạn II"
  },
  Stage_7937_Desc = {
    Text = "\"Mỗi chìa khóa đều có một con số độc nhất, và cũng chỉ thuộc về một điều tra viên duy nhất.\" \n\"Điều đó cũng đồng nghĩa rằng, thời khắc chìa khóa rơi xuống cũng đánh dấu cái chết của điều tra viên sở hữu nó.\" \n\"Điều này tuyệt vời làm sao, vì ngay cả cái chết cũng là độc nhất vô nhị.\""
  },
  Stage_7937_Name = {
    Text = "Thâm Nhập Mộng Ảo V"
  },
  Stage_7938_Desc = {
    Text = "\"Mỗi chìa khóa đều có một con số độc nhất, và cũng chỉ thuộc về một điều tra viên duy nhất.\" \n\"Điều đó cũng đồng nghĩa rằng, thời khắc chìa khóa rơi xuống cũng đánh dấu cái chết của điều tra viên sở hữu nó.\" \n\"Điều này tuyệt vời làm sao, vì ngay cả cái chết cũng là độc nhất vô nhị.\""
  },
