  },
  Stage_7940_Name = {
    Text = "Thâm Nhập Mộng Ảo VI"
  },
  Stage_7941_Desc = {
    Text = "\"cửa\"đã được mở, ảo mộng sắp tỉnh giấc. \n Suỵt... đừng nhìn, đừng nghe."
  },
  Stage_7941_Name = {
    Text = "Thịt máu · khe hở luân chuyển III"
  },
  Stage_7942_Desc = {
