  },
  Stage_7964_Desc = {
    Text = "Đây là một thế giới được tạo riêng cho cô ấy, là tình yêu vĩ đại nhưng cũng là một nhà tù đáng sợ."
  },
  Stage_7964_Name = {
    Text = "Bệnh viện tinh thần"
  },
  Stage_7965_Desc = {
    Text = "Cuộc giao tranh trên thế gian không chỉ diễn ra trên chiến trường nơi lưỡi kiếm va chạm, mà đôi khi còn tồn tại trong miệng của những kẻ điên rồ."
  },
  Stage_7965_Name = {
    Text = "Miệng kẻ điên"
  },
  Stage_7966_Desc = {
    Text = "Ngọn lửa cháy trong im lặng, hứa với người lữ khách những lời hứa giả dối."
  },
  Stage_7966_Name = {
    Text = "lửa dụ dỗ"
  },
  Stage_7967_Desc = {
    Text = "Dấu vết bị cuốn vào sương mù, vô số bước chân lang thang trên đó, mỗi điểm đặt chân đều là sự chất vấn đối với số phận."
  },
  Stage_7967_Name = {
    Text = "Lối đi mù mịt"
  },
  Stage_7968_Desc = {
    Text = "Nó không ngừng truy đuổi những kẻ vi phạm quy tắc. \nVề việc gì là \"quy tắc\", gì là \"vi phạm\"? \nChó săn không bao giờ suy nghĩ — điều đó chỉ cản trở tốc độ tấn công của nó."
  },
  Stage_7968_Name = {
    Text = "Bóng Ma Ngoài Giới I"
  },
  Stage_7969_Desc = {
    Text = "Cô ấy dùng thân mình để chứa đựng thánh cốt, dùng giáo lý để hướng dẫn chúng tín, dùng răng độc để truyền bá tín ngưỡng."
  },
  Stage_7969_Name = {
    Text = "Bàn tay thành tâm I"
  },
  Stage_7970_Desc = {
    Text = "Giông bão vẫn đang tích tụ, tất cả vẫn chưa đi đến hồi kết."
  },
  Stage_7970_Name = {
    Text = "Khởi động lại thực tế"
  },
  Stage_7971_Desc = {
    Text = "Đó tuyệt đối không phải là sức sống được mong đợi, chỉ là con ký sinh trùng ô uế mà thôi."
  },
  Stage_7971_Name = {
    Text = "Ký sinh trùng"
  },
  Stage_7972_Desc = {
    Text = "Đi về đất liền, đi về tia sáng cuối đường hầm."
  },
  Stage_7972_Name = {
    Text = "Khởi đầu bi thảm"
  },
  Stage_7973_Desc = {
    Text = "Đêm tối bị dòng chảy đen tối xâm chiếm, tinh tú im bặt. Tháng nguy hiểm ẩn chứa sự thay đổi và giông tố, lặng lẽ soi rọi tương lai vô định."
  },
  Stage_7973_Name = {
    Text = "Mặt Trăng Nguy Hiểm"
  },
  Stage_7974_Desc = {
    Text = "Trong bóng tối vô tận của màn đêm, đuổi theo ánh sáng mê hoặc, giống như một con thiêu thân lao vào ánh lửa, bất chấp tất cả để bay về phía ánh hào quang số phận."
  },
  Stage_7974_Name = {
    Text = "Bướm đuổi lửa"
  },
  Stage_7975_Desc = {
    Text = "Tình bạn chập chờn trong những năm tháng đã qua, nay đơm hoa kết trái thành hy vọng mới."
  },
  Stage_7975_Name = {
    Text = "Bạn cũ bạn mới"
  },
  Stage_7976_Desc = {
    Text = "R run rúng trong cơn gió số phận, đấu tranh, nhưng nó sẽ không thực sự tan biến."
  },
  Stage_7976_Name = {
    Text = "Sắp đổ"
  },
  Stage_7977_Desc = {
    Text = "Đón gió và cát sa mạc, chiến binh không do dự lao về phía mặt trời."
  },
  Stage_7977_Name = {
    Text = "Viễn Chinh Mặt Trời"
  },
  Stage_7978_Desc = {
    Text = "Di chuyển, chảy tràn... những bong bóng chất nguyên sinh đang lọt qua khe hở của xiềng xích. \nĐây là cái giá mà cô phải trả cho \"tự do\"."
  },
  Stage_7978_Name = {
    Text = "Chuỗi tối tăm V"
  },
  Stage_7979_Desc = {
    Text = "Một đống chất thô lỗ, chưa được tiêu hóa. Người ta gọi nó là chất thải, hay là hỗn loạn. \nThế giới được sinh ra từ chất thải."
  },
  Stage_7979_Name = {
    Text = "Nhóm Hỗn Loạn III"
  },
  Stage_7980_Desc = {
    Text = "Những pho tượng có nguồn gốc không rõ ràng lang thang, run rẩy trong bóng tối. \nChúng bước theo nhịp điệu cổ xưa, nhảy múa theo tiếng sáo từ xa vọng lại."
  },
  Stage_7980_Name = {
    Text = "Chuyến đi siêu việt·khe hở VIII"
  },
  Stage_7981_Desc = {
    Text = "Chúng vặn vẹo, hòa quyện trong bóng tối, rồi được cẩn thận bảo quản trong tượng. \nĐây là một cuộc hội ngộ đã được dự mưu từ lâu."
  },
  Stage_7981_Name = {
    Text = "Đầm lầy thịt máu · khe hở V"
  },
  Stage_7982_Desc = {
    Text = "Rồi cô ấy biến mất, trở lại trong bóng tối. \nNgười dân ngước lên cao, chăm chú nhìn theo bầu trời nơi cô ấy vừa lướt qua."
  },
  Stage_7982_Name = {
    Text = "Gỗ tuyết tùng"
  },
  Stage_7983_Desc = {
    Text = "Một con chuột nhỏ, một con chuột nhỏ. \n chạy đi, chạy đi, cô ấy dùng dao cắt thịt để cắt đứt đuôi của nó."
  },
  Stage_7983_Name = {
    Text = "Brun tấn công"
  },
  Stage_7984_Desc = {
    Text = "Bạn chìm vào sự yên tĩnh của đêm, \n không còn bất kỳ nghi ngờ hay tranh cãi nào, \n như được ôm trọn trong vòng tay vĩnh cửu, \n chúng ta nằm trong sự bình yên, an lành."
  },
  Stage_7984_Name = {Text = "Phòng"},
  Stage_7985_Desc = {
    Text = "Lentiennam nổi tiếng với nền văn minh công nghiệp rực rỡ và lớp sương mù màu chì xám bao phủ thành phố. \nSương mù hiện diện khắp nơi, đối với người đi đường, nó giống như một sự bất tiện ngẫu nhiên và không đáng kể."
  },
  Stage_7985_Name = {
    Text = "Thành phố Sương Quái III"
  },
  Stage_7986_Desc = {
    Text = "Trên bàn thờ của nhan sắc nàng, tôi nguyện dâng hiến nước mắt, tiếng thở than và trái tim rực cháy của tôi."
  },
  Stage_7986_Name = {
    Text = "Ga-la-tê-a"
  },
  Stage_7987_Desc = {
    Text = "Bộp bộp, nứt ra rồi. \nbộp bộp, gãy rồi."
  },
  Stage_7987_Name = {
    Text = "Bảo tàng Búp bê"
  },
  Stage_7988_Desc = {
    Text = "Quy tắc, không phải là để phá vỡ sao?"
  },
  Stage_7988_Name = {
    Text = "Ba quy tắc"
  },
  Stage_7989_Desc = {
    Text = "Thị trấn ven biển —— Scarborough nằm ở North Yorkshire. Nơi đây có những vách đá cao chót vót và vịnh vàng, là một điểm nghỉ mát thanh lịch và quyến rũ."
  },
  Stage_7989_Name = {
    Text = "Mùa hè Scarborough"
  },
  Stage_7990_Desc = {
    Text = "Ô, cánh tay, những cánh tay phiền toái! Chúng luôn kéo tóc tôi không buông."
  },
  Stage_7990_Name = {
    Text = "Hai mươi tư"
  },
  Stage_7991_Desc = {
    Text = "Cô ấy đã học được nhiều kiến thức tâm lý học thực tế từ nước mắt và chất thải của con người —— nhiều hơn tất cả những gì cô ấy học được từ sách vở."
  },
  Stage_7991_Name = {
    Text = "Sổ tay điều trị"
  },
  Stage_7992_Desc = {
    Text = "Để bảo vệ sức khỏe của bạn, hãy tránh xa nicotine."
  },
  Stage_7992_Name = {
    Text = "Khói và tử la lan"
  },
  Stage_7993_Desc = {
    Text = "Thị trấn ven biển —— Scarborough nằm ở North Yorkshire. Nơi đây có những vách đá cao chót vót và vịnh vàng, là một điểm nghỉ mát thanh lịch và quyến rũ."
  },
