  },
  Stage_8008_Name = {
    Text = "Thâm Nhập Mộng Ảo VI"
  },
  Stage_8009_Desc = {
    Text = "Đây là nơi ngủ say của một thành phố cổ xưa. \nNó thích ngủ như chủ nhân của nó."
  },
  Stage_8009_Name = {
    Text = "Phế tích Pohnpei I"
  },
  Stage_8010_Desc = {
    Text = "Chúng ta sẽ còn gặp nhau, ở những chiều thời gian và không gian khác"
  },
  Stage_8010_Name = {
    Text = "Hẹn ngày gặp lại"
  },
  Stage_8011_Desc = {
    Text = "Cảnh quan uốn cong ẩn sâu trong vũ trụ. \nNó có thể đưa bạn từ bóng tối đến một bóng tối khác."
  },
  Stage_8011_Name = {
    Text = "Họng Schwarzschild II"
  },
  Stage_8012_Desc = {
