  },
  Stage_8012_Name = {
    Text = "Họng Schwarzschild V"
  },
  Stage_8013_Desc = {
    Text = "Không ai có thể hái xuống vương miện mà Thần Vương ban tặng, chẳng ai."
  },
  Stage_8013_Name = {
    Text = "\"Sự vinh quang\" của Lemuria"
  },
  Stage_8014_Desc = {
    Text = "Tình bạn chập chờn trong những năm tháng đã qua, nay đơm hoa kết trái thành hy vọng mới."
  },
  Stage_8014_Name = {
    Text = "Bạn cũ bạn mới"
  },
  Stage_8015_Desc = {
    Text = "Đêm tối bị dòng chảy đen tối xâm chiếm, tinh tú im bặt. Tháng nguy hiểm ẩn chứa sự thay đổi và giông tố, lặng lẽ soi rọi tương lai vô định."
  },
  Stage_8015_Name = {
    Text = "Mặt Trăng Nguy Hiểm"
  },
  Stage_8016_Desc = {
    Text = "Đúng, tham lam là tội nguyên của anh ta, anh ta sẽ phải sám hối vì điều đó."
  },
  Stage_8016_Name = {
    Text = "Sự diệt vong"
  },
  Stage_8017_Desc = {
    Text = "Người bảo vệ im lặng đã phát ra tiếng mới."
  },
  Stage_8017_Name = {
    Text = "Bảo vệ quá tải"
  },
  Stage_8018_Desc = {
    Text = "Trong bóng tối vô tận của màn đêm, đuổi theo ánh sáng mê hoặc, giống như một con thiêu thân lao vào ánh lửa, bất chấp tất cả để bay về phía ánh hào quang số phận."
  },
  Stage_8018_Name = {
    Text = "Bướm đuổi lửa"
  },
  Stage_8019_Desc = {
    Text = "\"cửa\"đã được mở, ảo mộng sắp tỉnh giấc. \n Suỵt... đừng nhìn, đừng nghe."
  },
  Stage_8019_Name = {
    Text = "Vùng Hỗn Loạn · Khe Hở Luân Chuyển III"
  },
  Stage_8020_Desc = {
    Text = "\"cửa\"đã được mở, ảo mộng sắp tỉnh giấc. \n Suỵt... đừng nhìn, đừng nghe."
  },
  Stage_8020_Name = {
