  },
  Stage_8021_Name = {
    Text = "Vùng Hỗn Loạn · Khe Hở Luân Chuyển III"
  },
  Stage_8022_Desc = {
    Text = "Đó tuyệt đối không phải là sức sống được mong đợi, chỉ là con ký sinh trùng ô uế mà thôi."
  },
  Stage_8022_Name = {
    Text = "Ký sinh trùng"
  },
  Stage_8023_Desc = {
    Text = "Giấc ngủ thật hạnh phúc, nó đã đưa thiên thần của tôi trở lại bên tôi."
  },
  Stage_8023_Name = {
    Text = "Ô cửa bí ẩn"
  },
  Stage_80242_Desc = {
    Text = "Cuối câu chuyện, thế giới vẫn đang cháy, tôi đã sẵn sàng để nói lời tạm biệt.\nNhưng cuối cùng chúng ta sẽ đoàn tụ."
  },
  Stage_80242_Name = {
    Text = "Thế giới đang cháy, tạm biệt"
  },
  Stage_80243_Desc = {
    Text = "Con người là một loại động vật xã hội, họ bị ảnh hưởng bởi xã hội và lại ảnh hưởng đến xã hội.\nVậy, hãy cho tôi biết, cuộc sống và môi trường đã hình thành nên bạn là người như thế nào?"
  },
  Stage_80243_Name = {
    Text = "Thí nghiệm tái cấu trúc nhận thức"
  },
  Stage_80244_Desc = {
    Text = "Xin lỗi vì tôi không có món quà nào dành tặng bạn.\nCái kén nhỏ này là lời chúc phúc sâu sắc nhất của tôi dành cho bạn: Khi rơi vào tuyệt cảnh, nhất định hãy xé bỏ kén để tái sinh."
  },
  Stage_80244_Name = {
    Text = "Kén của tình bạn"
  },
  Stage_80245_Desc = {
    Text = "Ngọn lửa, mang đến ánh sáng, cũng mang đến đau đớn và sát thương.\n Khi cả thế giới đang cháy, tôi sẵn lòng biến cuộc sống thành một giọt nước mắt, tập hợp thành đại dương đau khổ."
  },
  Stage_80245_Name = {
    Text = "Chào bạn, thế giới đang cháy"
  },
  Stage_80246_Desc = {
    Text = "Người dũng cảm là đơn độc, nhân loại không thể thực sự bước vào họ, rồng cũng không thể thực sự hiểu họ.\nLiệu là tiêu diệt rồng, hay hóa thân thành rồng, đó là một câu hỏi."
  },
  Stage_80246_Name = {
    Text = "Chiến binh cô đơn"
  },
  Stage_80247_Desc = {
    Text = "Tôi tràn đầy ước mơ về thế giới, hy vọng hoa luôn nở rộ, hy vọng nụ cười trường tồn.\nNhưng cuộc sống chỉ cho tôi một giấc mơ."
  },
  Stage_80247_Name = {
    Text = "Tôi có nhiều ước mơ"
  },
  Stage_80248_Desc = {
    Text = "Tập thể là hổ phách đang chảy, mỗi linh hồn đều phản chiếu ánh sáng của người khác, lại nhìn thấy phản chiếu của chính mình trong cái lồng trong suốt."
  },
  Stage_80248_Name = {
    Text = "Động vật xã hội"
  },
  Stage_80249_Desc = {
    Text = "Tôi là bạn của tôi, cũng là kẻ thù của tôi.\nCuộc hợp tác và chiến đấu này sẽ không dừng lại, cho đến khi chỉ còn lại một người trên sân đấu."
  },
  Stage_80249_Name = {
    Text = "Nhân đôi"
  },
  Stage_8024_Desc = {
    Text = "Dù vỏ bọc kim loại có nặng đến đâu, linh hồn chỉ nặng 21 gam."
  },
  Stage_8024_Name = {Text = "21 g"},
  Stage_80250_Desc = {
    Text = "Những con bướm nhỏ, bay qua giấc mơ, bay về thực tại.\nCó lẽ nó quá ngu ngốc, nhưng lựa chọn của bướm lại khác với con người."
  },
  Stage_80250_Name = {
    Text = "Bươm bướm bay"
  },
  Stage_80251_Desc = {
    Text = "Để tôi xem, xem thành phần và cấu trúc nào đã tạo nên \"bạn\" và \"tôi\"."
  },
  Stage_80251_Name = {
    Text = "Đôi mắt"
  },
  Stage_80252_Desc = {
    Text = "À, bạn của tôi, chúng ta đều sẽ mơ.  \nChỉ có một số người biến giấc mơ thành hiện thực, trong khi thực tế của một số người lại giống như một giấc mơ điên rồ."
  },
  Stage_80252_Name = {
    Text = "Giấc mơ không kiểm soát"
  },
  Stage_80253_Desc = {
    Text = "Tôi nhảy múa trong ký ức đã mất, quên đi người yêu mình và người tôi yêu, chỉ nhảy cùng chính mình mãi mãi, nhảy đến tận cùng thời gian."
  },
  Stage_80253_Name = {
    Text = "Ký ức đã mất"
  },
  Stage_80254_Desc = {
    Text = "Chạy, chạy, cún con nhanh lên chạy.\nDùng sự hoảng loạn và đau khổ của bạn, biểu diễn cho chúng tôi một vở hài kịch."
  },
  Stage_80254_Name = {
    Text = "Truy đuổi"
  },
  Stage_80255_Desc = {
    Text = "Nhìn bạn, tôi đang nhìn bạn.  \nMỗi giây mỗi phút, cứ thế nhìn bạn."
  },
  Stage_80255_Name = {
    Text = "Ánh mắt của người khác"
  },
  Stage_80256_Desc = {
    Text = "Ký ức không đáng tin cậy, vì khi tôi lục tìm trong đó, nó bắt đầu bị hủy hoại và phai màu. Thực sự có cách nào để giúp bóng hình bạn trở nên vĩnh cửu?  \nNếu ký ức không vững chắc, thì hãy khắc nó vào cuộc sống."
  },
  Stage_80256_Name = {
    Text = "Hình bóng tương tự"
  },
  Stage_80257_Desc = {
    Text = "Ba viên đạn đầu tiên chỉ là nhạc dạo.\nTrong hai viên đạn cuối cùng, một viên bắn mang đi mạng sống của hắn, một viên bắn mang đi linh hồn của hắn."
  },
  Stage_80257_Name = {
    Text = "Âm thanh súng nổ năm lầ"
  },
  Stage_80258_Desc = {
    Text = "\"Sự tò mò\"đã ném cho bạn một câu hỏi, dù biết rõ câu trả lời đầy gai góc, sẽ khiến bạn cháy rụi, bạn cũng không thể từ chối.\nCuối cùng bạn vẫn là con mèo không thể từ chối \"sự tò mò\"."
  },
  Stage_80258_Name = {
    Text = "Sự tò mò giết chết mèo"
  },
  Stage_80259_Desc = {
    Text = "Thế giới là một viện dưỡng lão lớn, mọi người đều điên cuồng, hoặc đang giấu đi sự điên cuồng của mình.\nVậy, có muốn đến một buổi tư vấn tâm lý không?"
  },
  Stage_80259_Name = {
    Text = "Thư mời tư vấ"
  },
  Stage_8025_Desc = {
    Text = "Đây là một thế giới được tạo riêng cho cô ấy, là tình yêu vĩ đại nhưng cũng là một nhà tù đáng sợ."
  },
  Stage_8025_Name = {
    Text = "Bệnh viện tinh thần"
  },
  Stage_80260_Desc = {
    Text = "À, bạn của tôi, chúng ta đều sẽ mơ.  \nChỉ có một số người biến giấc mơ thành hiện thực, trong khi thực tế của một số người lại giống như một giấc mơ điên rồ."
  },
  Stage_80260_Name = {
    Text = "Giấc mơ không kiểm soát"
  },
  Stage_80261_Desc = {
    Text = "Tôi nhảy múa trong ký ức đã mất, quên đi người yêu mình và người tôi yêu, chỉ nhảy cùng chính mình mãi mãi, nhảy đến tận cùng thời gian."
  },
  Stage_80261_Name = {
    Text = "Ký ức đã mất"
  },
  Stage_80262_Desc = {
    Text = "Chạy, chạy, cún con mau chạy.\nHãy dùng sự hoảng loạn và đau khổ của bạn, để biểu diễn một buổi hài kịch cho chúng tôi."
  },
  Stage_80262_Name = {
    Text = "Truy đuổi"
  },
  Stage_80263_Desc = {
