  },
  Stage_80263_Name = {
    Text = "Hình bóng tương tự"
  },
  Stage_80264_Desc = {
    Text = "Ba viên đạn đầu tiên chỉ là nhạc dạo.\nTrong hai viên đạn cuối cùng, một viên bắn mang đi mạng sống của hắn, một viên bắn mang đi linh hồn của hắn."
  },
  Stage_80264_Name = {
    Text = "Âm thanh súng nổ năm lầ"
  },
  Stage_80265_Desc = {
    Text = "Thế giới là một viện dưỡng lão lớn, mọi người đều điên cuồng, hoặc đang giấu đi sự điên cuồng của mình.\nVậy, có muốn đến một buổi tư vấn tâm lý không?"
  },
  Stage_80265_Name = {
    Text = "Thư mời tư vấ"
  },
  Stage_80266_Desc = {
    Text = "Ngọn lửa, mang đến ánh sáng, cũng mang đến đau đớn và sát thương.\n Khi cả thế giới đang cháy, tôi sẵn lòng biến cuộc sống thành một giọt nước mắt, tập hợp thành đại dương đau khổ."
  },
  Stage_80266_Name = {
    Text = "Chào bạn, thế giới đang cháy"
  },
  Stage_80267_Desc = {
    Text = "Người dũng cảm là đơn độc, nhân loại không thể thực sự bước vào họ, rồng cũng không thể thực sự hiểu họ.\nLiệu là tiêu diệt rồng, hay hóa thân thành rồng, đó là một câu hỏi."
  },
  Stage_80267_Name = {
    Text = "Chiến binh cô đơn"
  },
  Stage_80268_Desc = {
    Text = "Con người là một loại động vật xã hội, họ bị ảnh hưởng bởi xã hội và lại ảnh hưởng đến xã hội.\nVậy, hãy cho tôi biết, cuộc sống và môi trường đã hình thành nên bạn là người như thế nào?"
  },
  Stage_80268_Name = {
    Text = "Thí nghiệm tái cấu trúc nhận thức"
  },
  Stage_80269_Desc = {
    Text = "Tôi tràn đầy ước mơ về thế giới, hy vọng hoa luôn nở rộ, hy vọng nụ cười trường tồn.\nNhưng cuộc sống chỉ cho tôi một giấc mơ."
  },
  Stage_80269_Name = {
    Text = "Tôi có nhiều ước mơ"
  },
  Stage_8026_Desc = {
    Text = "Khi các quý tộc mất quyền lực, khi những người giàu có bị phá sản, họ không thể tiến thêm một bước nào, giống như chính bạn hiện tại."
  },
  Stage_8026_Name = {
    Text = "Vượt qua bức tường điên loạn"
  },
  Stage_80270_Desc = {
    Text = "Tôi là bạn của tôi, cũng là kẻ thù của tôi.\nCuộc hợp tác và chiến đấu này sẽ không dừng lại, cho đến khi chỉ còn lại một người trên sân đấu."
  },
  Stage_80270_Name = {
    Text = "Nhân đôi"
  },
  Stage_80271_Desc = {
    Text = "Những con bướm nhỏ, bay qua giấc mơ, bay về thực tại.\nCó lẽ nó quá ngu ngốc, nhưng lựa chọn của bướm lại khác với con người."
  },
  Stage_80271_Name = {
    Text = "Bươm bướm bay"
  },
  Stage_8027_Desc = {
    Text = "Cuộc giao tranh trên thế gian không chỉ diễn ra trên chiến trường nơi lưỡi kiếm va chạm, mà đôi khi còn tồn tại trong miệng của những kẻ điên rồ."
  },
  Stage_8027_Name = {
    Text = "Miệng kẻ điên"
  },
  Stage_8028_Desc = {
    Text = "Cắt đứt những sợi dây mỏng trên thân con rối, cô ấy sẽ không bao giờ nhảy múa nữa."
  },
  Stage_8028_Name = {
    Text = "Đêm vắng bóng chim"
  },
  Stage_8029_Desc = {
    Text = "Đừng quay đầu lại! Lời dặn dò vô cùng quý giá, đừng đi vào vết xe đổ của Orpheus."
  },
  Stage_8029_Name = {
    Text = "Đừng ngoảnh lại"
  },
  Stage_8030_Desc = {
    Text = "Ai có thể diễn giải ý nghĩa của \"mùa xuân\"?\nCái chết và sự lãng quên ẩn náu trong khoảng không tĩnh lặng, hòa vào ảo cảnh mờ ảo của ngày xuân."
  },
  Stage_8030_Name = {
    Text = "Mùa xuân của Botticelli"
  },
  Stage_8031_Desc = {
    Text = "Nhật ký là những phân mảnh của ký ức. \nTrong quá trình điều tra, luôn tìm thấy nhật ký."
  },
  Stage_8031_Name = {
    Text = "Phân mảnh ký ức"
  },
  Stage_8032_Desc = {
    Text = "Chào mừng lần đầu gặp mặt, thưa chủ nhân."
  },
  Stage_8032_Name = {
    Text = "Giác quan thứ sáu"
  },
  Stage_8033_Desc = {
    Text = "Chúng vặn vẹo, hòa quyện trong bóng tối, rồi được cẩn thận bảo quản trong tượng. \nĐây là một cuộc hội ngộ đã được dự mưu từ lâu."
  },
  Stage_8033_Name = {
    Text = "Thịt máu · khe hở VI"
  },
  Stage_8034_Desc = {
    Text = "Trước khi các ngôi sao được sinh ra, chúng đã tồn tại ở đây. \nChúng vừa là hư vô, vừa là tất cả."
  },
  Stage_8034_Name = {
    Text = "Hình ảnh mờ nhạt III"
  },
  Stage_8035_Desc = {
    Text = "4 ngẫu nhiên"
  },
  Stage_8035_Name = {
    Text = "Gương ao trăng IV"
  },
  Stage_8036_Desc = {
    Text = "Ngẫu nhiên 5"
  },
  Stage_8036_Name = {
    Text = "Gương Đầm Trăng V"
  },
  Stage_8037_Desc = {
    Text = "\"Cửa\" sắp mở ra, bạn nhìn thấy một phần sự thật. \nKhông phải màu đen, cũng không phải màu trắng — sự thật là đa sắc màu, cũng như mờ đục."
  },
  Stage_8037_Name = {
    Text = "Vùng Hỗn Loạn · Khe Hở Xoay Chuyển I"
  },
  Stage_8038_Desc = {
    Text = "Ngẫu nhiên một"
  },
  Stage_8038_Name = {
    Text = "Gương ao trăng I"
  },
  Stage_8039_Desc = {
    Text = "\"Cửa\" sắp mở ra, bạn nhìn thấy một phần sự thật. \nKhông phải màu đen, cũng không phải màu trắng — sự thật là đa sắc màu, cũng như mờ đục."
  },
  Stage_8039_Name = {
    Text = "Vùng Hỗn Loạn · Khe Hở Xoay Chuyển I"
  },
  Stage_8040_Desc = {
    Text = "\"Cửa\" sắp mở ra, bạn nhìn thấy một phần sự thật. \nKhông phải màu đen, cũng không phải màu trắng — sự thật là đa sắc màu, cũng như mờ đục."
  },
  Stage_8040_Name = {
    Text = "Vùng Hỗn Loạn · Khe Hở Xoay Chuyển I"
  },
  Stage_8041_Desc = {
    Text = "Ramona đã trở lại đội. Misaque tiếp tục cuộc hành trình."
  },
  Stage_8041_Name = {
    Text = "Hôm qua trở lại"
  },
  Stage_8042_Desc = {
    Text = "Dưới cây cầu đường sắt hoang vu, một con quái vật khổng lồ, mập mạp phát ra những tiếng gầm thấp kỳ quái. Để đến được viện điều dưỡng tâm thần Rai, phải vượt qua nơi đây."
  },
  Stage_8042_Name = {
    Text = "Đến chân cầu, đường sẽ rõ"
  },
  Stage_8043_Desc = {
    Text = "Điều bạn muốn biết, đều ở ngay trước mắt bạn, nhưng bạn chưa bao giờ phát hiện ra."
  },
  Stage_8043_Name = {
    Text = "Ẩn dưới vành mũ"
  },
  Stage_8044_Desc = {
    Text = "Cuộc đời giống như một đường xoắn ốc, những cơn ác mộng từng trốn thoát luôn trở lại vào giữa đêm khuya."
  },
  Stage_8044_Name = {
    Text = "Quay lại điểm xuất phát"
  },
  Stage_8045_Desc = {
    Text = "Trong tiếng thì thầm dịu dàng của Ramona và lơ-tan, Người Giữ Gìn chìm sâu vào giấc mơ như bị giam cầm trong ngục tối."
  },
  Stage_8045_Name = {
    Text = "Đừng sửa những gì chưa bị hư"
  },
  Stage_8046_Desc = {
    Text = "Thần nói, họ sinh ra đã phải trải qua gian khổ, đổ hết máu. \n Giống như mặt trời vốn dĩ phải mọc, mưa vốn dĩ phải rơi. \n Mọi thứ đều là sự sắp xếp tốt nhất."
  },
  Stage_8046_Name = {
    Text = "Vùng Đất Mưa Sầu"
  },
  Stage_8047_Desc = {
    Text = "Bảo tàng sáp Rogers nằm ở cuối đường Southwark, gần nhánh sông Thames. \nNó không hề nổi bật, nhưng thu hút nhiều người đam mê nghệ thuật đương đại đến tham quan."
  },
  Stage_8047_Name = {
    Text = "Bảo tàng Nến Điên Rồ II"
  },
  Stage_8048_Desc = {
    Text = "Nó là sinh vật duy nhất ở đây, mọi thứ nó thấy đều do nó thống trị. \n——Nó là vị vua tối cao."
  },
  Stage_8048_Name = {
    Text = "Vương Quốc Dã Thú"
  },
  Stage_8049_Desc = {
    Text = "Quốc độ của Ngài là xác thân của vũ trụ, ham muốn của Ngài không giới hạn."
  },
  Stage_8049_Name = {
    Text = "Nơi của giun I"
  },
  Stage_8050_Desc = {
    Text = "\"Bàn Tay\" vén lên bức màn của đêm đen, lặng lẽ tiến vào thế giới này."
  },
  Stage_8050_Name = {
    Text = "Thâm Nhập Mộng Ảo V"
  },
  Stage_8051_Desc = {
    Text = "Tượng thần sụp đổ quan sát con dân của nó; \nchứng kiến bọn họ sinh tồn, sinh sản, chiến đấu cùng nhau-- và cuối cùng, đánh mất chính mình trong quên lãng. \nTượng thần sụp đổ hoài niệm con dân của nó..."
  },
  Stage_8051_Name = {
    Text = "Thâm Nhập Mộng Ảo II"
  },
  Stage_8052_Desc = {
    Text = "Tượng thần sụp đổ quan sát con dân của nó; \nchứng kiến bọn họ sinh tồn, sinh sản, chiến đấu cùng nhau-- và cuối cùng, đánh mất chính mình trong quên lãng. \nTượng thần sụp đổ hoài niệm con dân của nó..."
  },
  Stage_8052_Name = {
    Text = "Thâm Nhập Mộng Ảo III"
  },
  Stage_8053_Desc = {
    Text = "Đây là một bộ phim không có kết thúc, cô ấy đã ngủ giữa các cảnh phim nhiều năm. \nCô ấy mơ thấy những bông hồng vào buổi chiều hè, và cả những cơn gió cùng với tro tàn…"
  },
  Stage_8053_Name = {
    Text = "Thi xã Felin"
  },
  Stage_8054_Desc = {
    Text = "Tượng thần sụp đổ quan sát con dân của nó; \nchứng kiến bọn họ sinh tồn, sinh sản, chiến đấu cùng nhau-- và cuối cùng, đánh mất chính mình trong quên lãng. \nTượng thần sụp đổ hoài niệm con dân của nó..."
  },
  Stage_8054_Name = {
    Text = "Thâm Nhập Mộng Ảo VI"
  },
  Stage_8055_Desc = {
    Text = "Tượng thần sụp đổ quan sát con dân của nó; \nchứng kiến bọn họ sinh tồn, sinh sản, chiến đấu cùng nhau-- và cuối cùng, đánh mất chính mình trong quên lãng. \nTượng thần sụp đổ hoài niệm con dân của nó..."
  },
  Stage_8055_Name = {
    Text = "Thâm Nhập Mộng Ảo VII"
  },
  Stage_8056_Desc = {
    Text = "Tượng thần sụp đổ quan sát con dân của nó; \nchứng kiến bọn họ sinh tồn, sinh sản, chiến đấu cùng nhau-- và cuối cùng, đánh mất chính mình trong quên lãng. \nTượng thần sụp đổ hoài niệm con dân của nó..."
  },
  Stage_8056_Name = {
    Text = "Thâm Nhập Mộng Ảo IV"
  },
  Stage_8057_Desc = {
    Text = "Tượng thần sụp đổ quan sát con dân của nó; \nchứng kiến bọn họ sinh tồn, sinh sản, chiến đấu cùng nhau-- và cuối cùng, đánh mất chính mình trong quên lãng. \nTượng thần sụp đổ hoài niệm con dân của nó..."
  },
  Stage_8057_Name = {
    Text = "Thâm Nhập Mộng Ảo V"
  },
  Stage_8058_Desc = {
    Text = "Khi màn mưa rơi xuống, máu tươi trào ra, chúng ta chào đón khoảnh khắc tái ngộ. \nĐã lâu không gặp, Người Giữ Gìn."
  },
  Stage_8058_Name = {
    Text = "Cuộc gặp bất ngờ"
  },
  Stage_8060_Desc = {
    Text = "Khi bóng tối lẻn vào đêm tối, giọt nước hòa vào mưa. \nThời khắc săn giết sắp đến…"
  },
  Stage_8060_Name = {
    Text = "Bão sắp đến"
  },
  Stage_8062_Desc = {
    Text = "Chúng tôi là tập hợp của những sinh vật nhỏ bé, xương và nước mắt. \nĐêm nay chúng tôi tụ họp ở đây, chỉ để chiêm ngưỡng dòng sông rực rỡ với vô số cầu vồng."
  },
  Stage_8062_Name = {
    Text = "Hội Săn Đầu"
  },
  Stage_8063_Desc = {
    Text = "\"Nó là duy nhất. Nó là tất cả. Nó là hi vọng để mở ra cánh cổng Chân Lý.\"\nVô số chìa khóa tụ thành một vòng tròn. Chúng từ bầu trời rơi xuống, đem đến hi vọng nặng trĩu cho nhân loại.\nCũng như, những nấm mồ nặng tựa Thái Sơn."
  },
