  Stage_8069_Name = {
    Text = "Thâm Nhập Mộng Ảo VI"
  },
  Stage_8070_Desc = {
    Text = "Chúng vặn vẹo, hòa quyện trong bóng tối, rồi được cẩn thận bảo quản trong tượng. \nĐây là một cuộc hội ngộ đã được dự mưu từ lâu."
  },
  Stage_8070_Name = {
    Text = "Di sản biển sâu · khe hở VI"
  },
  Stage_8071_Desc = {
    Text = "Chúng vốn là tập hợp vô thức của nỗi buồn, sự méo mó và bối rối, \n nhưng lại được ngụy trang thành những đứa trẻ, người lớn và thú cưng hạnh phúc. \n Vì chưa bao giờ biết đến hạnh phúc, chúng trở thành những diễn viên tồi tệ nhất."
  },
  Stage_8071_Name = {
    Text = "Bí mật bình tượng nến III"
  },
  Stage_8072_Desc = {
    Text = "Nó không ngừng truy đuổi những kẻ vi phạm quy tắc. \nVề việc gì là \"quy tắc\", gì là \"vi phạm\"? \nChó săn không bao giờ suy nghĩ — điều đó chỉ cản trở tốc độ tấn công của nó."
  },
  Stage_8072_Name = {
    Text = "Bóng Ma Ngoài Giới I"
  },
  Stage_8073_Desc = {
    Text = "Chúng giống như những phù thủy khó đoán, lang thang giữa các kẽ hở thời gian và không gian. \n Không có thù hận, không có sợ hãi, cũng không có lòng thương xót."
  },
  Stage_8073_Name = {
    Text = "Bản sao chiều không gian V"
  },
  Stage_8074_Desc = {
    Text = "Di chuyển, chảy tràn... những bong bóng chất nguyên sinh đang lọt qua khe hở của xiềng xích. \nĐây là cái giá mà cô phải trả cho \"tự do\"."
  },
  Stage_8074_Name = {
    Text = "Dây xích hắc ám I"
  },
