    Text = "Bảo tàng sáp Rogers nằm ở cuối đường Southwark, gần nhánh sông Thames. \nNó không hề nổi bật, nhưng thu hút nhiều người đam mê nghệ thuật đương đại đến tham quan."
  },
  Stage_8104_Name = {
    Text = "Bảo tàng Sáp Cuồng Loạn III"
  },
  Stage_8105_Desc = {
    Text = "Làm thế nào có hoàng hôn vĩnh viễn không lặn?"
  },
  Stage_8105_Name = {
    Text = "Hoàng hôn"
  },
  Stage_8106_Desc = {
    Text = "Đầu nhọn sắc bén phá vỡ đường tròn tuyệt đối, không phải vật của \"Cerberus\" sinh ra từ khe nứt."
  },
  Stage_8106_Name = {
    Text = "Vết nứt trên vỏ"
  },
  Stage_8107_Desc = {
    Text = "Là điều gì đã che mờ đôi mắt của cô ấy? \n Là tình yêu, lòng thương xót, công lý và sự biết ơn quá mức sao?"
  },
  Stage_8107_Name = {
    Text = "Vượt thoát"
  },
  Stage_8108_Desc = {
    Text = "Chúng giống như những phù thủy khó đoán, lang thang giữa các kẽ hở thời gian và không gian. \n Không có thù hận, không có sợ hãi, cũng không có lòng thương xót."
  },
  Stage_8108_Name = {
    Text = "Ảnh tàn chiều không gian IV"
  },
  Stage_8109_Desc = {
    Text = "\"Cửa\" sắp mở ra, bạn nhìn thấy một phần sự thật. \nKhông phải màu đen, cũng không phải màu trắng — sự thật là đa sắc màu, cũng như mờ đục."
  },
  Stage_8109_Name = {
    Text = "Di sản biển sâu · Khe hở luân chuyển I"
  },
  Stage_8110_Desc = {
    Text = "Truy tìm những lời đồn đại về chó địa ngục \"Cerberus\", các điều tra viên của Misaque đã đến thị trấn Rai ở vùng ngoại ô Lentiennam, khám phá bí ẩn đằng sau các vụ mất tích…"
  },
  Stage_8110_Name = {
    Text = "Cân nhắc kỹ lưỡng trước khi hành động"
  },
  Stage_8111_Desc = {
    Text = "Một tin tốt, một tin xấu. Dấu vết đã mất sẽ không xuất hiện lại, nhưng một vụ án mới đang dần hình thành trong bóng tối. Hãy tin tưởng, điều tra viên sẽ không ra về tay trắng."
  },
  Stage_8111_Name = {
    Text = "Tin tốt, tin xấu"
  },
  Stage_8112_Desc = {
    Text = "Bà Chủ Hoa Thủy Tiên bí ẩn."
  },
  Stage_8112_Name = {
    Text = "Xin chào, Bà Daphne"
  },
  Stage_8113_Desc = {
    Text = "Giọng điệu điên cuồng, mùi tanh nồng đậm, đây chính là nghi thức chào đón từ Lai."
  },
  Stage_8113_Name = {
    Text = "Chào mừng bạn đến với Lai"
  },
  Stage_8114_Desc = {
    Text = "Chân người không thể sánh bằng sự nhanh nhẹn của động vật hoang dã bốn chân, nhưng trí óc có thể. Chỉ là, sau khi bắt được \"chó địa ngục\", điều gì đang chờ đợi các ngươi?"
  },
  Stage_8114_Name = {
    Text = "Lá bài bí mật"
  },
  Stage_8115_Desc = {
    Text = "Đào Đen Đá đã mời \"câu trả lời\" của các bạn, quân cờ mới bước vào bàn cờ, mang theo giấc mơ về bão tuyết."
  },
  Stage_8115_Name = {
    Text = "Lo lắng không yên"
  },
  Stage_8116_Desc = {
    Text = "Chúc bạn có chuyến đi vui vẻ."
  },
  Stage_8116_Name = {
    Text = "Chúc bạn một chuyến đi vui vẻ"
  },
  Stage_8117_Desc = {
    Text = "Trong tàu điện ngầm, các bạn đã bị một sát thủ bí ẩn tấn công……"
  },
  Stage_8117_Name = {
    Text = "Cuộc đời không có bạn bè"
  },
  Stage_81181_Desc = {
    Text = "Mọi người đã tạo ra vô số đồng thau và sắt tục, để đo lường quỹ đạo của các vì sao.\nTrên đại dương không có gì cả, các vì sao mãi mãi là ngọn đèn sáng nhất."
  },
  Stage_81181_Name = {
    Text = "Quỹ đạo của các vì sao·Phần năm"
  },
