  Stage_81188_Desc = {
    Text = "Trên đại dương vô biên mà âm thanh khó truyền tải, cờ hiệu thay thế cho lời nói, kết nối một chiếc thuyền với những chiếc thuyền khác"
  },
  Stage_81188_Name = {
