  Stage_81189_Name = {
    Text = "Cờ tín hiệu·Sáu"
  },
  Stage_8118_Desc = {
    Text = "Sự giao dịch với Bà Daphne luôn được cấu thành từ các thỏa thuận. Bà Daphne xuất hiện và đề xuất một thỏa thuận với các bạn. Liệu kẻ tấn công bí ẩn có chấp nhận thỏa thuận này không?"
