  Stage_81195_Desc = {
    Text = "Nhờ sự kết hợp chính xác của thiết bị quang học, mọi người có thể khám phá góc nhìn của các vì sao."
  },
  Stage_81195_Name = {
    Text = "Thước lỗ cổ điển·Phần bốn"
  },
  Stage_81196_Desc = {
    Text = "Biển cả bí ẩn và nguy hiểm, nhưng cũng đầy cơ hội.\nCuốn cẩm nang này ghi lại những quan sát và kinh nghiệm của người đi trước trong việc hàng hải, hy vọng có thể hướng dẫn bạn trở thành một người dẫn đường đủ tiêu chuẩn."
  },
  Stage_81196_Name = {
