  },
  Stage_81203_Desc = {
    Text = "Hãy reo hò, hãy điên cuồng, hãy làm vui lòng người vĩ đại @3 bằng nỗi đau và cái chết của các bạn."
  },
  Stage_81203_Name = {
    Text = "hiến tế"
  },
  Stage_81204_Desc = {
    Text = "Cảm ơn vận mệnh, sinh ra là một người dẫn đường, bạn sẽ sớm được ôm vào lòng bởi nước mặn, biến thành ánh lửa dẫn đường."
  },
  Stage_81204_Name = {
    Text = "Bài ca của người dẫn đường"
  },
  Stage_81205_Desc = {
    Text = "Trước khi bóng tối bao trùm, không phải là ánh sáng, mà là một bóng tối không quá tối.\nBởi vì luôn có người sẽ giơ cao ngọn đuốc."
  },
  Stage_81205_Name = {
    Text = "Trước khi bóng tối bao trùm"
  },
  Stage_81206_Desc = {
    Text = "Bản đồ sao là đôi mắt của người đi biển, nó có thể giúp chúng tôi tìm thấy hướng đi trong bầu trời đêm."
  },
  Stage_81206_Name = {
    Text = "Bản đồ sao hoang tàn·Phần ba"
  },
  Stage_81207_Desc = {
    Text = "Chỉ cần thuyền còn, tôi sẽ thực hiện nhiệm vụ hoa tiêu của mình.\nQuá khứ là vậy, hiện tại cũng vậy."
  },
  Stage_81207_Name = {
    Text = "Đường đi trong tương lai"
  },
  Stage_81208_Desc = {
    Text = "Bản đồ sao là đôi mắt của người đi biển, nó có thể giúp chúng tôi tìm thấy hướng đi trong bầu trời đêm."
