  Stage_81208_Name = {
    Text = "Bản đồ sao hoang tàn·Phần bố"
  },
  Stage_81209_Desc = {
    Text = "Bản đồ hàng hải cổ này bị vẽ kín mít, ghi lại mọi trải nghiệm mà tất cả những người sở hữu nó kể từ khi nó ra đời."
  },
  Stage_81209_Name = {
    Text = "Bản đồ cổ·Sáu"
  },
  Stage_8120_Desc = {
    Text = "Nguy hiểm đến từ bên trong."
  },
  Stage_8120_Name = {
    Text = "Mối nguy hiểm tiềm ẩn"
  },
  Stage_81210_Desc = {
