  },
  Stage_8125_Desc = {
    Text = "Điều hoành hành ở đây không phải là một căn bệnh thông thường."
  },
  Stage_8125_Name = {Text = "Bệnh"},
  Stage_8126_Desc = {
    Text = "Bạn và Ramona đến Bệnh viện Từ thiện Lily ở phía đông Lentiennam, để bắt đầu cuộc điều tra đầu tiên của bạn với tư cách là một Người Giữ Gìn mới. \nMọi thứ sẽ suôn sẻ, phải không?"
  },
  Stage_8126_Name = {
    Text = "Đừng trông mặt mà bắt hình dong"
  },
  Stage_8127_Desc = {
    Text = "Ma quỷ ẩn náu trong bóng tối —— dưới đất hay trong lòng người."
  },
  Stage_8127_Name = {
    Text = "Hồn ma trong lòng đất"
  },
  Stage_8128_Desc = {
    Text = "Không có oxy để hô hấp, không có ánh sáng le loe như đầu que diêm, đây là giấc mơ hoàn toàn tối tăm."
  },
  Stage_8128_Name = {
    Text = "Giấc mơ đen"
  },
  Stage_8129_Desc = {
    Text = "\"Mỗi chìa khóa đều có một con số độc nhất, và cũng chỉ thuộc về một điều tra viên duy nhất.\" \n\"Điều đó cũng đồng nghĩa rằng, thời khắc chìa khóa rơi xuống cũng đánh dấu cái chết của điều tra viên sở hữu nó.\" \n\"Điều này tuyệt vời làm sao, vì ngay cả cái chết cũng là độc nhất vô nhị.\""
  },
  Stage_8129_Name = {
    Text = "Thâm Nhập Mộng Ảo VII"
  },
