  },
  Stage_8139_Desc = {
    Text = "Di chuyển, chảy tràn... những bong bóng chất nguyên sinh đang lọt qua khe hở của xiềng xích. \nĐây là cái giá mà cô phải trả cho \"tự do\"."
  },
  Stage_8139_Name = {
    Text = "Dây xích hắc ám IV"
  },
  Stage_8140_Desc = {
    Text = "Chúng vặn vẹo, hòa quyện trong bóng tối, rồi được cẩn thận bảo quản trong tượng. \nĐây là một cuộc hội ngộ đã được dự mưu từ lâu."
  },
  Stage_8140_Name = {
    Text = "Vùng Hỗn Loạn · Khe hở V"
  },
  Stage_8141_Desc = {
    Text = "Đây là nơi ngủ say của một thành phố cổ xưa. \nNó thích ngủ như chủ nhân của nó."
  },
  Stage_8141_Name = {
    Text = "Bona Phe Ruins III"
  },
  Stage_8142_Desc = {
    Text = "Là điều gì đã che mờ đôi mắt của cô ấy? \n Là tình yêu, lòng thương xót, công lý và sự biết ơn quá mức sao?"
  },
  Stage_8142_Name = {
    Text = "Vượt thoát"
  },
  Stage_8143_Desc = {
    Text = "Đầu nhọn sắc bén phá vỡ đường tròn tuyệt đối, không phải vật của \"Cerberus\" sinh ra từ khe nứt."
  },
  Stage_8143_Name = {
    Text = "Vết nứt trên vỏ"
  },
  Stage_8144_Desc = {
    Text = "Làm thế nào có hoàng hôn vĩnh viễn không lặn?"
  },
  Stage_8144_Name = {
    Text = "Hoàng hôn"
  },
  Stage_8145_Desc = {
    Text = "\"Bàn Tay\" vén lên bức màn của đêm đen, lặng lẽ tiến vào thế giới này."
  },
  Stage_8145_Name = {
    Text = "Thâm Nhập Mộng Ảo I"
  },
  Stage_8146_Desc = {
    Text = "Những pho tượng có nguồn gốc không rõ ràng lang thang, run rẩy trong bóng tối. \nChúng bước theo nhịp điệu cổ xưa, nhảy múa theo tiếng sáo từ xa vọng lại."
  },
  Stage_8146_Name = {
    Text = "Di sản của Biển Sâu · Khe hở II"
  },
  Stage_8147_Desc = {
    Text = "Bộp bộp, nứt ra rồi. \nbộp bộp, gãy rồi."
  },
  Stage_8147_Name = {
    Text = "Bảo tàng Búp bê"
  },
  Stage_8148_Desc = {
    Text = "\"cửa\"đã được mở, ảo mộng sắp tỉnh giấc. \n Suỵt... đừng nhìn, đừng nghe."
  },
  Stage_8148_Name = {
    Text = "Vùng Hỗn Loạn · Khe Hở Luân Chuyển IV"
  },
  Stage_8149_Desc = {
    Text = "\"cửa\"đã được mở, ảo mộng sắp tỉnh giấc. \n Suỵt... đừng nhìn, đừng nghe."
  },
  Stage_8149_Name = {
    Text = "Vùng Hỗn Loạn · Khe Hở Luân Chuyển IV"
  },
  Stage_8150_Desc = {
    Text = "\"cửa\"đã được mở, ảo mộng sắp tỉnh giấc. \n Suỵt... đừng nhìn, đừng nghe."
  },
  Stage_8150_Name = {
    Text = "Vùng Hỗn Loạn · Khe Hở Luân Chuyển IV"
  },
  Stage_8151_Desc = {
    Text = "Cảm giác quen thuộc và thực tại đang xé Người Giữ Gìn thành hai nửa, một nửa dành cho ký ức, một nửa ở ngay trước mắt."
  },
  Stage_8151_Name = {Text = "Dao găm"},
  Stage_8152_Desc = {
    Text = "Cảng biển về đêm, người dân chân chất, sự đón tiếp nồng hậu."
  },
  Stage_8152_Name = {
    Text = "Vây hãm tứ phía"
  },
  Stage_8153_Desc = {
    Text = "Câu chuyện mở đầu quen thuộc: một Người Giữ Gìn cô độc mất trí nhớ. \nKhác biệt là, lần này anh ta tỉnh dậy giữa đại dương mênh mông, nơi chỉ có một mình."
  },
  Stage_8153_Name = {Text = "Mắt bão"},
  Stage_8154_Desc = {
    Text = "Sứ đồ vượt qua muôn biển."
  },
  Stage_8154_Name = {Text = "Sứ đồ"},
  Stage_8155_Desc = {
    Text = "Trên một con tàu, ngoài thuyền trưởng, thì ai còn đáng tin cậy?"
  },
  Stage_8155_Name = {
    Text = "Thủy thủ"
  },
  Stage_8156_Desc = {
    Text = "Khi không còn đường lui, người bạn được đào tạo bài bản thường là chìa khóa để phá vỡ thế bế tắc — Ramona đã dạy bạn điều này một lần nữa."
  },
  Stage_8156_Name = {
    Text = "Không lối thoát"
  },
  Stage_8157_Desc = {
    Text = "Đạp vỡ muôn biển mà qua, ngoài kẻ thù, có lẽ còn có ánh sáng hy vọng."
  },
  Stage_8157_Name = {
    Text = "Kẻ sa đà"
  },
  Stage_8158_Desc = {
    Text = "Đó là thanh kiếm khổng lồ của người muốn xé toạc đại dương, là khát vọng chế ngự mọi biển cả."
  },
  Stage_8158_Name = {
    Text = "Kẻ cuồng nộ và đại kiếm"
  },
  Stage_8159_Desc = {
    Text = "Đó là cơn ác mộng không thể xóa nhòa của cô, cũng là thực tế biến dạng đeo bám cô suốt cuộc đời."
  },
  Stage_8159_Name = {
    Text = "Thực tại bị bóp méo"
  },
  Stage_8160_Desc = {
    Text = "Chúng vặn vẹo, hòa quyện trong bóng tối, rồi được cẩn thận bảo quản trong tượng. \nĐây là một cuộc hội ngộ đã được dự mưu từ lâu."
  },
  Stage_8160_Name = {
    Text = "Chuyến đi Siêu việt·Khe hở V"
  },
  Stage_8161_Desc = {
    Text = "Lentiennam nổi tiếng với nền văn minh công nghiệp rực rỡ và lớp sương mù màu chì xám bao phủ thành phố. \nSương mù hiện diện khắp nơi, đối với người đi đường, nó giống như một sự bất tiện ngẫu nhiên và không đáng kể."
  },
  Stage_8161_Name = {
    Text = "Thành phố sương quái IV"
  },
  Stage_8162_Desc = {
    Text = "Cảnh quan uốn cong ẩn sâu trong vũ trụ. \nNó có thể đưa bạn từ bóng tối đến một bóng tối khác."
  },
  Stage_8162_Name = {
    Text = "Họng Schwarzschild IV"
  },
  Stage_8163_Desc = {
    Text = "Hư vô là cội nguồn của chúng ta, cũng là chốn quay về của chúng ta."
  },
  Stage_8163_Name = {
    Text = "Lời thì thầm bất diệt"
  },
  Stage_8164_Desc = {
    Text = "Dưới cây cầu đường sắt hoang vu, một con quái vật khổng lồ, mập mạp phát ra những tiếng gầm thấp kỳ quái. Để đến được viện điều dưỡng tâm thần Rai, phải vượt qua nơi đây."
  },
  Stage_8164_Name = {
    Text = "Đến chân cầu, đường sẽ rõ"
  },
  Stage_8165_Desc = {
    Text = "Elworth nằm ở cực điểm của cà đa sác, quanh năm bị phủ bởi tuyết băng không tan, \ndưới lớp băng dày và cứng cáp, ẩn chứa những nhịp đập của sức sống."
  },
  Stage_8165_Name = {
    Text = "Dãy núi Mất trật tự I"
  },
  Stage_8166_Desc = {
    Text = "Những pho tượng có nguồn gốc không rõ ràng lang thang, run rẩy trong bóng tối. \nChúng bước theo nhịp điệu cổ xưa, nhảy múa theo tiếng sáo từ xa vọng lại."
  },
  Stage_8166_Name = {
    Text = "Vùng Hỗn Loạn Khe Hở VIII"
  },
  Stage_8167_Desc = {
    Text = "\"Nó là duy nhất. Nó là tất cả. Nó là hi vọng để mở ra cánh cổng Chân Lý.\"\nVô số chìa khóa tụ thành một vòng tròn. Chúng từ bầu trời rơi xuống, đem đến hi vọng nặng trĩu cho nhân loại.\nCũng như, những nấm mồ nặng tựa Thái Sơn."
  },
  Stage_8167_Name = {
    Text = "Thâm Nhập Mộng Ảo IV"
  },
  Stage_8168_Desc = {
    Text = "\"Cửa\" sắp mở ra, bạn nhìn thấy một phần sự thật. \nKhông phải màu đen, cũng không phải màu trắng — sự thật là đa sắc màu, cũng như mờ đục."
  },
  Stage_8168_Name = {
    Text = "Đầm lầy thịt máu · khe hở III"
  },
  Stage_8169_Desc = {
    Text = "\"Nó là duy nhất. Nó là tất cả. Nó là hi vọng để mở ra cánh cổng Chân Lý.\"\nVô số chìa khóa tụ thành một vòng tròn. Chúng từ bầu trời rơi xuống, đem đến hi vọng nặng trĩu cho nhân loại.\nCũng như, những nấm mồ nặng tựa Thái Sơn."
  },
  Stage_8169_Name = {
    Text = "Thâm Nhập Mộng Ảo VI"
  },
  Stage_8170_Desc = {
    Text = "\"Nó là duy nhất. Nó là tất cả. Nó là hi vọng để mở ra cánh cổng Chân Lý.\"\nVô số chìa khóa tụ thành một vòng tròn. Chúng từ bầu trời rơi xuống, đem đến hi vọng nặng trĩu cho nhân loại.\nCũng như, những nấm mồ nặng tựa Thái Sơn."
  },
  Stage_8170_Name = {
    Text = "Thâm Nhập Mộng Ảo VII"
  },
  Stage_8171_Desc = {
    Text = "\"Nó là duy nhất. Nó là tất cả. Nó là hi vọng để mở ra cánh cổng Chân Lý.\"\nVô số chìa khóa tụ thành một vòng tròn. Chúng từ bầu trời rơi xuống, đem đến hi vọng nặng trĩu cho nhân loại.\nCũng như, những nấm mồ nặng tựa Thái Sơn."
  },
  Stage_8171_Name = {
    Text = "Thâm Nhập Mộng Ảo I"
  },
  Stage_8172_Desc = {
    Text = "\"Nó là duy nhất. Nó là tất cả. Nó là hi vọng để mở ra cánh cổng Chân Lý.\"\nVô số chìa khóa tụ thành một vòng tròn. Chúng từ bầu trời rơi xuống, đem đến hi vọng nặng trĩu cho nhân loại.\nCũng như, những nấm mồ nặng tựa Thái Sơn."
  },
  Stage_8172_Name = {
    Text = "Thâm Nhập Mộng Ảo II"
  },
  Stage_8173_Desc = {
    Text = "Những pho tượng có nguồn gốc không rõ ràng lang thang, run rẩy trong bóng tối. \nChúng bước theo nhịp điệu cổ xưa, nhảy múa theo tiếng sáo từ xa vọng lại."
  },
  Stage_8173_Name = {
    Text = "Siêu việt chi lữ · Khe hở II"
  },
  Stage_8174_Desc = {
    Text = "Ông ấy không phải là Ngài, Ngài không thể là ông ấy. \nĐúng vậy… Đúng vậy, chỉ có thần minh của tôi mới là đấng chân chính."
  },
  Stage_8174_Name = {
    Text = "Ánh sáng thất lạc"
  },
  Stage_81757_Desc = {
    Text = "Vùng đất thần thánh lấp lánh dần hiện ra trong đôi mắt bạn đang mở to.\nỞ đó, bạn sẽ nhận được sự hứa hẹn, sở hữu mọi thứ."
  },
  Stage_81757_Name = {
    Text = "Tiếng thì thầm từ vùng đất thần thánh"
  },
  Stage_81758_Desc = {
    Text = "Thông qua bức điêu khắc ngà voi đó, ánh mắt của Người đã hạ xuống nhân gian.\nTừ đó, cả hai chúng ta đều chìm đắm trong ý chí của Người."
  },
  Stage_81758_Name = {
    Text = "Ánh nhìn của thánh tượng"
  },
  Stage_81759_Desc = {
    Text = "Vũ trụ vô hạn hội tụ trong cơ thể của ngươi, như những vì sao lao về khoảnh khắc liên kết.\nHãy đáp lại tiếng gọi từ hư không này! Con của Ngài. Con rối của Ngài."
  },
  Stage_81759_Name = {
    Text = "Sự triệu hồi của hư vô"
  },
  Stage_8175_Desc = {
    Text = "Hiện thực đã gieo rắc mầm họa, nhưng số phận lại dẫn lối cho cuộc gặp gỡ."
  },
  Stage_8175_Name = {
    Text = "Hạt giống định mệnh"
  },
  Stage_81760_Desc = {
    Text = "Khe hở giữa ảo tưởng và thực tại, nghi lễ đã bắt đầu.\nHãy hô vang, hét lên, niềm vui và nỗi đau của bạn sẽ vượt qua chiều không gian, trở thành bài ca ca ngợi sự đến của vùng đất thần thánh."
  },
  Stage_81760_Name = {
    Text = "Phản hồi lễ tế"
  },
  Stage_81761_Desc = {
    Text = "Tất cả niềm hoan hỉ đã qua.\nBạn kéo theo thân thể bị chia rẽ, giơ tay ra, phát ra tiếng gầm rú đầu tiên kinh hoàng và báng bổ của thế giới sau khi tỉnh thức.\n\n \"Vùng đất thần thánh cuối cùng sẽ đến.\""
  },
  Stage_81761_Name = {
    Text = "Tín phụ mơ hồ"
  },
  Stage_81762_Desc = {
    Text = "Ah, lắng nghe âm thanh hỗn loạn này, lắng nghe bản nhạc ảo diệu vô tận.\nThần linh đã ban xuống thánh chỉ, và bạn với tư cách là con cháu và con rối của Ngài, sẽ trung thành thực hiện đến cùng."
  },
  Stage_81762_Name = {
    Text = "Thánh chỉ của Thần Vương"
  },
  Stage_81763_Desc = {
    Text = "Nhịp tim tăng tốc chỉ là dấu hiệu của sự rối loạn trong cơ thể.\nKhông cần phải hoảng sợ, đó chỉ là âm thanh của dòng máu bạn đang Tỉnh thức."
  },
  Stage_81763_Name = {
    Text = "Sự run rẩy của xác thịt"
  },
  Stage_8176_Desc = {
    Text = "Trái tim thứ hai trong cơ thể Muphí đang đập, ngăn chặn \"Nghi lễ Giáng Sinh\"đang trở nên cấp bách."
  },
  Stage_8176_Name = {
    Text = "Một kỳ tích khác"
  },
  Stage_8177_Desc = {
    Text = "Vượt qua vòng vây chưa bao giờ là dễ dàng, nhưng may mắn thay, lần này Người Giữ Gìn đã tìm thấy ngôi sao sáng nhất."
  },
  Stage_8177_Name = {
    Text = "Đuổi theo những vì sao"
  },
  Stage_81781_Desc = {
    Text = "Vào thời khắc thảm họa vô hình sống lại, lịch sử và hiện tại của thế giới vật chất dần chìm vào tận cùng vực sâu."
  },
  Stage_81781_Name = {
    Text = "Vùng cấm hòa hợp với thiên tai·Sóng 3·Điên loạn"
  },
  Stage_81782_Desc = {
    Text = "Vào thời khắc thảm họa vô hình sống lại, lịch sử và hiện tại của thế giới vật chất dần chìm vào tận cùng vực sâu."
  },
  Stage_81782_Name = {
    Text = "Vùng cấm hòa hợp với thiên tai·Sóng thứ 2·Điên loạn"
  },
  Stage_81783_Desc = {
    Text = "Vào thời khắc thảm họa vô hình sống lại, lịch sử và hiện tại của thế giới vật chất dần chìm vào tận cùng vực sâu."
  },
  Stage_81783_Name = {
    Text = "Vùng cấm hòa hợp với thiên tai·Sóng 1·Điên loạn"
  },
  Stage_81784_Desc = {
    Text = "Vào thời khắc thảm họa vô hình sống lại, lịch sử và hiện tại của thế giới vật chất dần chìm vào tận cùng vực sâu."
  },
  Stage_81784_Name = {
    Text = "Vùng cấm hòa hợp với thiên tai·Sóng thứ 5·Điên loạn"
  },
  Stage_81785_Desc = {
    Text = "Vào thời khắc thảm họa vô hình sống lại, lịch sử và hiện tại của thế giới vật chất dần chìm vào tận cùng vực sâu."
  },
  Stage_81785_Name = {
    Text = "Vùng cấm hòa hợp với thiên tai·Sóng thứ 4·Điên loạn"
  },
  Stage_81786_Desc = {
    Text = "Thủy Triều Đen đã dâng trào vượt quá ranh giới cảnh báo; giờ đây một gợn sóng nhỏ nhất cũng là mối nguy khôn lường, sẵn sàng nuốt chửng những kẻ thiếu cảnh giác."
  },
  Stage_81786_Name = {
    Text = "Vùng Cấm - Thảm Họa Phân Giải: Đợt Thứ Tư: Cảnh Báo Bậc 1"
  },
  Stage_81787_Desc = {
