  Stage_88880_Desc = {
    Text = "Tôi giữ ngọn lửa mà bạn đã thắp sáng.\n Bạn đã dẫn dắt tôi, tôi sẽ trở thành mắt của bạn, giúp bạn thấy ánh sáng trở lại.\n Con đường mà bạn đã đi, tôi sẽ tiếp bước cho bạn, tất cả mọi hàng rào gỉ sét sẽ sụp đổ trước ngọn lửa này."
  },
  Stage_88880_Name = {
    Text = "Người truyền nến · Ba"
  },
  Stage_88881_Desc = {
    Text = "Một thành phố đang ngưng lại, đã hóa thành một mẫu vật của nền văn minh."
  },
  Stage_88881_Name = {
    Text = "Mẫu vật"
  },
  Stage_88882_Desc = {
    Text = "Anh sinh ra đã ngốc nghếch, chậm chạp, bị giam hãm trong cuộc sống đơn giản, mù quáng và bướng bỉnh.\nNhưng ai nói kẻ ngu ngốc không thể mở ra một con đường hoàn toàn mới? Tất cả sự giam cầm chỉ là cơn bão chưa nở rộ, dù anh hoàn toàn không biết gì, vẫn có thể vững vàng bay về phía bầu trời chưa được biết đến."
  },
  Stage_88882_Name = {
    Text = "Kẻ ngu ngốc·Điên loạn"
  },
  Stage_88883_Desc = {
    Text = "Tôi đã mơ về những ngày xưa xa xưa.\nKhi đó bạn chỉ vào những vì sao sâu thẳm như được trải trên tấm nhung xanh, nói rằng sau này sẽ chọn một đêm quang đãng, cùng nhau bay bên cạnh mặt trăng, xem rốt cuộc bầu trời có phong cảnh như thế nào."
  },
  Stage_88883_Name = {
    Text = "Giấc mơ hôm qua · sáu"
  },
  Stage_88884_Desc = {
    Text = "Anh ấy luôn có hai cái bóng, và giờ đây anh ấy đã làm mất đi một cái.\nAnh đơn độc đi trên bầu trời tĩnh lặng, cất lên những bài hát thuở nhỏ mà anh đã cùng nhau sáng tác.\nChim bay, chim bay, bạn ở đâu... \nBóng, bóng, hãy về nhà..."
  },
  Stage_88884_Name = {
    Text = "Hành trình cô đơn·Phần năm"
  },
  Stage_88885_Desc = {
    Text = "Tôi giữ ngọn lửa mà bạn đã thắp sáng.\n Bạn đã dẫn dắt tôi, tôi sẽ trở thành mắt của bạn, giúp bạn thấy ánh sáng trở lại.\n Con đường mà bạn đã đi, tôi sẽ tiếp bước cho bạn, tất cả mọi hàng rào gỉ sét sẽ sụp đổ trước ngọn lửa này."
  },
  Stage_88885_Name = {
    Text = "Người truyền nến · Bốn"
  },
  Stage_88886_Desc = {
