  Stage_88890_Name = {
    Text = "Người truyền nến · Sáu"
  },
  Stage_88891_Desc = {
    Text = "Cát như biển, khi gió ngừng lại, sóng sẽ lặng im; khi gió nổi lên, sinh linh đều diệt vong.\nAnh ấy như một con hải âu bất khuất bay giữa biển cát vô tận."
  },
  Stage_88891_Name = {
    Text = "Vô tận cát · một"
  },
  Stage_88892_Desc = {
    Text = "Cát như biển, khi gió ngừng lại, sóng sẽ lặng im; khi gió nổi lên, sinh linh đều diệt vong.\nAnh ấy như một con hải âu bất khuất bay giữa biển cát vô tận."
  },
  Stage_88892_Name = {
    Text = "Vô tận cát · sáu"
  },
  Stage_88893_Desc = {
    Text = "Kể từ khi anh mở mắt, đôi mắt ấy không thể nào khép lại nữa.\nKể từ khi anh đã thấy bầu trời, bầu trời ấy vẫn luôn ở trong lòng.\nNếu tự do phải đổi bằng cái chết, anh sẽ không chần chừ mà hi sinh chính mạng sống của mình."
  },
  Stage_88893_Name = {
    Text = "Tự do và cái chết·Ba"
  },
  Stage_88894_Desc = {
    Text = "Anh sinh ra đã ngốc nghếch, chậm chạp, bị giam hãm trong cuộc sống đơn giản, mù quáng và bướng bỉnh.\nNhưng ai nói kẻ ngu ngốc không thể mở ra một con đường hoàn toàn mới? Tất cả sự giam cầm chỉ là cơn bão chưa nở rộ, dù anh hoàn toàn không biết gì, vẫn có thể vững vàng bay về phía bầu trời chưa được biết đến."
  },
