    Text = "Cấu trúc của sa mạc là: nóng bức, khô cằn, gió và cát, những cồn cát kéo dài vô tận, loài bò sát nhanh nhẹn, cây xương rồng, và một mỹ nhân có làn da mịn màng như mật."
  },
  Stage_88924_Name = {
    Text = "Cát và mật"
  },
  Stage_88925_Desc = {
    Text = "Tôi giữ ngọn lửa mà bạn đã thắp sáng.\n Bạn đã dẫn dắt tôi, tôi sẽ trở thành mắt của bạn, giúp bạn thấy ánh sáng trở lại.\n Con đường mà bạn đã đi, tôi sẽ tiếp bước cho bạn, tất cả mọi hàng rào gỉ sét sẽ sụp đổ trước ngọn lửa này."
  },
  Stage_88925_Name = {
    Text = "Người truyền nến · Điên cuồng"
  },
  Stage_88926_Desc = {
    Text = "Nếu sinh ra trong lồng, vậy thì thật sự sinh ra để bị trói? \nNếu chôn sâu dưới đất, lại quyết tâm phá đất tái sinh."
  },
  Stage_88926_Name = {
    Text = "Phá vỡ nhà tù·phần hai"
  },
  Stage_88927_Desc = {
    Text = "Cát như biển, khi gió ngừng lại, sóng sẽ lặng im; khi gió nổi lên, sinh linh đều diệt vong.\nAnh ấy như một con hải âu bất khuất bay giữa biển cát vô tận."
  },
  Stage_88927_Name = {
    Text = "Vô tận cát · ba"
  },
  Stage_88928_Desc = {
    Text = "Kể từ khi anh mở mắt, đôi mắt ấy không thể nào khép lại nữa.\nKể từ khi anh đã thấy bầu trời, bầu trời ấy vẫn luôn ở trong lòng.\nNếu tự do phải đổi bằng cái chết, anh sẽ không chần chừ mà hi sinh chính mạng sống của mình."
  },
  Stage_88928_Name = {
    Text = "Tự do và cái chết·Sáu"
  },
  Stage_88929_Desc = {
    Text = "Kể từ khi anh mở mắt, đôi mắt ấy không thể nào khép lại nữa.\nKể từ khi anh đã thấy bầu trời, bầu trời ấy vẫn luôn ở trong lòng.\nNếu tự do phải đổi bằng cái chết, anh sẽ không chần chừ mà hi sinh chính mạng sống của mình."
  },
  Stage_88929_Name = {
    Text = "Tự do và cái chết·Hai"
  },
  Stage_88930_Desc = {
    Text = "Anh ấy luôn có hai cái bóng, và giờ đây anh ấy đã làm mất đi một cái.\nAnh đơn độc đi trên bầu trời tĩnh lặng, cất lên những bài hát thuở nhỏ mà anh đã cùng nhau sáng tác.\nChim bay, chim bay, bạn ở đâu... \nBóng, bóng, hãy về nhà..."
  },
  Stage_88930_Name = {
    Text = "Hành trình cô đơn·Phần một"
  },
  Stage_88931_Desc = {
    Text = "Tôi giữ ngọn lửa mà bạn đã thắp sáng.\n Bạn đã dẫn dắt tôi, tôi sẽ trở thành mắt của bạn, giúp bạn thấy ánh sáng trở lại.\n Con đường mà bạn đã đi, tôi sẽ tiếp bước cho bạn, tất cả mọi hàng rào gỉ sét sẽ sụp đổ trước ngọn lửa này."
  },
  Stage_88931_Name = {
    Text = "Người truyền nến · Một"
  },
  Stage_88932_Desc = {
    Text = "Anh sinh ra đã ngốc nghếch, chậm chạp, bị giam hãm trong cuộc sống đơn giản, mù quáng và bướng bỉnh.\nNhưng ai nói kẻ ngu ngốc không thể mở ra một con đường hoàn toàn mới? Tất cả sự giam cầm chỉ là cơn bão chưa nở rộ, dù anh hoàn toàn không biết gì, vẫn có thể vững vàng bay về phía bầu trời chưa được biết đến."
  },
  Stage_88932_Name = {
    Text = "Kẻ ngu ngốc·Năm"
  },
  Stage_89731_Desc = {
    Text = "Giọt nước mắt rơi nhẹ nhàng, trong suốt như hoa băng tinh khiết."
  },
  Stage_89731_Name = {
    Text = "Một giọt nước mắt"
  },
  Stage_89732_Desc = {
    Text = "Chạy, trốn, truy đuổi, kéo kéo, thợ săn đã giơ lên khẩu súng đen ngòm."
  },
  Stage_89732_Name = {
    Text = "Đến săn"
  },
  Stage_90490_Desc = {
    Text = "Thể Thức Tỉnh sinh ra từ hỗn loạn đứng cùng bạn, Chìa Khóa Bạc của bạn phát ra tiếng rung hưng phấn.\nChiến đấu cùng họ, nắm vững phương pháp kích phát tiềm năng của Chìa Khóa Bạc."
  },
  Stage_90490_Name = {
    Text = "Ý Niệm Hỗn Loạn"
  },
  Stage_90662_Desc = {
    Text = "Khi tiếng chuông nghĩa trang vang lên, những làn sương đen sẽ tan biến trong giấc mơ. \nHãy mở nắp quan tài nặng nề, thành phố hoàng gia hùng vĩ đã đổ xuống trước mặt bạn."
  },
  Stage_90662_Name = {
    Text = "Dưới giấc mơ"
  },
  Stage_90663_Desc = {
    Text = "Hãy lắng nghe, tiếng khóc của đại dương.\nNhững tín đồ thành tâm cầu xin. Cầu xin Chúa hồi đáp lời cầu nguyện của họ, cầu xin Chúa ban thưởng cho máu của họ."
  },
  Stage_90663_Name = {
    Text = "Lễ tế máu"
  },
  Stage_90664_Desc = {
    Text = "\"Xác xương ngủ yên nơi đây, linh hồn lang thang giữa trời đêm —\nDưới danh nghĩa của vua xác sống, chúa tể của thành phố chôn cất, tôi sẽ mời gọi các bạn, trở về quê hương mà các bạn yêu quý.\nTôi sẽ mời gọi các bạn cùng tôi, thưởng thức bữa tiệc do kẻ thù ban tặng!\""
  },
  Stage_90664_Name = {
    Text = "Vũ điệu của vạn linh"
  },
  Stage_90665_Desc = {
    Text = "Lời thề gắn bó lâu dài đã có từ trước khi tận tâm phụng sự."
  },
  Stage_90665_Name = {
    Text = "Lời thề"
  },
  Stage_90666_Desc = {
    Text = "Tội lỗi? Âm mưu? Cái chết? \nHọa sĩ không có thời gian để quan tâm đến những điều này. Trong mắt ông, chỉ có cảnh tượng hoành tráng được tạo ra từ những xác chết."
  },
  Stage_90666_Name = {Text = "Hoạ sĩ"},
  Stage_90667_Desc = {
    Text = "Lời thề gắn bó lâu dài đã có từ trước khi tận tâm phụng sự."
  },
  Stage_90667_Name = {
    Text = "Lời thề"
  },
  Stage_90670_Desc = {
    Text = "Trong tất cả những phẩm chất của quân chủ thành phố mồ mả, sự thưởng thức ẩm thực là điều quan trọng nhất."
  },
  Stage_90670_Name = {
    Text = "Nghệ thuật nấu ăn của vua với xác chết"
  },
  Stage_90671_Desc = {
    Text = "Một ký ức của một người thân. Một câu chuyện của một hoàng tộc thành phố. Một đoạn lịch sử nặng nề tráng lệ.\nMột ký ức của một người bình dân. Một câu chuyện của một gia đình bình thường. Một chú thích có thể có hoặc không.\nĐối với vua của thành phố chôn cất, chúng không nên và cũng sẽ không có bất kỳ sự khác biệt nào."
  },
  Stage_90671_Name = {
    Text = "Chú thích hèn mọn"
  },
  Stage_90672_Desc = {
    Text = "\"Nhạc dây đã văng lên giữa trời, mọi nghi lễ phức tạp đã tản mác theo sắc sương.\nNhững thần dân yêu dấu của tôi, hãy hoan hô. Xé rách lớp vải bao xác chết, để lộ ra bản nguyên của cơn đói khao.\nĐêm nay, thanh âm của thi sĩ sẽ vang lên cho chúng ta.\nĐêm nay, vòng tay của mẹ sẽ ôm chúng ta vào lòng.\""
  },
  Stage_90672_Name = {
    Text = "Ánh trăng, xương cốt và điệu múa"
  },
  Stage_90674_Desc = {
    Text = "Ông là vị vua của thành phố Chôn Xác. Ông là chủ của bữa tiệc này.\nÔng giang tay chào đón tất cả khách mời, mời họ rời khỏi sàn nhảy.\nTrên những xác chết khắp nghĩa trang, ông cùng với vực thẳm khiêu vũ."
  },
  Stage_90674_Name = {
    Text = "Chúa Tể Táng Hài"
  },
  Stage_90676_Desc = {
    Text = "Khi tiếng chuông nghĩa trang vang lên, những làn sương đen sẽ tan biến trong giấc mơ. \nHãy mở nắp quan tài nặng nề, thành phố hoàng gia hùng vĩ đã đổ xuống trước mặt bạn."
  },
  Stage_90676_Name = {
    Text = "Dưới giấc mơ"
  },
  Stage_90679_Desc = {
    Text = "Trong tất cả những phẩm chất của quân chủ thành phố mồ mả, sự thưởng thức ẩm thực là điều quan trọng nhất."
  },
  Stage_90679_Name = {
    Text = "Nghệ thuật nấu ăn của vua với xác chết"
  },
  Stage_90680_Desc = {
    Text = "Giọng nói trong giấc mơ, nền văn minh bị lãng quên, dấu vết của bạn bè cũ...\nTất cả những gì bạn muốn biết đang chờ bạn xa ngoài biển khơi."
  },
  Stage_90680_Name = {
    Text = "Trên biển xa"
  },
  Stage_90681_Desc = {
    Text = "Hãy lắng nghe, tiếng khóc của đại dương.\nNhững tín đồ thành tâm cầu xin. Cầu xin Chúa hồi đáp lời cầu nguyện của họ, cầu xin Chúa ban thưởng cho máu của họ."
  },
  Stage_90681_Name = {
    Text = "Lễ tế máu"
  },
  Stage_90684_Desc = {
    Text = "Người ăn xác này già nua trước mặt là ai? Tại sao y lại ăn mặc tả tơi? Tại sao y lại khóc lóc? \nTại sao y lại khóc, với giọng nói nhẹ nhàng và khàn khàn gọi tên Elena? \nCô ấy không nhớ gì cả. \nÁnh trăng chiếu lên thi thể cô, đẹp như ngày cưới, vải voan trên người cô bay bổng theo gió."
  },
  Stage_90684_Name = {
    Text = "Đám cưới và tang lễ"
  },
  Stage_90685_Desc = {
    Text = "Người ăn xác này già nua trước mặt là ai? Tại sao y lại ăn mặc tả tơi? Tại sao y lại khóc lóc? \nTại sao y lại khóc, với giọng nói nhẹ nhàng và khàn khàn gọi tên Elena? \nCô ấy không nhớ gì cả. \nÁnh trăng chiếu lên thi thể cô, đẹp như ngày cưới, vải voan trên người cô bay bổng theo gió."
