  Stage_90997_Name = {
    Text = "Tiếng gọi xa xăm·3"
  },
  Stage_90998_Desc = {
    Text = "Dù món mồi ẩn nấp ở đâu, thợ săn chuyên nghiệp sẽ ngửi thấy thứ hương thơm ngọt ngào đó."
  },
  Stage_90998_Name = {
    Text = "Thợ săn mãnh liệt · thứ sáu"
  },
  Stage_90999_Desc = {
    Text = "Tiếng chuông chinh phục đã vang lên, các chiến binh đã lên đường.\nChúng ta tiến về phía trước, không thể ngăn cản, chúng ta nhất định sẽ chiến thắng."
  },
  Stage_90999_Name = {
    Text = "Kèn lệnh viễn chinh·Thứ năm"
  },
  Stage_91000_Desc = {
    Text = "Tiếng hoan hô và hoa tươi, rượu ngon và tiệc tùng, vàng và bảo vật.\nHãy tận hưởng, hãy cười thật to, đây là vinh quang mà các chiến binh đáng được nhận!"
  },
  Stage_91000_Name = {
    Text = "Vinh quang trở lại·2"
  },
  Stage_91001_Desc = {
    Text = "Tôi thừa nhận chúng ta đã có một số mâu thuẫn trong quá khứ, nhưng điều đó không cản trở chúng ta tạm thời cùng nhắm vào công nghệ hiện đại đáng ghét, tởm lợm và hèn hạ này."
  },
  Stage_91001_Name = {
    Text = "Trí tuệ hợp tác · thứ tư"
  },
  Stage_91002_Desc = {
    Text = "Tất cả những kẻ cản trở sẽ cúi đầu bởi nỗi sợ hãi, mọi ánh sáng đều hướng về Roma.\nVòng hoa trắng và lá nguyệt quế sẽ được đội lên đầu những chiến binh dũng cảm nhất."
  },
