  Stage_97622_Desc = {
    Text = "Thần đã tách trời với đất, đất với biển.\nBầu trời rủ xuống màn vải dày nhầy nhụa và quay cuồng, hơi thở của lưu huỳnh và muối biển bay lên trong Vực thẳm.\nNgài ban cho con dân của biển quyền đi khắp nơi."
  },
  Stage_97622_Name = {
    Text = "Ngày thứ hai·Bốn"
  },
  Stage_97623_Desc = {
    Text = "Tại sao thần lại mục nát, tại sao thần lại nhỏ nước mủ.\nThần linh, xin chỉ dẫn tôi, xin hãy tỉnh dậy, hãy cứu tôi——bất cứ điều gì cũng được! \nÔi, thần ơi, thần ơi…\nChỉ là những lỗi lầm vô lý và lời nói dối giả tạo."
  },
  Stage_97623_Name = {
    Text = "Ngày thứ bảy·Sáu"
  },
  Stage_97624_Desc = {
    Text = "Thần khiến hạt giống vô tri lớn lên trong thế gian.\nCó sinh vật có vây lội ngược dòng trong biển, có sinh vật có cánh bay lên trời.\nNgài ban cho lời thì thầm theo Ngài hít thở trong hải vực sâu, điên cuồng ca hát đi theo Ngài trong tầng mây."
  },
  Stage_97624_Name = {
    Text = "Ngày thứ tư · phần sáu"
  },
  Stage_97625_Desc = {
    Text = "Thần tạo ra hình thức giả tạo không trí tuệ.\nNhững vật tế được dẫn dụ để cùng chìm xuống không thể thoát khỏi số phận, thần không ban cho sự khai ngộ, thần không đáp lại, đứa trẻ không mắt không miệng mang lại giáo lý giả tạo.\nNgài ban cho kẻ tỉnh táo quyền say sưa."
  },
